  ('cpiuris2025::631e777e2a5aed23c5583acf262fa1c8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Prerrogativas dos Parlamentares', '## Prerrogativas dos Parlamentares

Os parlamentares não são obrigados a prestar testemunho sobre pessoas que lhes confiaram informações, salvo em casos constitucionais específicos.

### Conceitos
- **Prerrogativa**: Direito ou faculdade concedida a alguém
- **Testemunha**: Pessoa que fornece informações sobre um fato

### Referências legais
- Art. 221 do CPP

### Dicas de prova
- Entenda a noção de prerrogativa e sua aplicação aos parlamentares.
- Diferencie entre testemunha e parlamentar investigado/acusado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.69 (2)", "page_number": 69, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 221 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:07:21.408108+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=69", "doc_key": "631e777e2a5aed23c5583acf262fa1c8"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'fcb52cdf84e3d2812c80685bdae97b4514c7c936b4db71b895e76e6254657139'),
  ('cpiuris2025::6d33fffe9a090e5dbe5980c27c8872d9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Imunidades parlamentares', '## Imunidades parlamentares

Resumo sobre as imunidades dos parlamentares federais e estaduais, bem como os vereadores, em relação à eficácia do direito penal.

### Conceitos
- **Imunidade Diplomática**: Direito que protege os diplomatas de um país contra a aplicação da lei do seu país de origem
- **Princípio da Simetria**: Princípio constitucional que estabelece igualdade entre os membros do Congresso Nacional federal e estadual
- **Forno por Prerrogativa de Função**: Direito que concede ao parlamentar licenciado o direito de ser julgado perante a Corte Suprema

### Referências legais
- Art. 27, § 1º, da CF; Art. 29, VIII, da CF/88

### Jurisprudência
- Súmula Vinculante 45; RE 123456

### Dicas de prova
- Diferenciar entre imunidades absolutas e materiais
- Entender a aplicação do princípio da simetria
- Conhecer as regras de foro por prerrogativa de função', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.70 (1)", "page_number": 70, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 27, § 1º, da CF; Art. 29, VIII, da CF/88"], "jurisprudence": ["Súmula Vinculante 45; RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T13:07:52.946864+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=70", "doc_key": "6d33fffe9a090e5dbe5980c27c8872d9"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '9d689c730df9994f2d67ce208f16eb8d8afefab163c2692a604aadc1edc0a0b6'),
  ('cpiuris2025::d30f02799a67fd42c136217e2dfb6201', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Imunidade Diplomática', '## Imunidade Diplomática

A imunidade diplomática de Paolo é excepcionada apenas na hipótese de renúncia. Ele pode ser punido pela lei brasileira, exceto em casos de atos de ofício.

### Conceitos
- **Imunidade Diplomática**: Conceito jurídico que protege os diplomatas de penalidades por atos realizados no exercício de suas funções.
- **Renúncia**: Ação pelo qual o diplomata renuncia à sua imunidade diplomática, tornando-se sujeito às leis do Estado acreditante.
- **Atos de Ofício**: Ações realizadas por um diplomata em seu próprio interesse ou fora do exercício de suas funções.
- **Lei Brasileira**: Legislação do Brasil que regula a imunidade diplomática e as penalidades para os diplomatas.
- **Estado Acreditante**: País que reconhece o diplomata como representante de outro país.
- **Pena**: Sanção penal aplicada ao culpado em caso de condenação.
- **Isenção de Pena**: Exigência de que o culpável não seja punido com pena.

### Referências legais
- Art. 98 do Código Penal Brasileiro

### Jurisprudência
- Súmula 397/STF

### Dicas de prova
- Entenda a exceção de renúncia à imunidade diplomática.
- Distinção entre atos de ofício e atos realizados no exercício de funções.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.70 (2)", "page_number": 70, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 98 do Código Penal Brasileiro"], "jurisprudence": ["Súmula 397/STF"], "confidence": 0.8, "extracted_at": "2026-05-27T13:08:26.613611+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=70", "doc_key": "d30f02799a67fd42c136217e2dfb6201"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '43431cf9907ea1b903b4f63076b50147f3f68e8ac72ca2504d37a0e7c7bc9596'),
  ('cpiuris2025::746292c795fad062399c3eaf8092757b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Eficácia do Direito Penal em relação às pessoas', '## Eficácia do Direito Penal em relação às pessoas

Resumo objetivo: A eficácia do direito penal se refere à capacidade do Estado de punir uma pessoa por um crime cometido. O texto destaca a imunidade de jurisdição penal de agentes diplomáticos, conforme Art. 31 da Convenção de Viena sobre Relações Diplomáticas.

### Conceitos
- **Imunidade**: Conceito jurídico que se refere à isenção de responsabilidade por uma pessoa ou entidade em relação a certas ações ou decisões.
- **Jurisdição penal**: Poder do Estado para punir uma pessoa por um crime cometido.
- **Agentes diplomáticos**: Representantes de um país em outro país, que gozam de certas imunidades e isenções.

### Referências legais
- Art. 31 da Convenção de Viena sobre Relações Diplomáticas

### Dicas de prova
- Perguntas sobre imunidade e jurisdição penal podem ser complexas, mas é importante entender a distinção entre elas.
- O texto destaca a importância da Convenção de Viena sobre Relações Diplomáticas para os agentes diplomáticos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.71", "page_number": 71, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 31 da Convenção de Viena sobre Relações Diplomáticas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:09:04.020465+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=71", "doc_key": "746292c795fad062399c3eaf8092757b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ec832bbb9d15410b3e42f1e305304cc3812b3e1670779b216fadcdb33f81614c'),
  ('cpiuris2025::a376d6ab50c80ab94dc1ce84101866b2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Disposições Gerais', '## Disposições Gerais

Regulamentações sobre a eficácia de sentenças estrangeiras, contagem de prazo, frações não computáveis da pena e conflitos aparentes de normas.

### Conceitos
- **Homologação de sentença estrangeira**: Procedimento pelo qual o STJ homologa a sentença criminal proveniente de estado soberano estrangeiro
- **Exame formal**: O STJ apenas examina se a sentença é formalmente correta, sem apreciar seu mérito
- **Prazos processuais penais**: Não incluem o dia do início, mas sim o dia do vencimento, de acordo com o CPP
- **Prazos penais**: São improrrogáveis e incluem o dia do começo e excluem o dia do final
- **Frações não computáveis da pena**: As frações de dia e reais são desprezadas nas penas privativas de liberdade e multa, respectivamente
- **Conflito aparente de normas**: Ocorre quando há duas leis penais em vigor ao mesmo tempo, necessitando de interpretação para evitar conflitos

### Referências legais
- Art. 11 do CP
- Art. 45 da EC 45/2004
- Súmula 373 STJ

### Dicas de prova
- Pergunte sobre a diferença entre prazos processuais penais e prazos penais
- Entenda o conceito de homologação de sentença estrangeira e seu procedimento
- Conheça as regras para calcular frações não computáveis da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.73", "page_number": 73, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 11 do CP", "Art. 45 da EC 45/2004", "Súmula 373 STJ"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:09:48.832061+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=73", "doc_key": "a376d6ab50c80ab94dc1ce84101866b2"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c677f0b753c06a9fb92ad74e75c7b26a8c21b0d970473b52ac721f8ef93dab1d'),
  ('cpiuris2025::df3464ac6de89ecca688bea23ddf7f62', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípios para resolver conflitos entre normas penais', '## Princípios para resolver conflitos entre normas penais

Os princípios da especialidade, subsidiariedade e consunção são utilizados para resolver conflitos entre normas penais, estabelecendo a prevalência de uma norma sobre outra.

### Conceitos
- **Princípio da Especialidade**: Prevalência da lei especial sobre a geral
- **Princípio da Subsidiariedade**: Relação de menor gravidade e maior gravidade entre normas penais, com aplicação da norma mais grave quando não há subsunção do fato
- **Princípio da Consunção**: Absorção de um delito por outro

### Referências legais
- Art. 59, § 2º, inc. III, do Código Penal

### Dicas de prova
- Entenda a diferença entre princípio da especialidade e subsidiariedade
- Conheça o exemplo de infanticídio para ilustrar a aplicação do princípio da especialidade
- Aprenda a distinguir entre subsidiariedade expressa e tácita', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.74 (1)", "page_number": 74, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 59, § 2º, inc. III, do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:10:19.765741+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=74", "doc_key": "df3464ac6de89ecca688bea23ddf7f62"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '291f416b2d3b5d0c083723bff1b07c2859cf6570895118ee9bf2f08bbe72bb5f'),
  ('cpiuris2025::4b0540b29acecbeb36b762f10d93a257', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Relação entre crimes e aplicação da pena', '## Relação entre crimes e aplicação da pena

Não há relação direta entre crimes, mas a consunção pode ser aplicada para absorver o crime mais grave pelo menos grave.

### Conceitos
- **Consunção**: Princípio que permite a absorção de um crime pelo outro, quando houver relação de espécie e gênero
- **Relação de espécie e gênero**: Condição necessária para a aplicação da consunção
- **Pena do crime mais grave**: Pena que pode ser absorvida pelo menos grave em caso de consunção

### Referências legais
- Art. 68, § 2º, inciso II, do CP

### Jurisprudência
- Súmula 17 do STJ

### Dicas de prova
- Perguntas que exigem a aplicação da consunção
- Distinção entre crimes com relação de espécie e gênero', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.74 (2)", "page_number": 74, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 68, § 2º, inciso II, do CP"], "jurisprudence": ["Súmula 17 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T13:10:52.478195+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=74", "doc_key": "4b0540b29acecbeb36b762f10d93a257"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e6d09413dadb9d180da57a37ce386078ce92c399ecde55f5f5f93dc168941c75'),
  ('cpiuris2025::c1d79c9d6cc3d17aec0b3a768ee0931a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípio da Consunção', '## Princípio da Consunção

O princípio da consunção é aplicado quando uma lei atinge parte de um todo de outro crime, e deve ser aplicada a parte do crime que é o todo. Isso significa que se o agente comete um crime menos grave para alcançar um resultado mais grave, ele será responsabilizado pelo crime mais grave.

### Conceitos
- **Princípio da Consunção**: Aplicação de uma lei a parte de um todo de outro crime
- **Crime Progressivo**: O sujeito pratica um crime menos grave para alcançar um resultado mais grave
- **Progressão Criminosa**: O sujeito substitui o dolo inicial, passando de querer lesionar para querer matar

### Referências legais
- Art. 273 do CP
- Art. 33 da Lei n.º 11.343/2006

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda o princípio da consunção e sua aplicação
- Diferencie entre crime progressivo e progressão criminosa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 273 do CP", "Art. 33 da Lei n.º 11.343/2006"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T13:11:24.235309+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=75", "doc_key": "c1d79c9d6cc3d17aec0b3a768ee0931a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f6c2681c5e764938dc61c5fe4bb3f429e033287c85be6d9b248ebfb47eec2aeb'),
  ('cpiuris2025::c712200d45f97f6d26422f66b9c57828', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Impunibilidade', '## Impunibilidade

Fatos anteriores a uma ofensa mais grave não são puníveis. Exemplo: João quer furtar a televisão de José, mas a violação de domicílio é etapa do furto e não será punível.

### Conceitos
- **Impunibilidade**: Fatos anteriores a uma ofensa mais grave não são puníveis
- **Post factum impunível**: Exaurimento do crime principal após o cometimento

### Referências legais
- Art. 25, § 2º, CP

### Jurisprudência
- 7ª Turma do STJ - RE no REsp 1537773/SC
- ...

### Dicas de prova
- Entenda a diferença entre impunibilidade e post factum impunível
- Análise cuidadosa da progressão criminosa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, § 2º, CP"], "jurisprudence": ["7ª Turma do STJ - RE no REsp 1537773/SC", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T13:11:46.357815+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=75", "doc_key": "c712200d45f97f6d26422f66b9c57828"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '406294aaa4ec982d57aa7becfd6138009559e3b21b4bf7c5aa99d8856cbe21fc'),
  ('cpiuris2025::2e42f3de1e35981f442b1f21c36e9de9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípio da Subsidiariedade', '## Princípio da Subsidiariedade

O princípio da subsidiariedade estabelece que a incidência da norma principal com sanção mais grave afasta a incidência da norma subsidiária.

### Conceitos
- **Subsidiariedade**: Princípio que afasta a aplicação de uma norma subsidiária em face de uma norma principal
- **Norma Principal**: A norma com sanção mais grave
- **Norma Subsidiária**: A norma com sanção menos grave

### Referências legais
- Art. 102 do Código Penal

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Análise lógica dos elementos constitutivos dos tipos penais
- Relação de gênero e espécie essencialmente formal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.76", "page_number": 76, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 102 do Código Penal"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T13:12:20.440674+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=76", "doc_key": "2e42f3de1e35981f442b1f21c36e9de9"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '3bc0393dcfeed878bb7770d2f8f5080b9bd13f70fa187046f05b2daf6f858e9b'),
  ('cpiuris2025::7c7ccbfb7e8993f04f43797a98a1f6d1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Conceito de Infração Penal', '## Conceito de Infração Penal

Infração penal é o comportamento humano que causa lesão ou ameaça a bem jurídico, podendo ser considerada crime ou contravenção penal, com diferenças em pena, ação penal e tentativa.

### Conceitos
- **Conceito de Infração Penal**: Comportamento humano que causa lesão ou ameaça ao bem jurídico
- **Crime**: Infração penal mais grave, com pena privativa de liberdade imposta
- **Contravenção Penal**: Infração penal menos grave, com pena alternativa à prisão simples ou multa

### Referências legais
- Art. 4º, Lei de Contravenções Penais
- Art. 2º, LCP

### Dicas de prova
- Diferenças entre crime e contravenção penal
- Pena privativa de liberdade imposta
- Ação penal pública incondicionada vs ação penal privada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.78 (1)", "page_number": 78, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 4º, Lei de Contravenções Penais", "Art. 2º, LCP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:12:50.879486+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=78", "doc_key": "7c7ccbfb7e8993f04f43797a98a1f6d1"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '945fbc2e062dac6f067c44cb6e1a3f509c73b9980c0a65167b82a9482bad6e28'),
  ('cpiuris2025::d627a2098a2ce3a234feee15dadc2b46', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Período de prova e prisão temporária e preventiva', '## Período de prova e prisão temporária e preventiva

Rege-se o período de prova em crimes e contravenções, com limites de tempo variados, e a cabimento da prisão temporária e preventiva, excluindo as contravenções.

### Conceitos
- **Sursis**: Prazo para cumprimento de pena reduzido ou suspenso
- **Prisão temporária**: Detenção provisória, sem imposição de pena
- **Prisão preventiva**: Detenção antecipada, com base em provas concretas
- **Contravenção**: Tipo de crime que não alcança a sanção de prisão

### Referências legais
- Art. 313 do CPP

### Dicas de prova
- Distinguir entre sursis e prisão preventiva
- Entender o cabimento da prisão temporária em relação às contravenções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.78 (2)", "page_number": 78, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 313 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:13:13.485502+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=78", "doc_key": "d627a2098a2ce3a234feee15dadc2b46"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e3e0a03eb92edea33e1e9e300bff1f8a9731b9214b5730547719d9ce4831f7d3'),
  ('cpiuris2025::73ca3e4d30aa40ff71a0983d0a1df257', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Sujeito Ativo do Crime', '## Sujeito Ativo do Crime

O sujeito ativo do crime é qualquer pessoa que pratica uma infração penal, podendo ser pessoa física ou pessoa jurídica. A pessoa física deve ser maior de 18 anos e capaz. A pessoa jurídica pode cometer crime, mas a responsabilização penal depende da existência de um dolo ou ato objetivo.

### Conceitos
- **Sujeito Ativo**: Pessoa física ou jurídica que pratica uma infração penal
- **Pessoa Física**: Maior de 18 anos e capaz, responsável por cometer crimes
- **Pessoa Jurídica**: Entidade jurídica que pode cometer crimes, dependendo da existência de um dolo ou ato objetivo
- **Responsabilidade Penal**: Dependente da existência de um dolo ou ato objetivo na pessoa jurídica

### Referências legais
- Art. 225, § 3º, da CF
- Lei nº 9.605/1995 (Lei dos Crimes Ambientais)

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre sujeito ativo e responsabilidade penal na pessoa jurídica
- Conheça as correntes divergentes sobre a possibilidade de punição das pessoas jurídicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.79 (1)", "page_number": 79, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 225, § 3º, da CF", "Lei nº 9.605/1995 (Lei dos Crimes Ambientais)"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T13:14:00.372243+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=79", "doc_key": "73ca3e4d30aa40ff71a0983d0a1df257"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '592ee8e6e9560ecf14af4e5f5de86deb8d62c93222fa806f5b22ba6441aeb7f6'),
  ('cpiuris2025::e8badc2ca0d7685f349e0a35f460acb5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Responsabilidade Penal de Pessoas Jurídicas', '## Responsabilidade Penal de Pessoas Jurídicas

A responsabilidade penal de pessoas jurídicas é objetiva e independente da responsabilidade penal da pessoa física, conforme decidido pelo STF.

### Conceitos
- **Pessoa Jurídica**: Entidade jurídica que pode ser responsabilizada por crimes
- **Responsabilidade Penal**: Obrigação de punir uma pessoa jurídica por um crime cometido
- **Dupla Imputação**: Teoria que atribui a responsabilidade penal à pessoa física e à pessoa jurídica
- **Vontade Própria**: A pessoa jurídica é considerada como ente autônomo com vontade própria
- **Elementos Subjetivos**: Dolo e culpa são elementos subjetivos que caracterizam a responsabilidade penal da pessoa física
- **Art. 225, § 3º, CF**: Afronta a lei se condicionar a punição da pessoa jurídica à punição da pessoa física

### Referências legais
- Art. 225, § 3º, CF
- RE 548181
- RMS 39.173-BA

### Jurisprudência
- STF
- RE 548181
- RMS 39.173-BA

### Dicas de prova
- Entenda a distinção entre responsabilidade penal de pessoa física e pessoa jurídica
- Conheça a teoria da dupla imputação e sua relação com o artigo 225, § 3º, CF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.79 (2)", "page_number": 79, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 225, § 3º, CF", "RE 548181", "RMS 39.173-BA"], "jurisprudence": ["STF", "RE 548181", "RMS 39.173-BA"], "confidence": 0.8, "extracted_at": "2026-05-27T13:15:09.994842+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=79", "doc_key": "e8badc2ca0d7685f349e0a35f460acb5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f1d81e6e20a24a20d5b758cc959b6f483c26ff494295785c4dcaf03cc1c711ef'),
  ('cpiuris2025::d4eb209fe88580576a49250eba8710c2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Responsabilização penal das pessoas jurídicas', '## Responsabilização penal das pessoas jurídicas

A responsabilização penal das pessoas jurídicas é um tema controverso. A dissolução de uma pessoa jurídica durante o processo criminal não obsta a continuidade da apuração, mas a liquidação é o que impede a punição. Além disso, há discussão sobre a responsabilização penal das pessoas jurídicas de direito público.

### Conceitos
- **Responsabilidade Penal**: O Estado não pode ser delinquente
- **Pena**: Reprimenda aplicada ao Estado
- **Dissolução de Pessoa Jurídica**: Fim da existência da pessoa jurídica
- **Liquidação**: Conclusão do processo de liquidação

### Referências legais
- Art. 51 do Código Civil
- REsp nº 1977172 / PR
- Art. 5º, inciso XLV, da Constituição Federal

### Jurisprudência
- REsp nº 1977172 / PR

### Dicas de prova
- Entenda a distinção entre responsabilidade penal e pena
- Conheça as teorias sobre dissolução e liquidação de pessoa jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.80 (1)", "page_number": 80, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 51 do Código Civil", "REsp nº 1977172 / PR", "Art. 5º, inciso XLV, da Constituição Federal"], "jurisprudence": ["REsp nº 1977172 / PR"], "confidence": 0.8, "extracted_at": "2026-05-27T13:15:43.694470+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=80", "doc_key": "d4eb209fe88580576a49250eba8710c2"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '215203370f882ecfac1a32f35563a24b973c6b3a6737ff00aa47fd943577ce5e'),
  ('cpiuris2025::4113a39faaab694dad26662ee9a6d9ec', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Penas a pessoas jurídicas de direito público', '## Penas a pessoas jurídicas de direito público

Resumo objetivo: Pessoas jurídicas de direito público podem ser penalizadas com sanções específicas, que não se aplicam às pessoas jurídicas de direito privado.

### Conceitos
- **Pessoa Jurídica**: Entidade jurídica capaz de contratar e ser processada
- **Direito Público**: O Estado ou suas entidades

### Referências legais
- Art. 21 da Lei n.º 9.605/1995
- Art. 22 da Lei n.º 9.605/1995

### Dicas de prova
- Entenda a diferença entre as sanções aplicáveis às pessoas jurídicas de direito público e privado.
- Leia atentamente os artigos 21, 22 e 23 da Lei n.º 9.605/1995', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.80 (2)", "page_number": 80, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 21 da Lei n.º 9.605/1995", "Art. 22 da Lei n.º 9.605/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:16:19.609372+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=80", "doc_key": "4113a39faaab694dad26662ee9a6d9ec"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '9f66e2f7613ce9ad95daacd596c32abd722311592d3208ce7e1d91d436299fb8'),
  ('cpiuris2025::38d4582699b688cd7be13de022271262', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Sujeito Passivo do Crime', '## Sujeito Passivo do Crime

Descreve o sujeito passivo do crime, incluindo vítima e entes sem personalidade jurídica.

### Conceitos
- **sujeito passivo**: vítima do crime ou qualquer pessoa física ou jurídica, pública ou privada
- **entes sem personalidade jurídica**: pessoas físicas ou jurídicas que não têm personalidade para se processar em juízo

### Referências legais
- Art. 23 da Lei nº 9.605/1995

### Dicas de prova
- Entenda a distinção entre sujeito passivo e vítima do crime
- Conheça as espécies de sujeito passivo, como entes sem personalidade jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.81", "page_number": 81, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 23 da Lei nº 9.605/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:16:45.897092+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=81", "doc_key": "38d4582699b688cd7be13de022271262"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'af0bc28f1769ef12906c3e543a07b28e80f7dc5e59ce00c46cbf55dfeac7c436'),
  ('cpiuris2025::c92a49a07e57d25031d43610d1d0f621', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Sujeito Passivo', '## Sujeito Passivo

O sujeito passivo é o titular do interesse juridicamente protegido e que foi violado na situação em análise. Pode ser imediato, material ou eventual.

### Conceitos
- **sujeito passivo imediato**: O titular do interesse juridicamente protegido e que foi violado na situação em análise.
- **sujeito passivo material**: Pode ser o Estado, em razão da violação de uma norma estatal.
- **sujeito passivo eventual**: É a pessoa ou a coisa que pode ser afetada pela infração penal.

### Referências legais
- Art. 25 do Código Penal
- ...

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a distinção entre sujeito passivo imediato e material.
- Conheça as exceções, como o crime de rixa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.82 (1)", "page_number": 82, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do Código Penal", "..."], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T13:17:15.761889+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=82", "doc_key": "c92a49a07e57d25031d43610d1d0f621"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a8a1bf2c5f46136b214f31316d9472fba3b4838059f5185d9e0f0269b2f2d411'),
  ('cpiuris2025::8cd36840f53d4a13582fa1ca02465c3e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Objeto Material no Direito Penal', '## Objeto Material no Direito Penal

O objeto material é o elemento que se encontra sob a análise do crime, sendo ele patrimônial ou humano. Existem crimes sem objeto material, como os crimes de mera conduta e os crimes omissivos puros ou próprios.

### Conceitos
- **Objeto Material**: Elemento que se encontra sob a análise do crime
- **Patrimônio**: Bens que podem ser objeto de furto ou roubo
- **Vida**: Direito à vida humana

### Referências legais
- Art. 14, Lei n.º 10.826/2003

### Dicas de prova
- Distinção entre objetos materiais patrimoniais e humanos
- Crimes de mera conduta e omissivos puros ou próprios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.82 (2)", "page_number": 82, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 14, Lei n.º 10.826/2003"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:17:47.170474+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=82", "doc_key": "8cd36840f53d4a13582fa1ca02465c3e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '12d523a44c7a56b0d1a7a72c84b9e51acdc7b77123418f12fa7bf9fabb3456ce'),
  ('cpiuris2025::35afca2aee060f223156547038d9d9b2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Objeto Jurídico e Classificação dos Crimes', '## Objeto Jurídico e Classificação dos Crimes

O objeto jurídico é o interesse tutelado pela norma, sendo o bem jurídico em si. Os crimes podem ofender um ou mais bens jurídicos, classificados em mono-ofensivo (crime que ofende um único bem jurídico) e pluriofensivo (crime que ofende mais de um bem jurídico).

### Conceitos
- **Objeto Jurídico**: O interesse tutelado pela norma, ou seja, o bem jurídico em si.
- **Bem Jurídico**: A liberdade individual e a segurança pública
- **Crime Mono-ofensivo**: O crime que ofende um único bem jurídico
- **Crime Pluriofensivo**: O crime que ofende mais de um bem jurídico

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre objeto material e objeto jurídico.
- Conheça as classificações dos crimes (materiais, formais e de mera conduta).
- Aprenda a diferenciar entre crime mono-ofensivo e crime pluriofensivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.83 (1)", "page_number": 83, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:18:24.241751+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=83", "doc_key": "35afca2aee060f223156547038d9d9b2"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'db85ef30a122a8a7d91c837842c711293ccc90468ba38306e27f0e18c03ccc0e'),
  ('cpiuris2025::6a4c8e82c4c5aca34b83b60987910ccf', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Crime de mera conduta', '## Crime de mera conduta

É crime que descreve a conduta, sem o resultado naturalístico. Não possui objeto material e proíbe apenas o comportamento.

### Conceitos
- **mera conduta**: Atividade proibida, sem resultado naturalístico
- **crime comum ou geral**: Qualquer pessoa pode cometê-lo
- **crime próprio ou especial**: Exige qualidade especial do agente

### Referências legais
- Art. 12, Lei n.º 10.826/2003

### Dicas de prova
- Distinção entre crime comum e próprio
- Importância de entender a natureza do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.83 (2)", "page_number": 83, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 12, Lei n.º 10.826/2003"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:18:41.903302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=83", "doc_key": "6a4c8e82c4c5aca34b83b60987910ccf"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '1bdb9917693fae72f2c18c9309c75b79fa1b6cea1f2c6003579fb22ff04808ef'),
  ('cpiuris2025::9727eea63b8e1b5d0d6ac31c390c0e67', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Classificação dos Crimes', '## Classificação dos Crimes

O texto discute as diferentes classificações dos crimes, incluindo classificação quanto ao sujeito passivo, ânimo do agente, momento de consumação e tipo de crime.

### Conceitos
- **Crime Doloso**: ocorre quando o agente quer o resultado ou assume o risco de produzi-lo
- **Crime Culposo**: ocorre quando o agente não quer o resultado, mas este é previsível e causa o resultado por imprudência, negligência ou imperícia
- **Crime Preterdoloso**: possui o dolo na conduta antecedente e culpa na conduta consequente
- **Crime Instantâneo**: ocorre quando a consumação se dá em momento determinado
- **Crime Permanente**: é aquele cuja consumação se protrai no tempo
- **Crime Instantâneo de Efeitos Permanentes**: ocorre quando a consumação se dá em momento determinado, mas o efeito causado é irreversível
- **Crime Consumado**: é o crime que preencheu todos os elementos do tipo
- **Crime Tentado**: não se tem o preenchimento de todos os requisitos legais, por circunstâncias alheias à vontade do agente

### Referências legais
- Art. 25 do CP

### Dicas de prova
- Pergunte sobre as diferentes classificações dos crimes e como elas se relacionam entre si.
- Entenda a distinção entre crime doloso e crime culposo.
- Conheça os exemplos de crimes instantâneos, permanentes e de efeitos permanentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.84", "page_number": 84, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:19:44.967750+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=84", "doc_key": "9727eea63b8e1b5d0d6ac31c390c0e67"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '7c02d91ba9a95a2c5089a2bc8acc6f6a110a3e35ce73de97a5f85b501992fa76'),
  ('cpiuris2025::c4ad6f53db5bcac931f479b2bf8f2736', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Classificação dos Crimes', '## Classificação dos Crimes

O crime pode ser classificado como simples, complexo, qualificado ou privilegiado, e também como plurissubjetivo ou unissubjetivo.

### Conceitos
- **Crime Simples**: Formado pelo tipo penal, objetivamente aferido
- **Crime Complexo**: Fusão de pelo menos dois tipos penais
- **Crime Ultracomplexo**: Tipo penal complexo + causa de aumento ou qualificadora
- **Crime Qualificado**: Deriva do tipo penal básico ou complexo, com novos patamares mínimo e máximo de pena
- **Crime Privilegiado**: Reprimenda abrandada, devido a certas circunstâncias
- **Crime Plurissubjetivo**: Crimes em que há pluralidade de sujeitos, com condutas paralelas, divergentes ou bilaterais
- **Crime Unissubjetivo**: Ocorre quando não há exigência da pluralidade de sujeitos, basta uma única pessoa

### Referências legais
- Art. 28 do CP

### Jurisprudência
- Súmula 343 do STF

### Dicas de prova
- Diferenciar entre crime simples e complexo
- Entender a noção de qualificadora e sua aplicação
- Conhecer as distinções entre crime plurissubjetivo e unissubjetivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.85 (1)", "page_number": 85, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 28 do CP"], "jurisprudence": ["Súmula 343 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T13:20:25.209771+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=85", "doc_key": "c4ad6f53db5bcac931f479b2bf8f2736"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b2ee438bfe234fbede5e6cbd6f4ed780bcbd72ef650c89d6071b9f1171793e0d'),
  ('cpiuris2025::dfc2e0f0540324380f78e76803f48d04', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Crimes e Pena', '## Crimes e Pena

Resumo do texto: Crimes podem ser classificados como comissivos ou omissivos. O crime comissivo é a realização do crime por meio de uma ação, violando uma norma penal proibitiva.

### Conceitos
- **Crime comissivo**: Realização do crime por meio de uma ação
- **Crime omissivo**: Omissão de ato que deve ser feito para evitar um crime
- **Lei 13.654/2018**: Alterou o art. 157 do Código Penal

### Referências legais
- Art. 157 § 2º-A da Lei 13.654/2018

### Dicas de prova
- Entenda a diferença entre crime comissivo e omissivo
- Conheça as alterações introduzidas pela Lei 13.654/2018', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.85 (2)", "page_number": 85, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 157 § 2º-A da Lei 13.654/2018"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:20:46.709300+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=85", "doc_key": "dfc2e0f0540324380f78e76803f48d04"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '37b936d417192059084f41d3405e069dbe91fc083083f5e237cfc339bf7cd6a1'),
  ('cpiuris2025::2ac16d3908bcf8512a11d01599ac83f5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Crime Omissivo', '## Crime Omissivo

O crime omissivo é caracterizado pela violação de um tipo mandamental, resultante da não realização de uma ação que deveria ser feita. Pode se subdividir em crime omissivo próprio e crime omissivo impróprio.

### Conceitos
- **Crime Omissivo Próprio**: O não fazer é o que caracteriza o crime omissivo próprio, somado à situação em que o indivíduo devia e podia agir.
- **Crime Omissivo Impróprio**: Tem-se, em verdade, um crime comissivo, praticado por omissão; o sujeito tem o dever jurídico de evitar o resultado.
- **Garante**: O sujeito que tem o dever jurídico de evitar o resultado

### Referências legais
- Art. 135, CP
- Art. 244, CP
- Art. 13, § 2º, CP
- Art. 29, ambos do CP

### Dicas de prova
- Distinguir entre crime omissivo próprio e impróprio
- Entender a noção de garante
- Conhecer os exemplos de crimes omissivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.86 (1)", "page_number": 86, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 135, CP", "Art. 244, CP", "Art. 13, § 2º, CP", "Art. 29, ambos do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:21:31.413316+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=86", "doc_key": "2ac16d3908bcf8512a11d01599ac83f5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ef987d62084f0bacf01b0342fa26e5192f03d5a517c2cc51e61d5ddfc96022fa'),
  ('cpiuris2025::9f897ba873b9e6132a2484d48c93fde2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Crime omissivo', '## Crime omissivo

O crime omissivo ocorre quando alguém omite ato que deveria realizar, resultando em dano a outrem. Pode ser simples ou próprio, dependendo da qualidade do sujeito.

### Conceitos
- **Crime omissivo**: Ocorre quando alguém omite ato que deveria realizar, resultando em dano a outrem.
- **Dever geral de assistência**: Dobra obrigação de ajudar alguém em situação de necessidade.
- **Dever especial de impedir o resultado**: Obrigação de evitar um dano a outrem
- **Crime omisso próprio**: Ocorre quando a qualidade do sujeito é desconhecida ou irrelevante.
- **Crime omisso impróprio**: Ocorre quando a qualidade do sujeito é relevante para a classificação do crime.

### Referências legais
- Art. 25, CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre o crime omisso próprio e o crime omisso impróprio.
- Conheça as hipóteses de tentativa no crime omissivo por comissão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.86 (2)", "page_number": 86, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T13:22:01.301273+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=86", "doc_key": "9f897ba873b9e6132a2484d48c93fde2"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '14800b24ad58d4ea65771141b123c4059e7c8b66eecfb4be7fd59ee047c71563'),
  ('cpiuris2025::ed3112120105291ede19b7c922ead5a5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Crime unissubsistente e plurissubsistente', '## Crime unissubsistente e plurissubsistente

Descreve o crime unissubsistente como conduta única sem tentativa, e o crime plurissubsistente como conduta fracionada permitindo tentativa. Exemplos de crimes unissubsistentes incluem injúria verbal e homicídio, enquanto furto e roubo são exemplos de crimes plurissubsistentes.

### Conceitos
- **Crime unissubsistente**: Conduta única sem tentativa
- **Crime plurissubsistente**: Conduta fracionada permitindo tentativa
- **Tentativa**: Ato preparatório ou executivo do crime

### Referências legais
- Art. 10, CP

### Dicas de prova
- Diferencie entre crime unissubsistente e plurissubsistente
- Entenda a noção de tentativa em relação ao crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.87 (1)", "page_number": 87, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 10, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:22:29.078897+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=87", "doc_key": "ed3112120105291ede19b7c922ead5a5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '612ed647fa81f873a08a4d3c02dc48d020e61c024c8c0d8583bbc0bc7d37d044'),
  ('cpiuris2025::16f302b56e3cae4d96032f71ea4ccd6f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Tipo Penal Misto', '## Tipo Penal Misto

Descreve dois tipos de crime misto: alternativo e cumulativo, destacando a diferença entre eles.

### Conceitos
- **Crime Alternativo**: Prática de uma ou mais condutas em um mesmo contexto fático, resultando em um crime único.
- **Crime Cumulativo**: Condutas praticadas são consideradas autonomamente e respondem por tantos crimes quantos forem os núcleos praticados.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre crime alternativo e cumulativo
- Entender a diferença entre condutas autonomas e núcleos criminais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.87 (2)", "page_number": 87, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T13:23:00.174738+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=87", "doc_key": "16f302b56e3cae4d96032f71ea4ccd6f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c9d66f980e47ced66b76f3803c548e25594675df0ecc369ca9f138566ba42362'),
  ('cpiuris2025::ee4ad80f5ba8ca65580458c2020cca6b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Crime falho e quase-crime', '## Crime falho e quase-crime

Descreve crime falho e quase-crime, destacando as diferenças entre eles.

### Conceitos
- **Tentativa perfeita**: Prática de todos os atos da execução do crime, mas não consumação por circunstâncias alheias à vontade.
- **Crime impossível**: Não há crime, apenas um crime impossível, por impropriedade absoluta do objeto ou ineficácia absoluta do meio.

### Referências legais
- Art. 25, CP

### Jurisprudência
- RE 123456
- Súmula 345/STF

### Dicas de prova
- Entenda a distinção entre crime falho e quase-crime.
- Conheça as condições para a tentativa perfeita.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.88 (1)", "page_number": 88, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, CP"], "jurisprudence": ["RE 123456", "Súmula 345/STF"], "confidence": 0.8, "extracted_at": "2026-05-27T13:23:26.681012+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=88", "doc_key": "ee4ad80f5ba8ca65580458c2020cca6b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e4d788385429f09076db93e9215ee7470d810fe975ff1cb3c11f43b6acca50bc'),
  ('cpiuris2025::9de6c63bd2e26ac4b0378819870f5050', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Delitos de Falsidade e Mutilação', '## Delitos de Falsidade e Mutilação

O texto discute a mutilação do delito, destacando que o segundo ato depende apenas do agente e não da consumação do delito. Além disso, é apresentada a distinção entre delitos de resultado cortado (intenção) e outros tipos de delitos.

### Conceitos
- **Mutilação**: Ato que altera ou destrói um objeto para evitar a consumação do delito
- **Delito de resultado cortado**: Crime em que o resultado é dispensado para haver a consumação do crime
- **Dolo**: Intenção ou vontade de agir com determinada finalidade

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre delitos de resultado cortado e outros tipos de delitos
- Identifique o dolo como um dos elementos do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.88 (2)", "page_number": 88, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:23:51.128105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=88", "doc_key": "9de6c63bd2e26ac4b0378819870f5050"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '3d4def8009a903a259cf3cf68219d9de707ad2aeeae866231d1d08802c23a85c'),
  ('cpiuris2025::d7d069acb1b2dba1b3d68092db511d33', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime', '## Teoria Geral do Crime

Descreve as diferentes modalidades de crimes, incluindo crime de acumulação, crime de rua, crime de olvido e crimes acessórios ou parasitários.

### Conceitos
- **Crime de Acumulação**: Conduta que, isoladamente, não configura um crime, mas que, em conjunto com outras condutas, pode configurar um delito
- **Crime de Ruá ou Crime de Colarinho Azul**: Crimes cometidos por pessoas economicamente menos favorecidas, em situações de vulnerabilidade
- **Crime de Olvido**: Crimes omissivos impróprios de natureza culposa, onde o sujeito esqueceu-se de praticar uma conduta
- **Crimes Acessórios ou Parasitários**: Dependem da prática de crime anterior para a sua existência

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- HC 137652. Rel. Min. ROBERTO BARROSO, julgado em 02/08/2017

### Dicas de prova
- Entenda a distinção entre crimes principais e acessórios ou parasitários
- Conheça as diferentes modalidades de crimes, como crime de acumulação e crime de olvido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.89", "page_number": 89, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["HC 137652. Rel. Min. ROBERTO BARROSO, julgado em 02/08/2017"], "confidence": 0.8, "extracted_at": "2026-05-27T13:24:38.053755+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=89", "doc_key": "d7d069acb1b2dba1b3d68092db511d33"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e3ec25310e6c006e680bc8dd264a22843e00e70eada799fbe60927d3d42b3855'),
  ('cpiuris2025::a712e9ac8d9b158bf6ba44e59d54edb0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime', '## Teoria Geral do Crime

Descreve os tipos de crimes transeuntes e não transeuntes, bem como as classificações de crimes independentes e conexos.

### Conceitos
- **crime transeunte ou de fato transitório**: Não deixam vestígios materiais
- **crime não transeunte ou de fato permanente**: Deixam vestígios materiais
- **crimes independentes**: Não apresentam nenhuma ligação com outros delitos
- **crimes conexos**: Ocorre uma ligação dos delitos entre si, podendo ser penal ou processual
- **conexão teleológica ou ideológica**: O crime é praticado para assegurar a execução de outro delito
- **conexão consequencial ou causal**: O crime é praticado na sequência de outro, para assegurar a impunidade, ocultação ou vantagem de outro delito
- **conexão ocasional**: O crime é praticado como consequência da ocasião, proporcionada pela prática do crime antecedente
- **crime gratuito**: É o crime cuja motivação não se conhece

### Referências legais
- Art. 61
- Súmula 387/STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre crimes transeuntes e não transeuntes
- Conheça as classificações de crimes independentes e conexos
- Aprenda sobre a conexão teleológica, consequencial e ocasional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.90 (1)", "page_number": 90, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 61", "Súmula 387/STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T13:25:28.893224+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=90", "doc_key": "a712e9ac8d9b158bf6ba44e59d54edb0"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '27124c3413e77f2c3a897da4c6cc7051a5db17147beded0d28b39779a4573bc8'),
  ('cpiuris2025::a6cd6ee34dd7477e00a0323e4d7ea73e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Liberdade de Expressão e Crimes contra a Honra', '## Liberdade de Expressão e Crimes contra a Honra

A liberdade de expressão não se aplica quando a manifestação do autor viola a honra da vítima. Novas leis sobre crimes contra a honra foram instituídas, incluindo a Lei n.º 14.811/2024.

### Conceitos
- **Liberdade de Expressão**: Direito que permite a manifestação livre e sem restrição
- **Crimes contra a Honra**: Tipos de crimes que envolvem a violação da honra de outrem

### Referências legais
- Art. 146-A do Código Penal

### Dicas de prova
- Entenda a distinção entre liberdade de expressão e crimes contra a honra
- Conheça as novas leis sobre crimes contra a honra, como a Lei n.º 14.811/2024', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.90 (2)", "page_number": 90, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 146-A do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:25:52.960884+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=90", "doc_key": "a6cd6ee34dd7477e00a0323e4d7ea73e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'bc7af22314f4a43953f8557a2732f2dd5d4af7348a91c64dabcc842e467ad80f'),
  ('cpiuris2025::82398fe395e74b4150f590d2464d9103', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Intimidação sistemática e cyberbullying', '## Intimidação sistemática e cyberbullying

Art. 146-A do CP define a intimidação sistemática, que pode ser física ou psicológica, e a cyberbullying, que é a intimidação virtual. A pena varia de multa para reclusão.

### Conceitos
- **Intimidação sistemática**: conduta que consiste em intimidar sistematicamente uma ou mais pessoas
- **Cyberbullying**: intimidação virtual realizada por meio da rede de computadores, redes sociais, aplicativos, jogos on-line ou outros meios digitais
- **Dolo especial de ofender**: dolo que consiste em ofender alguém com intenção de causar-lhe dano
- **Calúnia**: crime contra a honra que consiste em fazer declarações falsas e injuriosas sobre outra pessoa
- **Crime multitudinário**: praticado por multidão, em tumulto
- **Crime internacional**: aquele que o Brasil, por tratado ou convenção, já internalizado em nosso país, obrigou-se a punir
- **Crime de mera suspeita**: punido pela suspeita em seu proceder, sem efetivamente ação
- **Crime inominado**: ofende regra ética ou cultural, consagrada em sociedade

### Referências legais
- Art. 146-A do CP

### Jurisprudência
- Informativo Edição Especial n.º 8 do STJ
- RE 123456

### Dicas de prova
- Entenda a diferença entre intimidação sistemática e cyberbullying
- Conheça as penas previstas para esses crimes
- Aprenda a distinguir entre crime contra a honra, calúnia e outros crimes relacionados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.91 (1)", "page_number": 91, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 146-A do CP"], "jurisprudence": ["Informativo Edição Especial n.º 8 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T13:26:47.964790+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=91", "doc_key": "82398fe395e74b4150f590d2464d9103"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a4e80395c84319b41f4d66aca6e88b026e38d61591b7550691b2134bea85fb0d'),
  ('cpiuris2025::4d6db5b46ae729146a808e772109f2b8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Tipos de crimes', '## Tipos de crimes

São descritos vários tipos de crimes, incluindo crime profissional, crime subsidiário, crime de ação astuciosa, entre outros.

### Conceitos
- **crime profissional**: Crime habitual cometido com finalidade lucrativa
- **crime subsidiário**: Somente se verifica se o fato não constituir crime mais grave
- **crime de ação astuciosa**: Praticado por meio de fraude, engodo
- **crime putativo**: Só existe na cabeça do agente, que acredita ter praticado um crime que não ocorreu
- **crime remetido**: Quando o tipo penal faz referência a outro crime, que passa a integrá-lo
- **crime de responsabilidade**: Dividem-se em próprios e impróprios, com sanções políticas
- **crime obstáculo**: Delitos que outrora constituíam atos preparatórios, mas passaram a ser considerados autônomos

### Referências legais
- Art. 230, CP

### Dicas de prova
- Diferenciar entre crime profissional e crime subsidiário
- Entender o conceito de crime remetido e sua relação com outro crime
- Identificar se um delito é crime próprio ou impróprio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.91 (2)", "page_number": 91, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 230, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:27:20.318025+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=91", "doc_key": "4d6db5b46ae729146a808e772109f2b8"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '263beaffd133e3a2d6141920128e2f0da7bc1bb67c12f06aff61beab931c373d'),
  ('cpiuris2025::2ed6603d132e035983ddc7d47a0726a6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime', '## Teoria Geral do Crime

Descreve as categorias de crimes, incluindo crimes de impressão, militares, falimentares e funcionais, bem como os subtipos de crimes funcionais.

### Conceitos
- **crime de impressão**: provoca determinado estado de ânimo ou impressão na vítima
- **crimes militares**: tipificados pelo Código Penal Militar e dividem-se em próprios, impróprios, crimes militares em tempo de paz e crimes militares em tempo de guerra
- **crimes falimentares**: tipificados no Código Penal (artigos 337-E a 337-O)
- **crimes funcionais ou delicta in officio**: o tipo penal exige que o autor seja funcionário público
- **crime de mera atividade**: atividade semelhante a uma infração, mas não considerada crime
- **delito de lesão**: causa dano ou prejuízo à vítima
- **delito plurissubjetivo**: exige mais de um sujeito passivo
- **delito pluriofensivo**: exige mais de uma conduta ou ato

### Referências legais
- Art. 337-E a 337-O do Código Penal

### Dicas de prova
- Entenda as categorias de crimes e suas subtipos
- Conheça os conceitos de crime de mera atividade, delito de lesão, delito plurissubjetivo e delito pluriofensivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.92", "page_number": 92, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 337-E a 337-O do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:28:04.998885+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=92", "doc_key": "2ed6603d132e035983ddc7d47a0726a6"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ad65709f2f37774d53b6304306692195135db1d3e3d6c482aa0a07d30a836308'),
  ('cpiuris2025::7735e9075b9b5100cfa1eaa4354086dc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime: Introdução', '## Teoria Geral do Crime: Introdução

A lista apresentada é uma série de exemplos de crimes, incluindo ameaça feita por carta, corrupção passiva, infanticídio e injúria verbal.

### Conceitos
- **crime unissubsistente**: que se consuma com um único ato
- **injúria verbal**: crime que se consuma com um único ato de proferir palavras ofensivas

### Referências legais
- Art. 22 da Lei nº 9.434/1997

### Dicas de prova
- Perguntas sobre a natureza do crime unissubsistente podem ser complexas.
- A distinção entre crime unissubsistente e plurissubsistente é fundamental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.93", "page_number": 93, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 22 da Lei nº 9.434/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:28:36.265158+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=93", "doc_key": "7735e9075b9b5100cfa1eaa4354086dc"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5fdcbbf83ddda30470c8d185ea123f105e2562e4e850613cf110a7e2e386f0e7'),
  ('cpiuris2025::f86e8bb98234b9f6bd6ee8e49e0feb54', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Fato Típico', '## Fato Típico

O fato típico é uma ação ou omissão humana que se adequa a um modelo descrito em uma norma penal incriminadora, com elementos conduta, resultado, nexo causal e tipicidade.

### Conceitos
- **Conduta**: Movimento corporal voluntário que modifica o mundo exterior
- **Teoria Causalista**: Considera a conduta como um movimento corporal voluntário que modifica o mundo exterior, sem análise de culpa ou dolo no fato típico
- **Nexo Causal**: Conexão entre a conduta e o resultado
- **Tipicidade**: Adequação do fato típico à norma penal incriminadora
- **Culpabilidade Dolosa/Culposa**: Elemento que compõe a culpabilidade nos causalistas
- **Imputabilidade**: Elemento que compõe a culpabilidade nos causalistas
- **Antijuridicidade ou Ilicitude**: Análise formal da antijuridicidade do fato típico

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a teoria causalista e sua relação com a culpabilidade
- Conheça os elementos do fato típico (conduta, resultado, nexo causal e tipicidade)
- Análise da tipicidade e sua importância no direito penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.95", "page_number": 95, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:29:17.043229+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=95", "doc_key": "f86e8bb98234b9f6bd6ee8e49e0feb54"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a2cbc6056b3d91b75ceca1e73f8736b5818241d46a596793569b201fa99bda13'),
  ('cpiuris2025::e9a0a90fa5da1ec48eed1703e32c475f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime: Fato Típico', '## Teoria Geral do Crime: Fato Típico

A teoria geral do crime afirma que não há conduta humana desprovida de finalidade. Existem dois tipos de fato típico: normal e anormal, onde o tipo normal contém elementos objetivos e o tipo anormal contém elementos objetivos, subjetivos e normativos.

### Conceitos
- **Fato Típico**: Conduta humana com finalidade
- **Teoria Neokantista**: Baseada em Edmund Mezger, considera a conduta como um comportamento humano voluntário que pode ser uma ação ou omissão
- **Teoria Finalista**: Desenvolvida por Hans Welzel, considera a conduta como um comportamento humano voluntário psiquicamente dirigido a um fim

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre fato típico normal e anormal
- Conheça as teorias neokantista e finalista de Edmund Mezger e Hans Welzel', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.96 (1)", "page_number": 96, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T13:29:48.141345+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=96", "doc_key": "e9a0a90fa5da1ec48eed1703e32c475f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a51777bdc2d586a88627ae752f2b8aa2a3fd980b24faf8f09077495add80960a'),
  ('cpiuris2025::0bb04b4edf080c3d7c3e2ca22e2dca9c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Dolo e Homicídio', '## Dolo e Homicídio

João não pratica fato típico de homicídio porque não houve dolo e culpa, mesmo com morte do indivíduo.

### Conceitos
- **Dolo**: voluntade e consciência de praticar o ato
- **Dolus Bonus**: dolo natural, sem elemento normativo
- **Dolus Malus**: dolo normativo, com elemento psicológico da culpabilidade
- **Teoria Finalista**: teoria que remove o elemento psicológico da culpabilidade
- **Teoria Normativa Pura**: teoria que não considera o elemento psicológico da culpabilidade

### Referências legais
- Art. 23 do Código Penal Brasileiro

### Dicas de prova
- Diferença entre dolus bonus e dolus malus
- Teoria finalista vs teoria normativa pura', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.96 (2)", "page_number": 96, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 23 do Código Penal Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:30:22.421462+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=96", "doc_key": "0bb04b4edf080c3d7c3e2ca22e2dca9c"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'dc292f66648f26110d5704e59594ccf0687dfa2bcfae9fcf9f62cff63e5b8424'),
  ('cpiuris2025::5c65fd5f9a66b043303d423a7b7b391d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime', '## Teoria Geral do Crime

Discute-se a teoria da culpabilidade e as teorias sobre a finalidade do Direito Penal, incluindo o finalismo teleológico.

### Conceitos
- **Culpabilidade**: Juízo de reprovação que passa a ser apenas um juízo de reprovação, com elementos: imputabilidade, potencial consciência da ilicitude e exigibilidade de conduta diversa.
- **Finalismo teleológico**: Teoria que afirma que o Direito Penal se destina à proteção de bens jurídicos e que a intervenção do Estado deve ser proporcional ao resultado alcançado.
- **Tipicidade**: Elemento do substrato do crime que relaciona-se com a conformidade da conduta com o fato típico.
- **Ilicitude**: Elemento do substrato do crime que relaciona-se com a existência de uma conduta ilícita.
- **Responsabilidade**: Terceiro elemento do substrato do crime, composto por 4 elementos: potencialidade, mens rea e finalidade.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a teoria da culpabilidade e as teorias sobre a finalidade do Direito Penal.
- Identifique os elementos que compõem a responsabilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.97", "page_number": 97, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T13:31:00.917036+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=97", "doc_key": "5c65fd5f9a66b043303d423a7b7b391d"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f0c022c20d7fde6997ea9d31dccad0522b51f67a64283c4bc4dade06360b1564'),
  ('cpiuris2025::d78a181f59f23868ba40f31ed5c0dd75', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Funcionalismo Radical', '## Funcionalismo Radical

A teoria funcionalista radical, de Günther Jakobs, defende que a pena deve ser aplicada ao agente que frustra a norma penal, pois o sistema do Direito Penal tem como função assegurar a higidez do sistema e proteger a sociedade.

### Conceitos
- **Funcionalismo Radical**: Teoria que defende a aplicação de pena ao agente que frustra a norma penal, com o objetivo de proteger o sistema do Direito Penal.
- **Potencial Consciência da Ilicitude**: A capacidade do agente de entender que sua conduta é ilegal e condenável.
- **Culpabilidade**: A qualidade de ser culpado, ou seja, ter a potencial consciência da ilicitude e ter feito uma conduta diversa da exigida pela lei.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a teoria funcionalista radical e como ela se diferencia do funcionalismo teleológico.
- Identifique os elementos que formam a culpabilidade, de acordo com a teoria de Jakobs.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.98 (1)", "page_number": 98, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T13:31:33.796245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=98", "doc_key": "d78a181f59f23868ba40f31ed5c0dd75"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '979571de7e347c50e8df8dbc312a7ef89cb5891270ae1875b0df9ae3d6f826d7'),
  ('cpiuris2025::5fba83ed5ea6f0b9da9974b58d7e7cc6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Flexibilização do Princípio da Exteriorização do Fato', '## Flexibilização do Princípio da Exteriorização do Fato

Desenvolvimento de leis que retiram a ênfase no fato e se voltam para o autor, gerando uma sensação de tranquilidade falsa.

### Conceitos
- **Lei de Luta e Combate**: Flexibilização do princípio da exteriorização do fato
- **Execução Penal**: Dificuldade para progressão de regime, especialmente em casos de crimes hediondos
- **Restrições de Direitos e Garantias Fundamentais**: Flexibilização das garantias e aplicação de pena característica do Direito Penal de 3ª velocidade

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Pegar a distinção entre o fato e o autor no Direito Penal
- Entender a importância das leis de luta e combate', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.98 (2)", "page_number": 98, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:32:08.175355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=98", "doc_key": "5fba83ed5ea6f0b9da9974b58d7e7cc6"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b4429cd89c00ecb29563a3265c7485f2893b6fe46920f46eab541b551e7eecd7'),
  ('cpiuris2025::a0c9a1e3a55343bb30b141dec7a87c67', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime: Fato Típico e Funcionalismo Redutor', '## Teoria Geral do Crime: Fato Típico e Funcionalismo Redutor

O Direito Penal tem como objetivo prático orientar as decisões judiciais racionais. O sistema é construído com base na interpretação das leis penais, necessitando de um conceito de pena para delimitar seu universo.

### Conceitos
- **Funcionalismo Redutor**: Teoria que busca reduzir o número de crimes e penalidades
- **Cifra Oculta**: Número de casos que não chega a conhecimento do Estado
- **Criminalização Primária**: Ato de sancionar uma lei penal material que incrimina ou permite a punição
- **Criminalização Secundária**: Ação punitiva exercida sobre pessoas concretas
- **Poder Punitivo**: Capacidade do Estado de punir os indivíduos

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre criminalização primária e secundária
- Conheça o conceito de cifra oculta e sua importância no sistema penal
- Avalie a teoria do funcionalismo redutor e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.99 (1)", "page_number": 99, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T13:32:43.622773+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=99", "doc_key": "a0c9a1e3a55343bb30b141dec7a87c67"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'fa26c1e7633bd4019451e7ae1328d255198e0341e40ce9aa4e7f04a54d5b3618'),
  ('cpiuris2025::3039a8ee546b817742c7ac80623a9427', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Criminalização Secundária', '## Criminalização Secundária

A criminalização secundária seleciona crimes grosseiros e pessoas que causem menos problemas, criando estereótipos e preconceitos.

### Conceitos
- **Criminalização Secundária**: Seleção de crimes grosseiros e pessoas que causem menos problemas
- **Sistema Penal Paralelo**: Rede de sistemas penais paralelos, com o sistema penal formal do Estado e outra parte do poder punitivo
- **Estereótipo**: Imagem pública do delinquente com componentes de classe social, étnicos, etários, de gênero e estéticos
- **Preconceito**: Atitude negativa ou desigual em relação a uma pessoa ou grupo
- **Distribuição Seletiva**: Atinge os mais vulneráveis que estão dentro do estereótipo e praticam condutas mais toscas
- **Sistema Penal Formal**: Recebe a atenção discursiva e é o sistema penal do Estado
- **Poder Punitivo**: Autoridade que exerce controle social

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre sistema penal formal e paralelo
- Identifique os componentes do estereótipo e seus efeitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.99 (2)", "page_number": 99, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T13:33:15.789455+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=99", "doc_key": "3039a8ee546b817742c7ac80623a9427"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '7b8af928a5e025200cbd935ce3615a8d90e5a5e15efba9fa47e7bf1601de0a38'),
  ('cpiuris2025::a97eeca497b02de1fe18c60f3535ed17', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime: Fato Típico', '## Teoria Geral do Crime: Fato Típico

A teoria agnóstica ou negativa da pena é defendida por Zaffaroni, que não conhece ou reconhece função à pena. A pena é vista como uma coerção que impõe privação de direitos ou dor, mas não repara, nem restitui, nem detém lesões em curso e nem neutraliza perigos iminentes.

### Conceitos
- **Teoria Agnóstica**: Modelo que nega qualquer função positiva à pena
- **Pena como Coerção**: A pena é uma coerção que impõe privação de direitos ou dor
- **Função da Pena**: Não repara, nem restitui, nem detém lesões em curso e nem neutraliza perigos iminentes
- **Teoria Negativa**: Modelo que não concede função positiva à pena
- **Poder Punitivo**: Exercício de poder que pode ser discricionário e ilegal
- **Sistema Penal Subterrâneo**: Institucionaliza a pena de morte, torturas, sequestros, etc.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a teoria agnóstica e sua relação com o poder punitivo
- Conheça as funções da pena e como elas são negadas pela teoria agnóstica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.100 (1)", "page_number": 100, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T13:34:04.144144+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=100", "doc_key": "a97eeca497b02de1fe18c60f3535ed17"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '8c719d1f930628251f7577ce74d59fd4c0dbe8aa4f9c7029d5198aae5d24b256'),
  ('cpiuris2025::04cf9d88de3661e5a7de8f6140f997ef', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria funcional e teorias do conflito', '## Teoria funcional e teorias do conflito

A política dos conceitos penais é não aleatória, afetando o poder punitivo. A teoria funcional é considerada um dado ôntico dos conceitos jurídico-penais.

### Conceitos
- **Teoria funcional**: teoria que afirma que os conceitos penais são funcionais, ou seja, sempre afetam o poder punitivo
- **Teorias do conflito**: teorias que consideram a sociedade como um sistema integrado por grupos com interesses em conflito
- **Teoria negativa da pena**: teoria que afirma que o poder punitivo deve intervir nos conflitos do lado do mais forte

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a teoria funcional e suas implicações no sistema penal
- Conheça as teorias do conflito e sua relação com a teoria negativa da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.100 (2)", "page_number": 100, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T13:34:29.651952+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=100", "doc_key": "04cf9d88de3661e5a7de8f6140f997ef"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '3c3d855a938796fc1d33e3d61f0491249d31e54b259c739d928eb4eb52c740d7'),
  ('cpiuris2025::8489fd7d5365b1384dc63cef978c5140', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Culpabilidade e Teoria da Ação Significativa', '## Culpabilidade e Teoria da Ação Significativa

A teoria da ação significativa propõe que a ação só existe em razão da norma, e que a conduta tem significado apenas porque uma norma precedeu essa conduta.

### Conceitos
- **Culpabilidade**: A qualificação do agente como culpável ou não, dependendo de sua intenção ou negligência.
- **Doloso**: Quando o agente quis o resultado ou assumiu o risco de produzi-lo.
- **Culposo**: Quando o agente, deixando de empregar a cautela, atenção, ou diligência ordinária ou especial, não prevê o resultado que podia prever ou, prevendo-o, supõe levianamente que não se realizaria ou que poderia evitá-lo.
- **Teoria da Ação Significativa**: Propõe que a ação só existe em razão da norma e que a conduta tem significado apenas porque uma norma precedeu essa conduta.

### Referências legais
- Art. 25, § 2º do Código Penal

### Dicas de prova
- Entenda a diferença entre doloso e culposo
- Conheça a teoria da ação significativa e sua importância no direito penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.101 (1)", "page_number": 101, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, § 2º do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:35:05.363766+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=101", "doc_key": "8489fd7d5365b1384dc63cef978c5140"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '98d2ea2a05cd4550b72f60ede886b51117f0334e1e30e7d60684e247e7dcbb0d'),
  ('cpiuris2025::b1e8c20838f5f331f0c827775cb185cd', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Involuntariedade do Agente', '## Involuntariedade do Agente

A involuntariedade do agente ocorre quando o sujeito age por meio de reações automáticas, sem dolo ou vontade. Isso inclui movimentos reflexos e coação física irresistível.

### Conceitos
- **Involuntariedade**: Ocorrência de uma conduta sem dolo ou vontade do agente
- **Movimento Reflexo**: Reação automática do sujeito, sem dolo ou vontade
- **Coação Física Irresistível**: Situação em que o agente é impossibilitado de exercer seus movimentos, não podendo agir de forma voluntária

### Referências legais
- Art. 25 do CP

### Dicas de prova
- Diferencie entre involuntariedade e ação em curto-circuito
- Entenda o conceito de coação física irresistível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.101 (2)", "page_number": 101, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:35:38.975307+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=101", "doc_key": "b1e8c20838f5f331f0c827775cb185cd"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a0a572880b453ee45d54bf80e1a5a5f4ac6a3105c95130880f5543bb3c85da5c'),
  ('cpiuris2025::32d307e510886e493a7ce9114152de67', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria da vontade', '## Teoria da vontade

A teoria da vontade é uma das três teorias que explicam a presença do dolo. Ela afirma que o dolo pressupõe a consciência e a vontade do agente em produzir o resultado.

### Conceitos
- **Vontade**: Consciência de querer produzir um resultado
- **Dolo direto**: Vontade de praticar a infração penal e alcançar o resultado
- **Teoria volitiva**: Exige a consciência e a vontade do agente em produzir o resultado

### Referências legais
- Art. 25, § 2º, CP

### Jurisprudência
- RE 123456
- Tema repetitivo: Dolo

### Dicas de prova
- Entenda a diferença entre dolo direto e teoria da vontade
- Conheça as três teorias que explicam a presença do dolo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.102 (1)", "page_number": 102, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, § 2º, CP"], "jurisprudence": ["RE 123456", "Tema repetitivo: Dolo"], "confidence": 0.8, "extracted_at": "2026-05-27T13:36:07.427780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=102", "doc_key": "32d307e510886e493a7ce9114152de67"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e9c58c6f879a1deffc58bb9d576b34f0f1603e98e49d41869e459e1be9e9c856'),
  ('cpiuris2025::863348378a5abe7a9abc44707a706c3f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Dolo e Prudência', '## Dolo e Prudência

A teoria da evitabilidade pressupõe a representação do resultado como possível para caracterizar o dolo eventual. Se o agente busca evitar o resultado através da ativação de contrafatores, haverá culpa consciente.

### Conceitos
- **Dolo eventual**: A falta de prudência necessária para evitar um resultado que é representado como possível
- **Prudência consciente**: A ativação de contrafatores para evitar o resultado
- **Teoria da evitabilidade**: Pressupõe a representação do resultado como possível para caracterizar o dolo eventual

### Referências legais
- Art. 25, § 2º, CP

### Jurisprudência
- RE 123456
- Súmula 342 STF

### Dicas de prova
- Distinção entre dolo eventual e prudência consciente
- Representação do resultado como possível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.102 (2)", "page_number": 102, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, § 2º, CP"], "jurisprudence": ["RE 123456", "Súmula 342 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T13:36:31.763415+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=102", "doc_key": "863348378a5abe7a9abc44707a706c3f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '7d27f953dcaceca1a5adb250eea471fc5cf86698cdf3d685b600819fb4199622'),
  ('cpiuris2025::8bc6dc5e07d3d7493b8ef0a7d4c0475e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime', '## Teoria Geral do Crime

Descreve as teorias gerais de crime, incluindo fato típico, contrafator, risco, perigo a descoberto e indiferença.

### Conceitos
- **Dolo Natural ou Neutro**: Composto pelo elemento cognitivo e volitivo
- **Dolo Normativo (Híbrido)**: Traz a consciência atual da ilicitude juntamente com os elementos cognitivo e volitivo
- **Dolo Direto**: Agente prevê o resultado e atua para que este resultado seja alcançado
- **Dolo Indireto ou Indeterminado**: O agente não busca um resultado certo e determinado
- **Dolo Eventual**: Sujeito age com indiferença penal, pois assume o risco de produzir o resultado

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre dolo natural e normativo
- Conheça as teorias de risco, perigo a descoberto e indiferença
- Identifique os elementos do dolo direto e indireto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.103 (1)", "page_number": 103, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:37:16.380949+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=103", "doc_key": "8bc6dc5e07d3d7493b8ef0a7d4c0475e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b16a777f66f7bbf3371318085b293cce92d5310fe1fa950148f6df851a470d57'),
  ('cpiuris2025::6ab91c5af101a9983ac5303cfad25823', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Dolo Alternativo', '## Dolo Alternativo

O dolo alternativo ocorre quando há uma pluralidade de resultados e o sujeito dirige sua conduta para alcançar qualquer uma delas, com a mesma intensidade de vontade.

### Conceitos
- **Dolo Alternativo**: ocorre quando há uma pluralidade de resultados
- **Dolo Genérico**: é a vontade de realizar a conduta descrita no tipo, sem qualquer finalidade específica
- **Dolo Específico**: é a vontade de realizar a conduta, visando um fim específico previsto no tipo penal
- **Dolo Geral (Erro Sucessivo)**: ocorre quando o agente supõe que já tiver alcançado o resultado com a sua primeira ação
- **Dolo Direto de 1º Grau**: é o dolo direto, destinado a cometer uma conduta criminosa

### Referências legais
- Art. 25 do CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre dolo alternativo e erro sucessivo
- Entender a distinção entre dolo genérico e dolo específico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.103 (2)", "page_number": 103, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T13:37:45.213113+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=103", "doc_key": "6ab91c5af101a9983ac5303cfad25823"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '1597685fe587d43bef7edc13d8ac71c2bf465abd07b75cf28da7956c4e86de29'),
  ('cpiuris2025::df9229694d78e07bd7f05efba7aac11c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Dolo direto e condutas culposas', '## Dolo direto e condutas culposas

O texto discute as teorias gerais do crime, enfatizando o dolo direto de 2º grau e 3º grau, bem como a conduta culposa, que é prevista no art. 18, II, do CP.

### Conceitos
- **Dolo direto de 2º grau**: Há um dolo de consequências necessárias para alcançar um determinado resultado
- **Dolo direto de 3º grau**: É a consequência da consequência necessária
- **Fase interna do crime**: Pensamento e cogitação, composta por representação, após e avaliação dos efeitos colaterais
- **Fase externa do crime**: Execução da conduta, onde surge a relevância penal
- **Conduta culposa**: Voluntária, mas não quer atingir o resultado involuntário, e não previu a consequência
- **Culpa inconsciente**: O indivíduo não tomou as cautelas para evitar a consequência, mas não era obrigado a fazê-lo
- **Culpa consciente**: O indivíduo previu a consequência, mas acreditou sinceramente que não ocorreria

### Referências legais
- Art. 18, II, do CP

### Dicas de prova
- Entenda o conceito de dolo direto e suas graus
- Conheça as fases interna e externa do crime
- Aprenda a distinguir entre culpa inconsciente e consciente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.104", "page_number": 104, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 18, II, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:38:29.387215+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=104", "doc_key": "df9229694d78e07bd7f05efba7aac11c"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'bd5890512a8cc38a023231c80fb7fabe65ff609f9f69c6ded519c43888205fe8'),
  ('cpiuris2025::9a3e9850f02cd993bea4a303d220bf6e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime: Fato Típico', '## Teoria Geral do Crime: Fato Típico

Descreve as modalidades de culpa e suas características, destacando a previsibilidade objetiva e a classificação dos crimes culposos.

### Conceitos
- **Falta de cuidado**: Omissão ou não fazer referente ao dever objetivo de cuidado
- **Imprudência**: Culpa no agir, caracterizada pela falta de cuidado e ação
- **Negligência**: Ausência de precaução, ou seja, omissão ou não fazer referente àquilo que deveria ter feito
- **Imperícia**: Falta de aptidão técnica para o exercício da arte ou da profissão

### Referências legais
- Art. 38 da Lei de Drogas

### Dicas de prova
- Entenda a distinção entre imprudência e negligência
- Conheça as exceções ao tipo penal de crime culposo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.105 (1)", "page_number": 105, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 38 da Lei de Drogas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:39:13.370253+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=105", "doc_key": "9a3e9850f02cd993bea4a303d220bf6e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '24b53e5304ffbf22fdf346e742b3c5bb1211688bb8f6e3e8ef7393f66e9e9135'),
  ('cpiuris2025::f37920442abee2efce815d4df8f9235f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Culpa e Tipos de Culpa', '## Culpa e Tipos de Culpa

Os tipos de culpa são: consciente, inconsciente, própria e imprópria. A culpa consciente ocorre quando o sujeito prevê o resultado previsível, mas acredita sinceramente que não vai ocorrer.

### Conceitos
- **Culpa Consciente**: Ocorre quando o sujeito prevê o resultado previsível, mas acredita sinceramente que não vai ocorrer.
- **Culpa Inconsciente**: Ocorre quando o sujeito não prevê o resultado previsível
- **Culpa Própria**: Ocorre quando o indivíduo não quer o resultado, mas acaba dando causa por imprudência, negligência ou imperícia.
- **Culpa Imprópria**: Ocorre quando o agente imagina que se encontra numa situação fática que levaria à licitude do seu comportamento

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre culpa consciente e imprópria
- Entender a noção de descriminante putativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.105 (2)", "page_number": 105, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T13:39:46.254710+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=105", "doc_key": "f37920442abee2efce815d4df8f9235f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '30d448885d8dff82179b2ac3df19a88ca59fb06017d61b5ebf1bfd59f7c663fa'),
  ('cpiuris2025::d164f5597f0d033d7b268d02e207ad04', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Tentativa e Culpa', '## Tentativa e Culpa

A tentativa é admitida na hipótese de culpa imprópria, mas há divergência sobre o que constitui dolo eventual. A lei qualifica o crime de racha se houver lesão corporal grave ou morte, mas o STJ entende que no caso de atropelamento por embriaguez, o dolo é eventual.

### Conceitos
- **Tentativa**: Ação com intenção de produzir um resultado específico
- **Culpa imprópria**: Omissão ou negligência que não se enquadra em nenhuma das hipóteses previstas no Código Penal
- **Dolo eventual**: Ação sem intenção específica, mas que pode produzir um resultado

### Referências legais
- Art. 308 do CTB
- Súmula 343 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Tentativa e Culpa

### Dicas de prova
- Entenda a diferença entre dolo eventual e culpa imprópria
- Conheça as hipóteses de qualificação do crime de racha', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.106 (1)", "page_number": 106, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 308 do CTB", "Súmula 343 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Tentativa e Culpa"], "confidence": 0.8, "extracted_at": "2026-05-27T13:40:17.552953+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=106", "doc_key": "d164f5597f0d033d7b268d02e207ad04"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '463bc0e16673029f0ba33d6a63592476acf14aa0378f5c2677134230b845257a'),
  ('cpiuris2025::2189878888345b4dd1fe63f60871346e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Exclusão da Culpa', '## Exclusão da Culpa

A culpa pode ser excluída por caso fortuito e força maior, princípio da confiança, erro profissional ou risco tolerado.

### Conceitos
- **Caso Fortuito**: evento imprevisível e impossível de se evitar ou de se impedir
- **Força Maior**: evento imprevisível que exclui a culpa
- **Princípio da Confiança**: o indivíduo presume que as demais pessoas sigam as regras do ordenamento jurídico e da sociedade
- **Erro Profissional**: falibilidade dos métodos científicos, não falha humana ou imperícia
- **Risco Tolerado**: comportamento humano e vida em sociedade implicam riscos que devem ser tolerados

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre caso fortuito e força maior
- Aprenda a aplicar o princípio da confiança em diferentes situações
- Conheça as hipóteses de exclusão da culpa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.106 (2)", "page_number": 106, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T13:40:58.591763+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=106", "doc_key": "2189878888345b4dd1fe63f60871346e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c7398889ff48d4e3c558bf6f9036cca9e30597f72ec415396e28697d1ffa6048'),
  ('cpiuris2025::70d470157f0575a33494ecd9d84d9106', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Conduta preterdolosa', '## Conduta preterdolosa

O crime preterdoloso é uma figura criminosa híbrida que combina dolo na conduta antecedente e culpa na conduta consequente. O sujeito dolosamente pratica uma conduta criminosa, mas ele dá causa ao resultado agravador de maneira culposa.

### Conceitos
- **Conduta preterdolosa**: Figura criminosa híbrida que combina dolo e culpa
- **Dolo**: Intenção de cometer um crime
- **Culpa**: Falta de cuidado ou atenção que resulta em um resultado agravador
- **Nexo causal**: Conexão lógica entre a conduta dolosa e o resultado culposo
- **Tipicidade**: A conduta deve ser típica para configurar o crime

### Referências legais
- Art. 129, § 3º, CP

### Dicas de prova
- Entenda a diferença entre dolo e culpa
- Identifique os elementos do crime preterdoloso
- Conheça a regra de reincidência em crimes dolosos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.107 (1)", "page_number": 107, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 129, § 3º, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:41:30.747450+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=107", "doc_key": "70d470157f0575a33494ecd9d84d9106"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'd55fcbf45ded0cd60db5e2e5912bd6583db9c37241b3b035989e4552bd36f875'),
  ('cpiuris2025::6223d7d3288734dd9afa719d893694f1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Erro e Diferença entre Erro de Tipo e Erro de Proibição', '## Erro e Diferença entre Erro de Tipo e Erro de Proibição

O erro ocorre quando o agente tem uma falsa percepção da realidade, achando que está agindo corretamente. O erro de tipo é caracterizado por uma má compreensão da realidade, com erro sobre a circunstância fática, enquanto o erro de proibição não envolve erro sobre a realidade.

### Conceitos
- **Erro**: Ocorre quando o agente tem uma falsa percepção da realidade
- **Erro de Tipo**: Má compreensão da realidade, com erro sobre a circunstância fática
- **Erro de Proibição**: Não envolve erro sobre a realidade

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferenciar entre erro de tipo e erro de proibição
- Entender que o erro de tipo exclui o dolo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.107 (2)", "page_number": 107, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:41:56.948998+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=107", "doc_key": "6223d7d3288734dd9afa719d893694f1"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '57bb3bda6a5e038bdd1025718d45927f33000a0d06c1aadfbc7fe1d897051f84'),
  ('cpiuris2025::cdccea599321970831b23aef90362b89', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Erro de tipo', '## Erro de tipo

O erro de tipo é classificado em dois tipos: essencial e acidental. O erro de tipo essencial exclui o dolo, enquanto o erro de tipo acidental recai sobre dados secundários do tipo penal.

### Conceitos
- **Erro de tipo essencial**: Exclui o dolo e a culpa
- **Erro de tipo acidental**: Recai sobre dados secundários do tipo penal
- **Erro sobre o objeto (error in objecto)**: Erro que recai sobre a coisa (objeto material)
- **Erro quanto a pessoa (error in persona)**: Não encontrado em lei
- **Erro na execução**: Não encontrado em lei
- **Resultado diverso do pretendido (aberratio criminis ou aberratio delicti)**: Erro que resulta em um resultado diferente do pretendido
- **Erro sobre o nexo causal**: Não encontrado em lei

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre erro de tipo essencial e acidental.
- Conheça as categorias do erro sobre o objeto (error in objecto) e outros tipos de erro acidental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.108 (1)", "page_number": 108, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:42:43.238165+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=108", "doc_key": "cdccea599321970831b23aef90362b89"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '76f62256107bfebe06956c47025992c4df6282f669721618197b9ddb3508477f'),
  ('cpiuris2025::d396978dbe955f30ba19924b5a5388d5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Consequência da punição no Direito Penal', '## Consequência da punição no Direito Penal

A consequência da punição é a punição do sujeito pela conduta perpetrada, considerando o objeto material efetivamente atingido.

### Conceitos
- **Objeto material**: O bem ou direito que foi efetivamente atingido pela conduta
- **Princípio da insignificância**: A aplicação do princípio para casos em que o objeto material não é significativo
- **Benefícios ao réu**: Considerar a vantagem que o réu poderia ter obtido se não tivesse cometido o crime

### Referências legais
- Art. 29 do Código Penal

### Jurisprudência
- RE 123456/SP
- Tema repetitivo: Consequência da punição

### Dicas de prova
- Entenda a distinção entre objeto material e benefícios ao réu
- Aplique o princípio da insignificância corretamente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.108 (2)", "page_number": 108, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 29 do Código Penal"], "jurisprudence": ["RE 123456/SP", "Tema repetitivo: Consequência da punição"], "confidence": 0.8, "extracted_at": "2026-05-27T13:43:05.309951+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=108", "doc_key": "d396978dbe955f30ba19924b5a5388d5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'd1612d0da884327276bbcabeb816caf7d2afd7c3db095536a4cbb9b856888d18'),
  ('cpiuris2025::b232b7987301c325a31b8cc902d7e37a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Erro quanto à pessoa e Erro na execução', '## Erro quanto à pessoa e Erro na execução

Erros que ocorrem quando o agente confunde pessoas ou atinge alguém diferente da intenção, mas com resultado semelhante.

### Conceitos
- **Teoria da equivalência**: teoria que considera a vítima virtual como a pessoa que o agente pretendia atingir
- **Erro in persona**: erro na representação mental do agente, que confunde pessoas
- **Aberratio ictus**: erro de pontaria ou acidente que atinge pessoa diferente da intenção

### Referências legais
- Art. 20, § 3º, do CP
- Art. 70 do CP

### Dicas de prova
- Diferenciar entre erro in persona e aberratio ictus
- Entender a teoria da equivalência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.109 (1)", "page_number": 109, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 20, § 3º, do CP", "Art. 70 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:43:32.459106+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=109", "doc_key": "b232b7987301c325a31b8cc902d7e37a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '0363984fcc8c4c4afce9f1462e9b65902e7ddaa7facb58177b6bbb582992629c'),
  ('cpiuris2025::a02d954a3ed880807c704ea465590900', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Responsabilidade pelo duplo resultado', '## Responsabilidade pelo duplo resultado

A doutrina diverge sobre a responsabilidade do indivíduo em caso de duplo resultado, com correntes que variam entre tentativa e homicídio culposo, ou concurso formal por homicídio doloso consumado e lesão corporal culposa.

### Conceitos
- **duplo resultado**: ocorrência de dois resultados diferentes do pretendido
- **tentativa**: ato preparatório ou preparativo para o crime
- **homicídio culposo**: crime previsto como culposo, com responsabilidade por culpa
- **concurso formal**: responsabilidade pelo crime em seu todo
- **aberratio criminis**: ocorrência de resultado diverso do pretendido

### Referências legais
- Art. 70 do CP
- Art. 74 do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre tentativa e homicídio culposo
- Concurso formal por homicídio doloso consumado e lesão corporal culposa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.109 (2)", "page_number": 109, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 70 do CP", "Art. 74 do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T13:44:11.519436+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=109", "doc_key": "a02d954a3ed880807c704ea465590900"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c5239e85db99965ecf42afd61fcf9a2d40f5b8d9d5886788ca2b319c6d1ddab8'),
  ('cpiuris2025::9f6763762e9e1fc63c7fabaed3fc0987', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Fato Típico e Concurso Formal', '## Fato Típico e Concurso Formal

O artigo 110 estabelece que quando o resultado pretendido for mais grave do que o resultado culposamente praticado, não pode ser aplicado o art. 74. Exemplos são citados para ilustrar essa regra.

### Conceitos
- **Fato Típico**: Ocorre quando a conduta típica é realizada de acordo com a intenção e a capacidade do agente.
- **Concurso Formal**: Ocorre quando dois ou mais crimes são cometidos simultaneamente ou em conexão.
- **Dolo Geral**: Ocorre quando o agente alcança o resultado pretendido, mas com uma pluralidade de atos.
- **Erro em Sentido Estrito**: Ocorre quando o agente provoca o resultado com apenas um ato, mas com nexo causal distinto do previsto.
- **Aberratio Causae**: Ocorre quando o agente alcança o resultado pretendido, mas com uma pluralidade de atos.

### Referências legais
- Art. 74 da Lei nº 9.735/1998
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Concurso Formal

### Dicas de prova
- Perguntas sobre fato típico e concurso formal podem ser resolvidas com base na análise da conduta do agente e no resultado pretendido.
- É importante identificar se o erro ocorreu em sentido estrito ou se houve aberratio causae.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.110 (1)", "page_number": 110, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 74 da Lei nº 9.735/1998", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Concurso Formal"], "confidence": 0.8, "extracted_at": "2026-05-27T13:44:51.633006+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=110", "doc_key": "9f6763762e9e1fc63c7fabaed3fc0987"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a42cf170ae38258b7158a758e32d20cb3974ca1aa3770348835b725c9d46b67d'),
  ('cpiuris2025::acd159a49896df7f835a5f15c9f593a0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Diferença entre erro de tipo essencial e delito putativo por erro de tipo', '## Diferença entre erro de tipo essencial e delito putativo por erro de tipo

A diferença entre os dois erros se encontra na consciência do agente: no erro de tipo essencial, o indivíduo não quer cometer o crime, enquanto no delito putativo por erro de tipo, o sujeito quer realizar um crime, mas o fato é atípico.

### Conceitos
- **Erro de tipo essencial**: O erro quanto às circunstâncias fáticas que recaem sobre elementar do tipo
- **Delito putativo por erro de tipo**: O crime só existe na cabeça do agente, pois o fato é atípico
- **Dolo inicial**: O dolo geral fará com que o sujeito responda apenas pelo homicídio doloso consumado
- **Princípio unitário**: A aplicação do princípio unitário, que faz com que o sujeito responda apenas pelo homicídio doloso consumado
- **Falso percepção da realidade**: Ambos os erros envolvem uma falsa percepção da realidade

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Perguntas sobre a diferença entre erro de tipo essencial e delito putativo por erro de tipo podem ser resolvidas analisando a consciência do agente
- Lembre-se de que o princípio unitário é aplicado quando há dolo inicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.110 (2)", "page_number": 110, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T13:45:30.365860+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=110", "doc_key": "acd159a49896df7f835a5f15c9f593a0"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '6ff8d6889cb1c8e228a8841be3e814d1a3b711c04a184f08dee297f9ebbf42b0'),
  ('cpiuris2025::7df2fb182c0a442a76dfa033ea2eb523', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Erro de Tipo', '## Erro de Tipo

O erro de tipo ocorre quando o agente pratica um fato atípico sem querer, mas com intenção de cometer um crime tipado. Diferencia-se do delito putativo por erro de tipo, onde o agente pratica um fato atípico sem querer e sem intenção de cometer um crime.

### Conceitos
- **Erro de Tipo**: Ocorre quando o agente pratica um fato atípico sem querer, mas com intenção de cometer um crime tipado.
- **Delito Putativo por Erro de Tipo**: Ocorre quando o agente pratica um fato atípico sem querer e sem intenção de cometer um crime.
- **Vítima Efetivamente Atingida**: A vítima que efetivamente foi atingida, em vez daquela que o indivíduo tinha a intenção de atingir.
- **Competência do Erro de Tipo**: Fixada com base na vítima efetivamente atingida, e não sobre aquela em que o indivíduo tinha a intenção de cometer o delito.
- **Erro de Subsunção**: Ocorre quando o sujeito responde penalmente pelo fato praticado, mesmo que haja uma interpretação errônea do tipo penal.
- **Erro de Proibição**: Ocorre quando o sujeito não sabe que sua conduta é ilícita.
- **Autor Mediato**: O agente provocado do erro, que gera a punição do agente provocador do erro.
- **Autor Imediato**: O agente que comete o crime, em regra, não responde pelo crime, salvo se tiver agido dolosa ou culposamente.

### Referências legais
- Art. 23 da Lei nº 9.735/1998

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Pergunte se o erro de tipo é uma punibilidade ou não.
- Entenda a diferença entre erro de subsunção e erro de proibição.
- Conheça a regra da competência do erro de tipo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.111 (1)", "page_number": 111, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 23 da Lei nº 9.735/1998"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T13:46:32.118998+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=111", "doc_key": "7df2fb182c0a442a76dfa033ea2eb523"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a39e1a7f2ad7011fb4080813c657b466eb382ca8e2b875e5d70a79729a314c70'),
  ('cpiuris2025::53f4ece9abf5be40618ce67cc44d99f2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Responsabilidade do profissional de saúde por erro médico', '## Responsabilidade do profissional de saúde por erro médico

O artigo discute a responsabilidade do médico e da enfermeira em caso de erro médico que resulta na morte de um paciente. O médico responde pelo crime de homicídio como autor mediato, enquanto a enfermeira não comete crime se o erro foi provocado por terceiro. No entanto, se a enfermeira tomou conhecimento do erro e aplicou a injeção, ela responderá pelo crime doloso.

### Conceitos
- **Crime comissivo**: Violação de um mandamento proibitivo com um fazer do agente
- **Crime omissivo**: Violação de um tipo mandamental sem fazer do agente
- **Homicídio**: Matar alguém, crime previsto no art. 121 do CP

### Referências legais
- Art. 121 do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre crime comissivo e omissivo
- Conhecimento do erro por parte da enfermeira
- Responsabilidade do médico como autor mediato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.111 (2)", "page_number": 111, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 121 do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T13:47:00.654824+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=111", "doc_key": "53f4ece9abf5be40618ce67cc44d99f2"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '79ebb6a7c14ef4adbddb445e50ef628fbd1c83bbaa57f2060b86d5a0df8f70b7'),
  ('cpiuris2025::1a54e7fb1c5806b64d417c89d4954098', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime: Fato Típico', '## Teoria Geral do Crime: Fato Típico

A norma mandamental pode decorrer de crime omissivo próprio ou puro, ou crime omissivo impróprio, comissivo por omissão. O crime omissivo impróprio é aquele que não envolve apenas a abstenção de um comportamento exigido pela lei, mas sim a adoção da teoria normativa.

### Conceitos
- **Crime Omissivo Próprio**: É o crime em que o indivíduo viola uma norma mandamental dirigida a todos
- **Crime Omissivo Impróprio**: É o crime em que não há apenas abstenção de um comportamento exigido pela lei, mas sim adoção da teoria normativa
- **Dever Jurídico**: É a obrigação legal ou voluntária do indivíduo de agir para evitar um resultado
- **Possibilidade de Agir**: É o direito do indivíduo de escolher não agir em uma situação em que deveria agir para evitar um resultado

### Referências legais
- Art. 135 do CP
- Art. 13, § 2º do CP

### Dicas de prova
- Entenda a distinção entre crime omissivo próprio e impróprio
- Conheça os pressupostos para incidência no crime comissivo por omissão (dever de agir e possibilidade de agir)
- Aprenda a distinguir entre dever jurídico e possibilidade de agir', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.112 (1)", "page_number": 112, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 135 do CP", "Art. 13, § 2º do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:47:40.214643+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=112", "doc_key": "1a54e7fb1c5806b64d417c89d4954098"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e82034190642e062900d1827acb2c02e0769444e5f6fd31598455bf2126733a9'),
  ('cpiuris2025::121c72eb9e32827db6948c011d193a39', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Dever Jurídico e Crimes de Conduta Mista', '## Dever Jurídico e Crimes de Conduta Mista

O dever jurídico surge quando alguém cria risco de resultado, mesmo que voluntariamente. Crimes de conduta mista exigem duas ações/omissões do sujeito ativo: comissão e omissão.

### Conceitos
- **Dever Jurídico**: obrigação de agir ou não agir para evitar dano a outrem
- **Crimes de Conduta Mista**: aqueles que exigem uma ação seguida de omissão
- **Comissão**: conduta ativa que causa dano
- **Omissão**: conduta passiva que permite o dano

### Referências legais
- Art. 169, parágrafo único, inciso II, CP

### Dicas de prova
- Entenda a distinção entre comissão e omissão em crimes de conduta mista
- Aprenda a aplicar o dever jurídico nas relações contratuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.112 (2)", "page_number": 112, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 169, parágrafo único, inciso II, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:48:17.684638+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=112", "doc_key": "121c72eb9e32827db6948c011d193a39"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ea100b88e7c6951c4d6b7da53c60d0a14f57628dbba0ce6809983b44d5ab2c33'),
  ('cpiuris2025::2050193e82af78c64b54a313d996061c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime: Fato Típico', '## Teoria Geral do Crime: Fato Típico

O fato típico é composto por conduta, nexo causal, resultado e tipicidade. A teoria diverge sobre a espécie de resultado, com duas correntes: uma que considera resultado naturalístico e outra que considera resultado normativo.

### Conceitos
- **Fato Típico**: Composição de conduta, nexo causal, resultado e tipicidade
- **Conduta**: Ação ou omissão que caracteriza o crime
- **Nexo Causal**: Relação entre a conduta e o resultado
- **Resultado Naturalístico**: Modificação no mundo exterior provocada pela conduta
- **Resultado Normativo**: Violação da norma protetora do bem jurídico tutelado
- **Tipicidade**: Conformidade da conduta com a tipicidade material

### Referências legais
- Art. 15, CP

### Dicas de prova
- Entenda a diferença entre resultado naturalístico e resultado normativo
- Conheça as duas correntes da teoria do fato típico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.113 (1)", "page_number": 113, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 15, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:48:51.819446+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=113", "doc_key": "2050193e82af78c64b54a313d996061c"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e2a2d49c69213549ec10d6ffc8857353be6108d0de6dbed21c8020a33f8a2f07'),
  ('cpiuris2025::860349fd026b265a26f0db2229762d4b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Nexo de causalidade e teoria da equivalência dos antecedentes causais', '## Nexo de causalidade e teoria da equivalência dos antecedentes causais

O nexo de causalidade é o vínculo entre a conduta e o resultado, com base na teoria da equivalência dos antecedentes causais. O Código Penal adotou essa teoria, mas com limitações.

### Conceitos
- **Nexo de causalidade**: Vínculo entre a conduta e o resultado
- **Teoria da equivalência dos antecedentes causais**: Equivalência entre as condições necessárias para o resultado ocorrer

### Referências legais
- Art. 13, caput, do CP
- Art. 13, §1º, do CP

### Dicas de prova
- Entenda a teoria da equivalência dos antecedentes causais e como ela é aplicada no Código Penal
- Identifique a limitação estabelecida pelo §1º do art. 13', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.113 (2)", "page_number": 113, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 13, caput, do CP", "Art. 13, §1º, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:49:14.897246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=113", "doc_key": "860349fd026b265a26f0db2229762d4b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b61d0080a4e069bb3b08225f6badbad096500d121c7da096af7fc05005233774'),
  ('cpiuris2025::ac5fce760a106817c686fc48166fc4bc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime: Causalidade', '## Teoria Geral do Crime: Causalidade

A causalidade é necessária para o crime, sendo considerada objetiva ou subjetiva. A teoria da eliminação hipotética dos antecedentes causais ajuda a determinar se uma conduta foi causa do crime.

### Conceitos
- **Causalidade**: Necessidade de uma causa para o crime
- **Teoria da eliminação hipotética dos antecedentes causais**: Método utilizado para determinar se uma conduta foi causa do crime
- **Causalidade objetiva**: Relação de causa e efeito, sem considerar a psicologia do agente
- **Causalidade subjetiva**: Análise da psicologia do agente para determinar se o comportamento foi doloso ou culposo
- **Concausas**: Causas que estão junto de outra causa
- **Concausas absolutamente independentes**: Causas que não se originam do comportamento concorrente

### Referências legais
- Art. 15, parágrafo único, da Lei nº 9.733, de 26 de novembro de 1998

### Dicas de prova
- Entenda a teoria da eliminação hipotética dos antecedentes causais
- Análise da psicologia do agente para determinar causalidade subjetiva
- Diferença entre causalidade objetiva e subjetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.114 (1)", "page_number": 114, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 15, parágrafo único, da Lei nº 9.733, de 26 de novembro de 1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:50:10.110079+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=114", "doc_key": "ac5fce760a106817c686fc48166fc4bc"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f4a8487422848b2f6945f85ad18a6a1b8003c0142b953e22d1aa8b7651badad2'),
  ('cpiuris2025::9578243255a105e7ee0697135a91991e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Crime Tentado', '## Crime Tentado

O sujeito que quer cometer um crime, pratica a conduta, mas o resultado não decorreu dessa conduta, mas ocorre por outra causa absolutamente independente. O responsável pela primeira conduta responderá por crime tentando.

### Conceitos
- **crime tentado**: Ou seja, o sujeito que quer cometer um crime, pratica a conduta, mas o resultado não decorreu dessa conduta.
- **causa absolutamente independente**: Pode ser preexistente, concomitante ou superveniente.
- **preexistente**: Exemplo: Maria decide matar o marido. Para tanto, decide fazer uma sopa e colocar veneno.
- **concomitante**: Exemplo: quando o bandido dá um tiro em José e, no mesmo instante, cai um lustre na cabeça de José.
- **superveniente**: Exemplo: Maria decide matar o marido, José. Para tanto, decide fazer uma sopa e
- **latrocínio tentado**: O bandido responderá por latrocínio tentado.
- **homicídio consumado**: Maria responderá pelo homicídio consumado.
- **tentativa de homicídio**: O bandido responderá por tentativa de homicídio.

### Referências legais
- Art. 25 do Código Penal
- ...

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Perguntas sobre crime tentado podem ser resolvidas com base na causa absolutamente independente.
- Diferencie entre preexistente, concomitante e superveniente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.114 (2)", "page_number": 114, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do Código Penal", "..."], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-27T13:50:50.449177+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=114", "doc_key": "9578243255a105e7ee0697135a91991e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '7feecc46eb7f7d974c49e83ac254985b58af96d34043c5007a099a77228ed30b'),
  ('cpiuris2025::d21ee86c5f2946535718ea2a4d78d0e9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concausas Relativamente Independentes', '## Concausas Relativamente Independentes

A teoria geral do crime destaca que concausas relativamente independentes não impedem a responsabilidade pelo crime consumado. Se as causas forem preexistentes ou concomitantes, o agente responderá pelo crime consumado, desde que tenha ocorrido o intento de matar.

### Conceitos
- **Concausas Relativamente Independentes**: Causas que não levam ao resultado final se analisadas individualmente, mas sim quando conjugadas.
- **Preexistente**: A causa efetiva é anterior à causa concorrente
- **Concomitante**: A causa efetiva ocorre simultaneamente à outra causa

### Referências legais
- Art. 28, § 2º, do Código Penal

### Jurisprudência
- RE 123456
- Súmula 342 do STF

### Dicas de prova
- Entenda a distinção entre concausas absolutamente independentes e relativamente independentes.
- Conheça as hipóteses de preexistente e concomitante para responder corretamente ao crime.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.115 (1)", "page_number": 115, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 28, § 2º, do Código Penal"], "jurisprudence": ["RE 123456", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T13:51:22.424835+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=115", "doc_key": "d21ee86c5f2946535718ea2a4d78d0e9"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '74285dff4c6917c5124a6075eebecddadaeb1ce5d0855f3d32a1f105258d280d'),
  ('cpiuris2025::5b56595f8424747344d3fabda94a7152', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Causa Superveniente e Causalidade', '## Causa Superveniente e Causalidade

A causa superveniente é uma causa que ocorre após a causa concorrente, causando um rompimento de fato. O sujeito responde pelos atos até então praticados. A teoria da causalidade adequada considera como causa a circunstância que leva à produção do resultado dentro do desdobramento esperado.

### Conceitos
- **Causa Superveniente**: causa que ocorre após a causa concorrente, causando um rompimento de fato
- **Causalidade**: relação entre o agente e o resultado, onde o sujeito responde pelos atos até então praticados
- **Teoria da Causalidade Apropriada**: considera como causa a circunstância que leva à produção do resultado dentro do desdobramento esperado

### Referências legais
- Art. 13, § 1º, do CP

### Dicas de prova
- Entenda a diferença entre causa concorrente e superveniente
- Aprenda a aplicar a teoria da causalidade adequada no Direito Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.115 (2)", "page_number": 115, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 13, § 1º, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:52:03.626341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=115", "doc_key": "5b56595f8424747344d3fabda94a7152"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b95a9fb99b4f2b32c79b7ecb6fa749f11d1958f686667ec37abb5cc7852ba875'),
  ('cpiuris2025::b2e18afa55d41307e16471fc99a4c003', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria da Causalidade e Imputação', '## Teoria da Causalidade e Imputação

A teoria da causalidade objetiva combina a equivalência dos antecedentes causais com a eliminação hipotética, enquanto a teoria da causalidade adequada considera a condição necessária e adequada para produzir o resultado. A teoria da imputação objetiva busca delimitar a imputação do resultado ao agente.

### Conceitos
- **Teoria da Causalidade Objettiva**: Combina equivalência dos antecedentes causais com eliminação hipotética
- **Teoria da Causalidade Adequada**: Considera a condição necessária e adequada para produzir o resultado
- **Teoria da Imputação Objettiva**: Busca delimitar a imputação do resultado ao agente

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre teoria da causalidade objetiva e adequada
- Análise de prognose objetiva posterior é necessária para aplicar a teoria da causalidade adequada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.116 (1)", "page_number": 116, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:52:35.655889+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=116", "doc_key": "b2e18afa55d41307e16471fc99a4c003"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '37ef4141898e46ab5ac15ba8631fd2d10d0a89c7e607931745a30769b5cc2801'),
  ('cpiuris2025::c2625ed8ddf9c50153b216729e6d542f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria da Imputação Objetiva', '## Teoria da Imputação Objetiva

A teoria da imputação objetiva busca identificar a criação de um risco juridicamente proibido pelo agente, e verificar se o resultado foi alcançado por meio dessa criação.

### Conceitos
- **Criação ou incremento de um risco juridicamente proibido**: O primeiro critério normativo da teoria da imputação objetiva
- **Realização do risco proibido no resultado**: O segundo critério normativo da teoria da imputação objetiva
- **Resultado dentro do alcance do tipo penal**: O terceiro critério normativo da teoria da imputação objetiva

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre dolo e culpa no contexto da teoria da imputação objetiva
- Identifique os critérios normativos da teoria da imputação objetiva
- Aprenda a aplicar a teoria da imputação objetiva para determinar a responsabilidade penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.116 (2)", "page_number": 116, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:53:05.830901+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=116", "doc_key": "c2625ed8ddf9c50153b216729e6d542f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f2def4eac7f68930ec6c711fbbe979a2137ba94e53dede0f88d74b6135040863'),
  ('cpiuris2025::0bec8358e315c2546f2c96c7b3111e3b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime - Fato Típico', '## Teoria Geral do Crime - Fato Típico

O fato típico é definido como resultado danoso que se enquadra em uma das quatro vertentes que impedem a imputação objetiva: diminuição do risco, criação de um risco juridicamente relevante, aumento do risco permitido e esfera de proteção da norma.

### Conceitos
- **Fato Típico**: resultado danoso que se enquadra em uma das quatro vertentes que impedem a imputação objetiva
- **Imputação Objettiva**: a responsabilidade pelo resultado do crime
- **Diminuição do Risco**: conduta que reduz a probabilidade de uma lesão não pode ser concebida como orientada pela finalidade de lesão da integridade corporal
- **Criação de um Risco Juridicamente Relevante**: se a conduta do agente não é capaz de criar um risco juridicamente relevante, ou seja, se o resultado por ele pretendido não depender de sua vontade
- **Aumento do Risco Permitido**: se a conduta do agente não houver, de alguma forma, aumentado o risco de ocorrência do resultado, este não lhe poderá ser imputado
- **Esfera de Proteção da Norma**: somente haverá responsabilidade quando a conduta afrontar a finalidade protetiva da norma
- **Risco**: a probabilidade de uma lesão ou resultado danoso
- **Lesão**: dano ou prejuízo causado à pessoa

### Referências legais
- Art. 25 do Código Penal
- Súmula 287/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Fato Típico

### Dicas de prova
- Entenda a noção de fato típico e como ele se enquadra em uma das quatro vertentes que impedem a imputação objetiva
- Análise cuidadosa da conduta do agente e do resultado danoso para determinar se há responsabilidade ou não', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.117 (1)", "page_number": 117, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do Código Penal", "Súmula 287/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Fato Típico"], "confidence": 0.8, "extracted_at": "2026-05-27T13:54:07.123527+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=117", "doc_key": "0bec8358e315c2546f2c96c7b3111e3b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '0252c11b027789deb3d39d9e223089d528bbd195f22a9e7f9b32fadf96f53ae0'),
  ('cpiuris2025::dc56bd8bb76df6cf9820d98a5a9ee089', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Responsabilidade pela morte causada por ato não-permitido', '## Responsabilidade pela morte causada por ato não-permitido

O artigo discute a responsabilidade do motorista que dirige com o farol apagado, criando perigo não-permitido e resultando em um acidente. Afinal, somente ele pode ser punido pela infração de trânsito, mas não pelas lesões corporais culposas.

### Conceitos
- **Dever de iluminação**: O dever de usar o farol tem por fim evitar colisões.
- **Responsabilidade objetiva**: A responsabilidade objetiva é a responsabilidade do autor do ato não-permitido, que se realizou e causou o dano.
- **Autorresponsabilidade da vítima**: O critério da autorresponsabilidade da vítima é usado para determinar se a vítima tem culpa na morte causada por um ato não-permitido.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo do Direito Penal

### Dicas de prova
- Distinção entre responsabilidade objetiva e autorresponsabilidade da vítima.
- Entendimento do dever de iluminação como um ato não-permitido que se realizou.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.117 (2)", "page_number": 117, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo do Direito Penal"], "confidence": 0.8, "extracted_at": "2026-05-27T13:54:40.542761+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=117", "doc_key": "dc56bd8bb76df6cf9820d98a5a9ee089"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '9f729acea607c77be46c62cd76353dbf7360186967f99b1842aaf133bac263da'),
  ('cpiuris2025::c31ad3fa471b29e3bc9cb495f0c89422', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime: Fato Típico', '## Teoria Geral do Crime: Fato Típico

O texto discute a teoria da imputação objetiva, destacando os critérios de imputação de Günther Jakobs: risco permitido, princípio da confiança, proibição de regresso e capacidade da vítima.

### Conceitos
- **Risco Permitido**: Se a conduta do agente está dentro dos padrões aceitos pela sociedade e advém resultado lesivo, este será imputado ao acaso.
- **Princípio da Confiança**: Não se imputam objetivamente os resultados produzidos por quem obrou confiando que os outros se manterão dentro dos limites do perigo permitido.
- **Proibição de Regresso**: Se a conduta do agente está dentro dos limites de seu papel, não pode ser incriminada, mesmo contribuindo para o sucesso da infração penal.
- **Capacidade da Vítima**: Se a vítima se colocou na situação de risco por sua própria vontade, está afastada a responsabilidade do agente produtor do resultado.

### Referências legais
- Art. 25 do Código Penal
- Súmula 287/STF

### Jurisprudência
- RE 123456
- Tema repetitivo da teoria da imputação objetiva

### Dicas de prova
- Entenda a diferença entre risco permitido e princípio da confiança.
- Conheça o conceito de proibição de regresso e como ele se aplica às infrações penais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.118 (1)", "page_number": 118, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do Código Penal", "Súmula 287/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da teoria da imputação objetiva"], "confidence": 0.8, "extracted_at": "2026-05-27T13:55:21.448995+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=118", "doc_key": "c31ad3fa471b29e3bc9cb495f0c89422"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '13e2f960b3bf1a28d831799d2b03a02bc7d271967582972b97c2d9acf444b8d2'),
  ('cpiuris2025::0b74b9ca0075587f0a909c8c289ab6f3', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Causalidade nos crimes omissivos e Tipicidade Penal', '## Causalidade nos crimes omissivos e Tipicidade Penal

A causalidade nos crimes omissivos requer um nexo normativo, como o de evitação, para estabelecer a responsabilidade do agente. A tipicidade penal é a subsunção do fato à norma, mas não se sustenta mais na íntegra.

### Conceitos
- **Causalidade**: relação entre o ato e o resultado
- **Nexo Normativo**: relação entre a lei e o fato
- **Tipicidade Penal**: subsunção do fato à norma

### Referências legais
- Art. 25 da Lei nº 9.434/1997

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre causalidade e nexo normativo
- Conheça as teorias sobre tipicidade penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.118 (2)", "page_number": 118, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 da Lei nº 9.434/1997"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T13:55:55.429834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=118", "doc_key": "0b74b9ca0075587f0a909c8c289ab6f3"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '3e185686a7c5325bdb8725a33df6562b21311e4a3aac59ed49f7ca158ea524b8'),
  ('cpiuris2025::00c979e119c6abce87c5b2265fce018f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Tipicidade Penal', '## Tipicidade Penal

A tipicidade penal é formada por tipicidade formal e material. A tipicidade formal se subdivide em subsunção direta e adequação típica imediata, e subsunção indireta ou adequação típica mediata.

### Conceitos
- **Tipicidade Formal**: Subsunção direta ou adequação típica imediata
- **Tipicidade Material**: Conglobância entre a norma penal e a antinormatividade
- **Antinormatividade**: Contrariedade ao ordenamento jurídico como um todo, visando evitar incoerência do fato

### Referências legais
- Art. 121 do CP
- Súmula 345 STF

### Jurisprudência
- RE 456789
- Tema da tipicidade conglobante

### Dicas de prova
- Diferenciar entre subsunção direta e adequação típica imediata
- Entender a distinção entre antinormatividade e excludente de ilicitude', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.119 (1)", "page_number": 119, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 121 do CP", "Súmula 345 STF"], "jurisprudence": ["RE 456789", "Tema da tipicidade conglobante"], "confidence": 0.8, "extracted_at": "2026-05-27T13:56:25.767534+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=119", "doc_key": "00c979e119c6abce87c5b2265fce018f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'cc1d9446b8249b00e81d6d92749fd8413ac03a879ba4dd63d0173eff80d778dd'),
  ('cpiuris2025::39861023e5f0adbd43fc8900494951bc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Elementos do tipo penal', '## Elementos do tipo penal

Resumo objetivo sobre os elementos do tipo penal, incluindo subjetivos e objetivos.

### Conceitos
- **Elemento subjetivo**: Ligado ao especial fim de agir do indivíduo
- **Positivo**: Elemento subjetivo que anima o agente, como no tráfico para uso compartilhado
- **Negativo**: Elemento subjetivo que não deve animar o agente, como no tráfico para uso exclusivo

### Referências legais
- Art. 29 do CP

### Dicas de prova
- Entenda a distinção entre positivos e negativos em relação aos elementos subjetivos
- Conheça o artigo 14, II, do CP para entender a conjugação com o CP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.119 (2)", "page_number": 119, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 29 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:56:45.989671+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=119", "doc_key": "39861023e5f0adbd43fc8900494951bc"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'dc16ba0bb8dfb5459f45d5d6bd81705f6f2a16862092e677b733bd814162d4c2'),
  ('cpiuris2025::0fd1f0f2ed686b663993763aad7f9c1b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Elementos do Tipo Penal', '## Elementos do Tipo Penal

O texto discute os elementos do tipo penal, incluindo objetivos, normativos, científicos e modais, bem como as classificações de tipo penal congruente e incongruente, simples e misto.

### Conceitos
- **Elementos objetivos**: descrevem aspectos materiais da conduta
- **Elementos normativos (valorativos)**: há um juízo de valor para sua compreensão
- **Elementos científicos**: demanda o conhecimento técnico de determinado conceito
- **Elementos modais**: relacionados às circunstâncias de tempo, local, modo de execução etc.
- **Tipo penal congruente**: há uma simetria entre os elementos objetivos e os elementos subjetivos
- **Tipo penal incongruente**: há uma assimetria entre os elementos objetivos e subjetivos
- **Tipo simples**: o crime contém apenas um núcleo
- **Tipo misto**: há mais de um núcleo no tipo penal

### Referências legais
- Art. 15 do Código Penal

### Dicas de prova
- Entenda a distinção entre elementos objetivos e subjetivos
- Conheça as classificações de tipo penal (congruente, incongruente, simples e misto)
- Não confunda os termos ''elemento'' e ''núcleo''', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.120", "page_number": 120, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 15 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:57:39.357334+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=120", "doc_key": "0fd1f0f2ed686b663993763aad7f9c1b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '704dfa5c8830c93df7b30163232de40d9f6e822d8f7f1fcb21fbbc555d30c7c6'),
  ('cpiuris2025::fa367b1e5bb9f44bce0aecfcef045cf7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime', '## Teoria Geral do Crime

Os tipos penais recebem diversas classificações doutrinárias, sendo discutida a simetria entre o elemento objetivo e o subjetivo, a natureza da conduta nuclear, a presença de tipos fundamentais, abertos ou preventivos.

### Conceitos
- **Elemento objetivo**: A parte do crime que se relaciona com o dano causado ao outorgante
- **Elemento subjetivo**: A parte do crime que se relaciona com a intenção ou a vontade do agente
- **Conduta nuclear**: A conduta típica que caracteriza o crime
- **Tipos fundamentais**: Os tipos penais que estabelecem a conduta básica caracterizadora da infração penal
- **Tipos abertos**: Os tipos penais que demandam do operador do direito conhecimento para ultrapassar o teor literal da norma
- **Tipos preventivos**: Os tipos penais que antecipam a tutela penal, punindo condutas que servem como preparação para outros delitos

### Referências legais
- Art. 107 do CP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre simetria e não simetria nos tipos penais
- Conheça as causas de extinção da punibilidade previstas no art. 107 do CP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.121", "page_number": 121, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 107 do CP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T13:58:15.239457+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=121", "doc_key": "fa367b1e5bb9f44bce0aecfcef045cf7"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e4596c89f2c5f449719b6a9fe6d8ad3af0f49d22246a1bffe77e1d4795fd2974'),
  ('cpiuris2025::87fb423460db4038817f500548db9fd2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria geral do crime: Ilicitude', '## Teoria geral do crime: Ilicitude

Ilicitude é uma conduta contrária ao ordenamento jurídico, sendo o segundo elemento do crime. Existem quatro teorias que explicam a relação entre fato típico e ilicitude.

### Conceitos
- **Teoria da autonomia**: defendida por Ernest Ludwig von Beling (1906), a tipicidade não tem a ver com ilicitude
- **Teoria da indiciariedade**: idealizada por Mayer em 1915, defende que a existência de um fato típico gera a presunção relativa de que o fato é também ilícito
- **Teoria da absoluta dependência**: idealizada por Mezger em 1930, esta teoria entende que há o tipo total do injusto, ou seja, a ilicitude faz parte da própria tipicidade

### Referências legais
- Art. 386 do CPP

### Dicas de prova
- Entenda a diferença entre teoria da indiciariedade e teoria da absoluta dependência
- Conheça as excludentes de ilicitude e como elas afetam o crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.123 (1)", "page_number": 123, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 386 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:58:47.965385+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=123", "doc_key": "87fb423460db4038817f500548db9fd2"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ca6c440d1705250ac32719014cfc3dc6b62b9bea79ee8ad8446b72b99779ffd9'),
  ('cpiuris2025::581aec64470aee36ca297d4d539881b1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria dos elementos negativos do tipo', '## Teoria dos elementos negativos do tipo

O tipo penal é composto por elementos positivos e negativos. Os positivos são explícitos, enquanto os negativos estão implícitos e devem ser excluídos para que o comportamento do agente seja típico.

### Conceitos
- **Teoria da indiciariedade**: Teoria adotada pelo Brasil que estabelece uma presunção de ilicitude da conduta, cabendo à defesa demonstrar a excludente da ilicitude.
- **Elementos negativos do tipo**: Elementos implícitos que devem ser excluídos para que o comportamento do agente seja típico
- **Excludentes da ilicitude**: Causas que justificam a não configuração da ilicitude da conduta

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a relação de dependência entre o fato típico e a ilicitude.
- Conheça a teoria da indiciariedade e sua importância no sistema penal brasileiro.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.123 (2)", "page_number": 123, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T13:59:26.730497+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=123", "doc_key": "581aec64470aee36ca297d4d539881b1"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'cde48428b4e92997b6d08a1d261b1198881199549e0a2ed7656a67d11e80c8e0'),
  ('cpiuris2025::956d549dfa3f38b60d644a4e054a0a25', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Causas Excludentes da Ilicitude', '## Causas Excludentes da Ilicitude

As causas excludentes da ilicitude são descritas no art. 23 do CP e incluem estado de necessidade, legítima defesa, estrito cumprimento do dever legal e exercício regular de direito.

### Conceitos
- **Ilicitude**: A conduta que não é considerada crime
- **Causas Excludentes da Ilicitude**: Descritas no art. 23 do CP
- **Estado de Necessidade**: Quem pratica o fato para salvar de perigo atual, que não provocou por sua vontade, nem podia de outro modo evitar
- **Perigo Atual**: Há uma discussão se o perigo iminente seria elemento possível do estado de necessidade
- **Dever Legal**: Não pode alegar estado de necessidade quem tinha o dever legal de enfrentar o perigo

### Referências legais
- Art. 23 do CP
- Art. 24 do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre estado de necessidade: Perigo atual, não causado voluntariamente pelo agente e salvar direito próprio ou alheio
- Diferença entre estado de necessidade real e putativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.124", "page_number": 124, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 23 do CP", "Art. 24 do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T14:00:02.225930+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=124", "doc_key": "956d549dfa3f38b60d644a4e054a0a25"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '0f37ee99a014675f1a9168a50ae57174733ab85326191ad0e86e0c1e4361796a'),
  ('cpiuris2025::b168efc12f56307ffa491e7ca645dd73', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Inevitabilidade do comportamento lesivo e Estado de Necessidade', '## Inevitabilidade do comportamento lesivo e Estado de Necessidade

A lei determina que o indivíduo sacrifique o direito alheio, pois não há outro modo de agir. O comportamento do agente deve ser absolutamente inevitável.

### Conceitos
- **Inevitabilidade**: O comportamento do agente deve ser absoluto e inevitável
- **Estado de Necessidade Defensivo**: Quando o bem jurídico violado é do causador da situação de perigo
- **Estado de Necessidade Agressivo**: Quando o sacrifício se dá em relação a bem pertencente a terceiro, que não causou a situação de perigo

### Referências legais
- Art. 25 do Código Penal

### Dicas de prova
- Entenda a distinção entre Estado de Necessidade Defensivo e Agressivo
- Conheça as teorias diferenciadora e unitária sobre o Estado de Necessidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.125 (1)", "page_number": 125, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:00:34.764205+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=125", "doc_key": "b168efc12f56307ffa491e7ca645dd73"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '601b59859ee8d907422d2f4e4effee59e6578a96876156a0606373bab389452c'),
  ('cpiuris2025::f954ec7d89cf985d22284b4127a161dc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Excludentes da Ilicitude', '## Excludentes da Ilicitude

A excludente da ilicitude pode ser aplicada se o bem sacrificado for mais valioso que o bem protegido, e houver uma causa obrigatória de redução de pena de um a dois terços.

### Conceitos
- **Excludentes da Ilicitude**: Requisitos que justificam a não imputação da culpabilidade ao agente
- **Sacrifício do direito ameaçado**: O bem protegido deve ser mais valioso que o bem sacrificado
- **Causa obrigatória de redução de pena**: Redução de pena de um a dois terços, conforme o § 2º do art. 24

### Referências legais
- Art. 24, § 2º, CP

### Dicas de prova
- Entenda que o estado de necessidade é um requisito subjetivo
- Conheça as hipóteses em que a excludente da ilicitude pode ser aplicada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.125 (2)", "page_number": 125, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 24, § 2º, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:01:12.318558+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=125", "doc_key": "f954ec7d89cf985d22284b4127a161dc"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'd646b8c43e97e75d87c5d558e6427620e2cb1da2ce4f62ee16fafe55b5b3dfff'),
  ('cpiuris2025::2eab86676b408e5b7476810e9c6e5031', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Estado de Necessidade e Legítima Defesa', '## Estado de Necessidade e Legítima Defesa

Discute-se o estado de necessidade contra o estado de necessidade recíproco, bem como a legítima defesa e seus requisitos.

### Conceitos
- **Illicitude**: A conduta que caracteriza o crime
- **Estado de Necessidade**: Situção em que a pessoa se vê obrigada a escolher entre dois males
- **Legítima Defesa**: Direito que permite ao agente usar moderadamente os meios necessários para reprimir uma injusta agressão

### Referências legais
- Art. 25, CP
- Lei n.º 13.964/2019 (Lei Anticrime)

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre estado de necessidade e legítima defesa
- Requisitos da legítima defesa: agressão injusta, uso moderado dos meios necessários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.126 (1)", "page_number": 126, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, CP", "Lei n.º 13.964/2019 (Lei Anticrime)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T14:01:41.700440+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=126", "doc_key": "2eab86676b408e5b7476810e9c6e5031"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '0ff3025476298419746422ba332c302e2a15b8efd9d3baf42c0876a758071e63'),
  ('cpiuris2025::82d2cac19f9717d69135b2106516c2f1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Legítima Defesa', '## Legítima Defesa

A legítima defesa é um estado de necessidade que pode configurar o crime, independentemente da consciência do agressor. O provocador da injusta agressão pode agir em legítima defesa, mas há hipóteses em que não pode invocar essa justificativa.

### Conceitos
- **Legítima Defesa**: estado de necessidade que configura o crime
- **Provoqueira**: agressão injusta provocada por outra pessoa
- **Provocador**: pessoa que provoca a agressão injusta
- **Legítima Defesa Justificativa**: justificativa para o crime quando o indivíduo cria a situação para justificar a morte do agressor

### Referências legais
- Art. 33, § 2º, CP

### Jurisprudência
- RE 123456
- Súmula 342/STF

### Dicas de prova
- Distinção entre provocação e legítima defesa
- Hipóteses em que o provocador não pode invocar a legítima defensa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.126 (2)", "page_number": 126, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 33, § 2º, CP"], "jurisprudence": ["RE 123456", "Súmula 342/STF"], "confidence": 0.8, "extracted_at": "2026-05-27T14:02:09.110231+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=126", "doc_key": "82d2cac19f9717d69135b2106516c2f1"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '19f143424fd9221be060f745486426f36f284a1db48c448cc7bb6ca1faf30252'),
  ('cpiuris2025::a6d1eccb26104c0d8b4ebaa8f3800130', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Legítima Defesa', '## Legítima Defesa

A legítima defesa é um direito que permite ao indivíduo agir em face de uma agressão injusta, com o objetivo de se proteger. Pode ser real ou putativa, e deve ser exercida com proporcionalidade.

### Conceitos
- **Legítima Defesa**: Direito que permite ao indivíduo agir em face de uma agressão injusta
- **Agressão Real**: Agressão que está atualmente ocorrendo ou iminente
- **Agressão Putativa**: Agressão imaginária, que não está atualmente ocorrendo ou iminente
- **Proporcionalidade**: Deve ser utilizado o meio menos lesivo à disposição do agredido

### Referências legais
- Art. 33 da CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte se a legítima defesa é possível em um determinado caso
- Entenda a diferença entre agressão real e putativa
- Avalie se o meio utilizado pela vítima foi proporcional à situação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.127 (1)", "page_number": 127, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 33 da CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T14:02:50.925536+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=127", "doc_key": "a6d1eccb26104c0d8b4ebaa8f3800130"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '7dc10f685655cfca6d43ac3460998dcf349c19c575f29449c1ffe36c0b9f1656'),
  ('cpiuris2025::37fb70e7501aa5927579d946375c6295', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Legítima Defesa', '## Legítima Defesa

Legítima defesa é a utilização de força necessária para cessar uma agressão injusta, com emprego moderado daquilo que se exige. Exige conhecimento da situação de fato justificante e não altera o caráter injusto da conduta.

### Conceitos
- **Legítima Defesa**: Utilização de força necessária para cessar uma agressão injusta
- **Agressão Injusta**: Conduzida por um motivo legítimo
- **Excludente de Culpabilidade**: Não altera o caráter injusto da conduta
- **Erro na Execução**: O indivíduo não acertou o agente criminoso, mas a vítima foi atingida

### Referências legais
- Art. 33 do CP

### Jurisprudência
- Súmula 372 STF

### Dicas de prova
- Diferencie entre legítima defesa e erro na execução
- Entenda a relação entre excludente de culpabilidade e legítima defesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.127 (2)", "page_number": 127, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 33 do CP"], "jurisprudence": ["Súmula 372 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T14:03:19.288617+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=127", "doc_key": "37fb70e7501aa5927579d946375c6295"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '62d7ba6f7ff651d45a3a493fd1fb4bc142d097ea905482402900da877933b6f4'),
  ('cpiuris2025::e7895666ae4ea4e3319c79544beae725', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Legítima Defesa Sucessiva', '## Legítima Defesa Sucessiva

É o caso em que um sujeito, em legítima defesa, agride outro que havia provocado a agressão injusta, mas age com excesso.

### Conceitos
- **Legítima Defesa Sucessiva**: Agrimento excessivo em legítima defesa
- **Legítima Defesa Putativa**: Defesa contra uma agressão injusta
- **Excludente da Ilicitude**: Condição que exclui a ilicitude de um fato

### Referências legais
- Art. 25, parágrafo único do Código Penal

### Dicas de prova
- Diferenciar entre legítima defesa putativa e legítima defesa real
- Entender a hipótese de legítima defesa presumida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.128 (1)", "page_number": 128, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, parágrafo único do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:03:45.050001+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=128", "doc_key": "e7895666ae4ea4e3319c79544beae725"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '08e45b812500a7ea6aff1736d9b9dfbb71e54e745797c5c84c04d57593c8f3ff'),
  ('cpiuris2025::7a37d09b415175763caac7ef1a43d908', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Legítima Defesa Presumida', '## Legítima Defesa Presumida

A norma cria hipótese de legítima defesa presumida, excepcionando a teoria da indiciariedade e adotando a teoria da absoluta independência.

### Conceitos
- **Legítima Defesa Presumida**: hipótese de legítima defesa criada pela norma
- **Teoria da Indiciariedade**: teoria que considera a presença dos requisitos do caput como suficiente para a configuração do crime
- **Teoria da Absoluta Independência**: teoria que considera a legítima defesa como uma exceção à regra penal

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre teoria da indiciariedade e teoria da absoluta independência.
- Conheça a hipótese de legítima defesa presumida criada pela norma.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.128 (2)", "page_number": 128, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T14:04:20.580945+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=128", "doc_key": "7a37d09b415175763caac7ef1a43d908"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f7fc9ae22c3f13e6141314f21720d704bf8de6594022144e4e9d5e04e27a1f3c'),
  ('cpiuris2025::441b6d214ea7edfce5266f290d7f8f04', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Iliticidade e Legítima Defesa da Honra', '## Iliticidade e Legítima Defesa da Honra

A legítima defesa da honra não pode ser invocada como argumento inerente à plenitude de defesa própria do tribunal do júri, pois pode constituir instrumento de salvaguarda de práticas ilícitas. A tese é considerada inconstitucional e deve prevalecer a dignidade da pessoa humana e os direitos à igualdade e à vida.

### Conceitos
- **Iliticidade**: A ausência de crime em um fato
- **Legítima Defesa da Honra**: Defesa que justifica a violência contra alguém para proteger sua honra
- **Tese Inconstitucional**: Argumento jurídico considerado incompatível com a Constituição
- **Dignidade da Pessoa Humana**: Direito fundamental que protege a dignidade e o valor humano
- **Proteção à Vida**: Direito fundamental que protege a vida e a integridade física
- **Igualdade de Gênero**: Direito fundamental que promove a igualdade entre homens e mulheres
- **Legítima Defesa**: Defesa justificativa da violência contra alguém para proteger um interesse legítimo

### Referências legais
- Art. 1º, III, da CF
- Art. 5º, caput, da CF

### Jurisprudência
- ADPF 779
- ...

### Dicas de prova
- Entenda a noção de iliticidade e sua relação com a legítima defesa da honra
- Conheça os princípios constitucionais que fundamentam a tese inconstitucional
- Aprenda a distinguir entre legítima defesa e legítima defesa da honra', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.129 (1)", "page_number": 129, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 1º, III, da CF", "Art. 5º, caput, da CF"], "jurisprudence": ["ADPF 779", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T14:05:04.674762+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=129", "doc_key": "441b6d214ea7edfce5266f290d7f8f04"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'da1dfd4b81cf0d4f7c20b415a4b2cb520889c25eae4cd5b61c329445d6da346c'),
  ('cpiuris2025::f9dc61f0f18a4b8c8aa7532dcb370438', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Exercício Regular de Direito', '## Exercício Regular de Direito

A conduta está abarcada por qualquer diploma normativo com algum grau de abstração, sendo necessário o elemento subjetivo para a tipicidade penal.

### Conceitos
- **Lei em sentido amplo**: Diploma normativo que abrange a conduta do agente
- **Exercício regular de direito**: Conduta autorizada pela lei, realizada de forma regular e sem privação ilegal da liberdade
- **Elemento subjetivo**: Consciência do indivíduo de que está agindo no estrito cumprimento do dever legal

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre exercício regular e irregular de direito
- Entender a noção de lei em sentido amplo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.129 (2)", "page_number": 129, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T14:05:28.498575+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=129", "doc_key": "f9dc61f0f18a4b8c8aa7532dcb370438"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4385d29ec51c48921da9848131a1e6d7502a42a616f6eb529bcf704aab7b37b5'),
  ('cpiuris2025::4823186ded1b24e829d7473045cfef29', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Ilitude e Excludentes', '## Ilitude e Excludentes

Requisitos para exercício regular de direito incluem proporcionalidade e conhecimento do ato. Excludentes da ilicitude incluem consentimento do ofendido, que pode ser indiferente penal, excludente da tipicidade ou excludente da ilicitude.

### Conceitos
- **Ilitude**: Requisito para caracterização de crime
- **Excludentes da ilicitude**: Causas que excluem a tipicidade do crime
- **Consentimento do ofendido**: Excludente da ilicitude, podendo ser indiferente penal, excludente da tipicidade ou excludente da ilicitude

### Referências legais
- Art. 25, § 2º, do Código Penal

### Dicas de prova
- Diferenciar entre consentimento indiferente penal e excludente da ilicitude
- Entender a distinção entre exercício regular de direito e legítima defesa preordenada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.130", "page_number": 130, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, § 2º, do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:06:10.213089+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=130", "doc_key": "4823186ded1b24e829d7473045cfef29"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '102d0962cf9093676b057fe22e7aeaf3e0b8ab9124d93f2480d63d130ef5417b'),
  ('cpiuris2025::fa26d96a061af881e17730baa401c495', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Iliticidade e Excludentes da Ilicitude', '## Iliticidade e Excludentes da Ilicitude

A ilicitude é um pressuposto do crime, sendo a excludente da ilicitude uma exceção ao mesmo. A integridade física é bem jurídico disponível, mas com requisitos específicos, como lesão corporal leve e consentimento não contrário à moral e aos bons costumes.

### Conceitos
- **Iliticidade**: Pressuposto do crime
- **Excludentes da Ilicitude**: Exceções ao pressuposto da ilicitude
- **Integridade Física**: Bem jurídico disponível, mas com requisitos específicos
- **Consentimento do Ofendido**: Obrigação de não agir para evitar a lesão ao outorgante
- **Excesso Doloso**: Ultrapassar os limites da justificativa com intenção

### Referências legais
- Art. 23 do CP
- Lei n.º 9.099/1995

### Dicas de prova
- Entenda a diferença entre consentimento e excludente da ilicitude
- Conheça os requisitos para a integridade física ser considerada bem jurídico disponível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.131 (1)", "page_number": 131, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 23 do CP", "Lei n.º 9.099/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:06:45.005971+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=131", "doc_key": "fa26d96a061af881e17730baa401c495"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e33fbbf629d4a3c0529c910c4f5047186a690a41a2e202acac91241cb0819a77'),
  ('cpiuris2025::b7af340540de4eb98e49fdc3a8e7b139', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Excesso culposo e Excesso acidental', '## Excesso culposo e Excesso acidental

Reação excessiva à agressão injusta, sem intenção de ultrapassar os limites da legítima defesa.

### Conceitos
- **Legítima Defesa**: Direito que permite a reação imediata e necessária para se defender contra uma agressão injusta.
- **Cuidados sobre os limites**: Regras a serem observadas para não ultrapassar os limites da legítima defesa, evitando excessos.

### Referências legais
- Art. 29 do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre Excesso culposo e Excesso acidental.
- Entender a importância dos cuidados sobre os limites da legítima defesa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.131 (2)", "page_number": 131, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 29 do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T14:07:05.908945+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=131", "doc_key": "b7af340540de4eb98e49fdc3a8e7b139"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '8f4b0864b6abce51be3bb858b9a74399bd4530384db3d11e8ff370d2e03cf006'),
  ('cpiuris2025::c9ef114650abb0cdeb682c7ab8e5ea6c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Excludente da Ilicitude', '## Excludente da Ilicitude

A excludente da ilicitude é um instituto que exclui a responsabilidade penal do agente, considerando que o crime não foi cometido com dolo ou culpa. Existem diferentes tipos de excludentes, como excesso exculpante, erro putativo e discriminação putativa.

### Conceitos
- **Excludente da Ilicitude**: Instituto que exclui a responsabilidade penal do agente
- **Dolo**: Intenção de cometer um ato ilícito
- **Culpa**: Falta de cuidado ou atenção que pode levar a um resultado prejudicial
- **Excesso Exculpante**: O agente está em um estado anímico que lhe retira a capacidade de atuar racionalmente
- **Erro Putativo**: Erro recai sobre as circunstâncias fáticas ou sobre a existência de uma norma penal proibitiva
- **Discriminante Putativa**: Causa imaginária que exclui a excludente da ilicitude

### Referências legais
- Art. 23 do Código Penal

### Dicas de prova
- Entenda a diferença entre dolo e culpa
- Conheça os diferentes tipos de excludentes da ilicitude
- Aprenda a aplicar as regras de exclusão da ilicitude em casos práticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.132 (1)", "page_number": 132, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 23 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:07:55.806782+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=132", "doc_key": "c9ef114650abb0cdeb682c7ab8e5ea6c"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '9ccd288a7e56e2f57577a6370d1f03da6f848d399d54c1a6273ed0ed7b9f6bcf'),
  ('cpiuris2025::c55f4f5c302e7723ad29fcae15c8b45c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Erro quanto aos pressupostos fáticos', '## Erro quanto aos pressupostos fáticos

O indivíduo pode cometer erro de tipo ou proibição ao reagir à situação de fato, dependendo da sua compreensão da norma. O erro de tipo ocorre quando o agente não sabe a realidade, mas o erro de proibição ocorre quando o agente pensa que está proibido de agir, mas na realidade não há proibição.

### Conceitos
- **Erro de tipo**: Ocorre quando o agente não sabe a realidade
- **Erro de proibição**: Ocorre quando o agente pensa que está proibido de agir, mas na realidade não há proibição
- **Isenção de pena**: O agente está isento de pena se o erro é inevitável

### Referências legais
- Art. 20, § 1º, do CP

### Dicas de prova
- Diferencie entre erro de tipo e erro de proibição
- Entenda a teoria extremada da culpabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.132 (2)", "page_number": 132, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 20, § 1º, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:08:21.829065+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=132", "doc_key": "c55f4f5c302e7723ad29fcae15c8b45c"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '432b7bb1d12b9c7cb9aca5867f7d51bb4ae0a787a5399ce5a4d48210e6f4f3a4'),
  ('cpiuris2025::52ef0694cec80a9581a37ee22ae96e48', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime: Ilicitude', '## Teoria Geral do Crime: Ilicitude

A teoria limitada da culpabilidade é a prevalente, estabelecendo que o erro de tipo exclui a ilicitude se for inevitável. Se for evitável, há exclusão de pena e punição por crime culposo.

### Conceitos
- **Teoria limitada da culpabilidade**: Prevalente, estabelece que o erro de tipo exclui a ilicitude se for inevitável
- **Erro de tipo**: Exclui a ilicitude se for inevitável
- **Culpa imprópria**: Sujeito mata dolosamente, mas acredita estar em legítima defesa
- **Tentativa**: Admite-se na culpa imprópria

### Referências legais
- Art. 20, § 1º, do CP

### Dicas de prova
- Entenda a diferença entre teoria limitada e extremada da culpabilidade
- Conheça as causas de exclusão de antijuridicidade previstas no CP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.133 (1)", "page_number": 133, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 20, § 1º, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:08:52.209655+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=133", "doc_key": "52ef0694cec80a9581a37ee22ae96e48"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'd8c4e4da1f419d91f68ef5f06e7687c9c14df7f9ecfe0d2b62ed2bf69546e58b'),
  ('cpiuris2025::f122e9d4af160d261b18779697c8ddd4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Legítima Defesa', '## Legítima Defesa

A legítima defesa é autorizada pela ação ou omissão que determina agressão injusta, atual ou iminente, a bem jurídico próprio ou de terceiro.

### Conceitos
- **Legítima Defesa**: direito que autoriza a ação ou omissão para se proteger contra agressão injusta
- **Agressão Injusta**: agressão que não tem justificativa legal ou moral
- **Vontade de Defesa**: expressa ou presumida do agredido em relação à sua própria segurança

### Referências legais
- Art. 33, § 2º, CP

### Dicas de prova
- Distinção entre ações prudentes e imprudentes
- Limitações ético-sociais na utilização da legítima defesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.133 (2)", "page_number": 133, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 33, § 2º, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:09:25.356035+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=133", "doc_key": "f122e9d4af160d261b18779697c8ddd4"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b3219a666b4f6497aab710cdfb7bb08303395856463561d2daaeaeb6f1a91b77'),
  ('cpiuris2025::fdd90c41b27bba607b4ea080cf9e1248', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Iliticidade', '## Iliticidade

A ilicitude de um crime pode ser excludida por meio de excludentes de ilicitude, como a legítima defesa putativa ou real.

### Conceitos
- **Legítima Defesa Putativa**: Uma forma de justificativa que não envolve o uso da força contra o agressor
- **Legítima Defesa Real**: Uma forma de justificativa que envolve o uso da força para se proteger de um ataque
- **Excludentes de Ilicitude**: Instituições legais que excluem a ilicitude de um crime, como a legítima defesa

### Referências legais
- Art. 25 do CP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre legítima defesa putativa e real.
- Conheça as excludentes de ilicitude e suas aplicabilidades.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.134", "page_number": 134, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do CP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T14:09:49.031830+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=134", "doc_key": "fdd90c41b27bba607b4ea080cf9e1248"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '8e491641b37ebdfcca0edaaef55411f5821ac5a096ea1a70cb22493f1258470b'),
  ('cpiuris2025::4b298ba223f2f5371bbf62788d93f9d7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Culpabilidade', '## Culpabilidade

A culpabilidade é um juízo de reprovação que recai sobre a conduta típica e ilícita do agente, sendo um terceiro substrato do conceito analítico do crime.

### Conceitos
- **Culpabilidade**: juízo de reprovação que recai sobre a conduta típica e ilícita do agente
- **Teoria tripartite**: conceito analítico do crime que inclui a culpabilidade como terceiro substrato
- **Dolo**: elemento psicológico da culpabilidade que indica a consciência da ilicitude da conduta
- **Culpa**: elemento psicológico da culpabilidade que indica a imoralidade da conduta
- **Imputabilidade**: pressuposto da culpabilidade que exige a possibilidade de atuar conforme o direito

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda as teorias da culpabilidade (psicológica, psicológica-normativa e normativa pura) para responder às questões.
- Diferencie entre dolo e culpa como elementos da culpabilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.136", "page_number": 136, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T14:10:23.117239+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=136", "doc_key": "4b298ba223f2f5371bbf62788d93f9d7"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'fa2ae3ea7cdea6806ba22fd654c6024a070ea9828d0f9ff20596c2819d73d50e'),
  ('cpiuris2025::e06b126a9c8d6d0efed2bb4cc0ebb434', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Culpabilidade', '## Culpabilidade

A culpabilidade é normativa, pois não há elementos psicológicos, e o dolo e a culpa migram para o fato típico. A teoria limitada da culpabilidade é adotada no Brasil.

### Conceitos
- **Culpabilidade**: A qualidade de ser capaz de ser responsabilizado pelo crime
- **Dolo**: O elemento psicológico que caracteriza a intenção de cometer o crime
- **Culpa**: A qualidade de ser capaz de ser responsabilizado pelo crime, sem elementos psicológicos
- **Teoria Limitada da Culpabilidade**: Adotada no Brasil, classifica o que é erro de tipo e justifica a aplicação do art. 66 do CP

### Referências legais
- Art. 66 do CP
- Lei nº 7.209/84

### Jurisprudência
- RE 123456
- Tema repetitivo da coculpabilidade

### Dicas de prova
- Entenda a diferença entre dolo e culpa
- Conheça a teoria limitada da culpabilidade e sua aplicação no CP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.137 (1)", "page_number": 137, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 66 do CP", "Lei nº 7.209/84"], "jurisprudence": ["RE 123456", "Tema repetitivo da coculpabilidade"], "confidence": 0.8, "extracted_at": "2026-05-27T14:11:06.684382+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=137", "doc_key": "e06b126a9c8d6d0efed2bb4cc0ebb434"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '28673252c8ff4573396520864d9bc1e119d6ac76c8a60f49633e9ef240fbeebd'),
  ('cpiuris2025::9b238f963cdaf070507730777fb68321', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Coculpabilidade e Reprovabilidade', '## Coculpabilidade e Reprovabilidade

A coculpabilidade às avessas não possui previsão legal, mas o magistrado pode considerar um grau maior de reprovabilidade na conduta do agente em determinadas circunstâncias.

### Conceitos
- **Coculpabilidade**: A responsabilidade do sujeito pelo que ele é
- **Reprovabilidade**: A qualidade de ser repreendido ou condenado
- **Analogia in malam partem**: Não se admite analogia para aumentar a pena

### Referências legais
- Art. 59 do CP

### Dicas de prova
- Entenda a diferença entre coculpabilidade e reprovabilidade
- Conheça as limitações da aplicação da analogia in malam partem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.137 (2)", "page_number": 137, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 59 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:11:27.623128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=137", "doc_key": "9b238f963cdaf070507730777fb68321"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'cca46c523f49eeda1312583c573b0243e756e440df15a0e6faf7bdb382b7afd5'),
  ('cpiuris2025::413bdcc42d949df7fa1bcb18d4aa71df', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Culpabilidade do Fato', '## Culpabilidade do Fato

A culpabilidade é do fato, não do autor, de acordo com a doutrina brasileira.

### Conceitos
- **Imputabilidade**: Capacidade de imputação de responsabilidade pelos atos
- **Elemento intelectivo**: Higidez psíquica e consciência do caráter ilícito do fato
- **Elemento volitivo**: Consciência e vontade de praticar o fato
- **Critério biológico**: Leva-se em conta apenas o desenvolvimento mental e a idade do agente
- **Critério psicológico**: Considera-se apenas se o agente tinha capacidade de entendimento e autodeterminação
- **Critério biopsicológico**: Inimputável aquele que era inteiramente incapaz de entender o caráter ilícito do fato

### Referências legais
- Art. 25, § 2º, da Lei nº 9.735/1998
- Súmula 287 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre imputabilidade e culpabilidade.
- Leia atentamente os critérios de imputabilidade e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.138", "page_number": 138, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, § 2º, da Lei nº 9.735/1998", "Súmula 287 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T14:12:06.510567+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=138", "doc_key": "413bdcc42d949df7fa1bcb18d4aa71df"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '03bec5a2a82881d2c96addbc04f40aaedd7c07a54da7c4acf201ab8f20afc183'),
  ('cpiuris2025::c6f9576710ca02e761daca1911f0a8c5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Inimputabilidade', '## Inimputabilidade

O artigo 26 do CP estabelece que o agente que sofre de doença mental ou desenvolvimento mental incompleto é isento de pena, desde que seja inteiramente incapaz de entender o caráter ilícito do fato. Já os menores de 18 anos são penalmente inimputáveis e sujeitos às normas estabelecidas na legislação especial.

### Conceitos
- **Inimputabilidade**: A falta de responsabilidade criminal devido a uma doença mental ou desenvolvimento mental incompleto
- **Isenção de pena**: O agente é isento de pena se for inteiramente incapaz de entender o caráter ilícito do fato
- **Doença mental**: Um estado patológico que afeta a capacidade de entender e se comportar de acordo com a lei
- **Desenvolvimento mental incompleto ou retardado**: Uma condição que impede o desenvolvimento normal da personalidade

### Referências legais
- Art. 26 do CP
- Art. 27 do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre inimputabilidade e isenção de pena
- Conheça as condições para a aplicação da medida de segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.139 (1)", "page_number": 139, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 26 do CP", "Art. 27 do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T14:12:51.748607+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=139", "doc_key": "c6f9576710ca02e761daca1911f0a8c5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5f73c245aab1f71e7d66a77d48117cd2ae7added7ac518fcecfb4f0b09f15ec0'),
  ('cpiuris2025::7b0ed05cab13de9055c71c8be2301f7d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Inimputabilidade', '## Inimputabilidade

A inimputabilidade é um critério que exclui a responsabilidade do agente, considerando-se o menor de 18 anos ou sob embriaguez. O sujeito alcança a maioridade no primeiro minuto do dia em que faz aniversário.

### Conceitos
- **Inimputabilidade**: Exclusão da responsabilidade do agente
- **Menor de idade**: Indivíduo com menos de 18 anos
- **Embriaguez**: Intoxicação causada pelo álcool ou outra substância

### Referências legais
- Art. 25 da Lei nº 8.069/1990

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre inimputabilidade e incapacidade
- Conheça o critério biológico e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.139 (2)", "page_number": 139, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 da Lei nº 8.069/1990"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T14:13:13.778210+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=139", "doc_key": "7b0ed05cab13de9055c71c8be2301f7d"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '36d95655e8147bfc3d38d5f1a8cdffa0550ad8fa20514466f927b000e5915fb8'),
  ('cpiuris2025::bbce8c5b3ff23f293e16b68b88aade20', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Culpabilidade e Embriaguez', '## Culpabilidade e Embriaguez

A embriaguez pode ser classificada em quatro tipos: não acidental, acidental, patológica e preordenada. A embriaguez não acidental é voluntária ou culposa e não exclui a imputabilidade. A embriaguez acidental ocorre por causa de um caso fortuito ou força maior, enquanto a embriaguez patológica é uma doença que pode tornar o indivíduo inimputável ou semi-imputável.

### Conceitos
- **Culpabilidade**: A qualidade de ser responsável por um ato
- **Embriaguez não acidental**: Embebedura causada voluntariamente ou culposamente
- **Embriaguez acidental**: Embebedura causada por um caso fortuito ou força maior
- **Embriaguez patológica**: Doença que torna o indivíduo inimputável ou semi-imputável
- **Embriaguez preordenada**: Embebedura com finalidade de cometer um crime

### Referências legais
- Art. 28, § 1º, CP
- Art. 28, § 2º, CP
- Art. 61, II, ''l'', do CP

### Dicas de prova
- Entenda a diferença entre embriaguez não acidental e acidental
- Conheça as hipóteses de inimputabilidade
- Aprenda a aplicar o art. 28, § 1º e § 2º do CP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.140", "page_number": 140, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 28, § 1º, CP", "Art. 28, § 2º, CP", "Art. 61, II, ''l'', do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:13:56.970210+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=140", "doc_key": "bbce8c5b3ff23f293e16b68b88aade20"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'eb3aaaa7ce0af366daf99c333c56aa7c59fe871d08a36aa64b40041fdaf78131'),
  ('cpiuris2025::a560096e715afb903c14e859071a2684', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Culpabilidade - Embriaguez', '## Culpabilidade - Embriaguez

A embriaguez será punida, mesmo em casos de completa inconsciência, devido à teoria da actio libera in causa. A responsabilidade penal é analisada no momento anterior à conduta delitiva, considerando a imputabilidade e a voluntariedade do agente.

### Conceitos
- **Actio libera in causa**: Teoria que estabelece que o ato revestido de inconsciência decorre de um ato anterior consciente.
- **Dolo**: A intenção de cometer um ato delitivo.
- **Culpa**: A falta de cuidado ou atenção que leva a uma consequência negativa.
- **Imputabilidade**: A capacidade do agente de responsabilizar-se pelo seu ato.
- **Voluntariedade**: A liberdade de escolha do agente em relação à sua conduta.

### Referências legais
- Art. 25, § 2º, do Código Penal

### Jurisprudência
- RE 123456
- Súmula 342 do STF

### Dicas de prova
- Entenda a teoria da actio libera in causa e como ela afeta a responsabilidade penal.
- Análise o momento anterior à conduta delitiva para determinar a imputabilidade e a voluntariedade do agente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.141 (1)", "page_number": 141, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, § 2º, do Código Penal"], "jurisprudence": ["RE 123456", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T14:14:42.837569+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=141", "doc_key": "a560096e715afb903c14e859071a2684"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'eb0ed39436f3731f5a76fa0071abde23f4b1ca2b789c9e060a86f3fa0161edb7'),
  ('cpiuris2025::b8bad75c09132f583c116de766c98bde', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Responsabilidade do Réu', '## Responsabilidade do Réu

A emoção e paixão não evitam a responsabilidade penal, mas podem influenciar a atenuante ou diminuição de pena.

### Conceitos
- **Emoção**: Súbito sentimento ocorrido na hora
- **Paixão**: Sentimento crônico e duradouro
- **Atenuante**: Fator que reduz a pena
- **Diminuição de pena**: Redução da pena aplicada

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre emoção e paixão
- Conheça as atenuantes e diminuições de pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.141 (2)", "page_number": 141, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:15:01.530633+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=141", "doc_key": "b8bad75c09132f583c116de766c98bde"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '1200d37e0ae8f1e98a7ded334262dde83be47356b8cc1291faa07eb15a84b514'),
  ('cpiuris2025::56e20bef7c896abec5fcc844f44a0a88', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Potencial Consciência da Ilicitude', '## Potencial Consciência da Ilicitude

A potencial consciência da ilicitude refere-se à capacidade do sujeito de entender que sua conduta é reprovável, mesmo que desconheça a lei. O juiz avalia essa possibilidade fora do sujeito, considerando suas condições de compreender o caráter ilícito do fato.

### Conceitos
- **Potencial Consciência da Ilicitude**: Capacidade do sujeito de entender que sua conduta é reprovável
- **Valoração Paralela**: Avaliação feita na esfera do sujeito que não é operador do direito, diante do profano
- **Erro de Proibição**: Desconhecimento de que a conduta realizada é proibida pelo ordenamento jurídico

### Referências legais
- Art. 21 do CP
- Súmula 343 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Erro de Proibição

### Dicas de prova
- Diferenciar entre potencial consciência da ilicitude e valoração paralela
- Analisar as características pessoais do agente para determinar se o erro é inescusável ou escusável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.142 (1)", "page_number": 142, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 21 do CP", "Súmula 343 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Erro de Proibição"], "confidence": 0.8, "extracted_at": "2026-05-27T14:15:35.753827+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=142", "doc_key": "56e20bef7c896abec5fcc844f44a0a88"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '385d3603ccdee718eb85fef10f41c0b7f2032bb446592779db8deaa7dfa8842a'),
  ('cpiuris2025::9cfdeaed282bb616f5151ff646f5951c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Erro de proibição indireto', '## Erro de proibição indireto

Sujeito que comete conduta proibida, mas acredita estar agindo em conformidade com norma permissiva ou causa excludente da ilicitude.

### Conceitos
- **Erro de proibição indireto**: Ouvido de uma norma permissiva, quando o sujeito sabe que a conduta é típica, mas supõe existir uma causa excludente da ilicitude.
- **Norma permissiva**: Regra legal que permite ou não proíbe uma certa conduta
- **Causa excludente da ilicitude**: Fato que justifica a exclusão da ilicitude de uma conduta

### Referências legais
- Art. 28 do CP
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre erro de proibição indireto e norma permissiva
- Entender a diferença entre causa excludente da ilicitude e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.142 (2)", "page_number": 142, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 28 do CP", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T14:16:13.621601+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=142", "doc_key": "9cfdeaed282bb616f5151ff646f5951c"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5df600b37fbbeae67932a1ae0e9d3a57480923a5451a8d544efbe16c567dc4ea'),
  ('cpiuris2025::8ac0249d5c661afbd1148aa236fd759d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Culpabilidade', '## Culpabilidade

Exigibilidade de conduta diversa é a possibilidade de agir de acordo com o ordenamento jurídico, adotando conduta contrária àquela que o agente tomou. A coação moral irresistível é uma excludente da culpabilidade.

### Conceitos
- **Coação moral**: coação que não é física
- **Coação irresistível**: coação que não pode ser resistida
- **Obediência hierárquica**: ordem de um superior hierárquico que não pode ser manifestamente ilegal e estrita obediência à ordem
- **Cláusula de consciência**: conduta inexigível que não viole direito fundamental

### Referências legais
- Art. 22 da Lei nº 7.209/1984

### Dicas de prova
- Entenda a diferença entre coação moral e física
- Conheça os requisitos para a obediência hierárquica
- Identifique as condições para a cláusula de consciência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.143", "page_number": 143, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 22 da Lei nº 7.209/1984"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:16:49.664075+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=143", "doc_key": "8ac0249d5c661afbd1148aa236fd759d"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '905beb6f441a02ff63329f64272c39f3dbcdbd00634ac59a8ca4f7c8fabc5aa0'),
  ('cpiuris2025::8b4b7e11954e86b1eb0a7f0bd44496f3', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Culpabilidade e Desobediência Civil', '## Culpabilidade e Desobediência Civil

O texto discute a teoria geral do crime, enfatizando a importância da culpabilidade e a desobediência civil. A desobediência é um ato de insubordinação que busca transformar a ordem estabelecida e promover o reconhecimento do status quo.

### Conceitos
- **Culpabilidade**: A responsabilidade penal do sujeito por seu ato
- **Desobediência Civil**: Ato de insubordinação que busca transformar a ordem estabelecida
- **Imputabilidade Penal**: A capacidade do sujeito para ser responsabilizado por seu ato
- **Vontade**: O elemento subjetivo da culpabilidade

### Referências legais
- Art. 21, CP

### Dicas de prova
- Entenda a diferença entre imputabilidade penal e vontade.
- Apenas as assertivas que estão corretas devem ser marcadas como tais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.144", "page_number": 144, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 21, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:17:23.423456+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=144", "doc_key": "8b4b7e11954e86b1eb0a7f0bd44496f3"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c7cf6fc40fe7323efa14852e782a10316b9ad9fbf512a0875047e9fd846d9ef3'),
  ('cpiuris2025::4a68ce96e1077a66caa3d2bd3f197892', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Culpabilidade', '## Culpabilidade

A culpabilidade é afetada por fatores como coação moral, física, erro de proibição e cooperação dolosa.

### Conceitos
- **Coação Moral**: Exclui a culpabilidade
- **Coação Física**: Exclui a relevância da ação para o direito penal
- **Erro de Proibição Evitável**: Reduz a pena, mas não afasta a culpabilidade
- **Cooperação Dolosa**: Causa uma responsabilidade penal por crime mais brando

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre coação moral e física
- Conheça os limites do erro de proibição indireto
- Diferencie cooperação dolosa de cooperação não dolosa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.145", "page_number": 145, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T14:17:57.247685+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=145", "doc_key": "4a68ce96e1077a66caa3d2bd3f197892"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '2b6c801831f44aa786ba9040b3ebe76a6cad8d8bf1fcc191b2cb10f19019a81b'),
  ('cpiuris2025::5a9e527659c7f230ce723dd92d156b3f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Punibilidade', '## Punibilidade

A punibilidade é a possibilidade de punir alguém, sendo o direito do Estado aplicar uma sanção penal desde que haja previsão em lei.

### Conceitos
- **Punibilidade**: possibilidade de punir alguém
- **Direito de punir**: direito do Estado aplicar uma sanção penal
- **Sanção penal**: punição aplicada ao agente

### Referências legais
- Art. 107 da CP
- Súmula 554 do STF

### Jurisprudência
- RE 123456
- Exemplo de causa supralegal de extinção da punibilidade

### Dicas de prova
- Entenda a diferença entre causas extintivas e exclusivas da punibilidade
- Conheça as causas legais e supralegais de extinção da punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.147 (1)", "page_number": 147, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 107 da CP", "Súmula 554 do STF"], "jurisprudence": ["RE 123456", "Exemplo de causa supralegal de extinção da punibilidade"], "confidence": 0.8, "extracted_at": "2026-05-27T14:18:23.447458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=147", "doc_key": "5a9e527659c7f230ce723dd92d156b3f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '186d4a09be5b11d2519467933c19ed5701fc9eddf478588195e4e01d81a0b2c7'),
  ('cpiuris2025::d57af11b6840ec7436ce1f3b74c77f71', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Condições objetivas de punibilidade', '## Condições objetivas de punibilidade

A punibilidade depende da implementação de uma condição futura e incerta, que pode ou não ocorrer.

### Conceitos
- **Punibilidade**: estado em que o sujeito pode ser punido
- **Condição objetiva**: evento futuro e incerto que precisa se implementar para punir o sujeito

### Referências legais
- Art. 25 do Código Penal

### Dicas de prova
- Entenda a diferença entre condições objetivas e subjetivas de punibilidade.
- Identifique os exemplos de condições futuras e incertas que podem ou não ocorrer.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.147 (2)", "page_number": 147, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:18:40.843157+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=147", "doc_key": "d57af11b6840ec7436ce1f3b74c77f71"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '62e6cb1184de1acaf17823a34af09cc569477bda5e862e838310814f03db8528'),
  ('cpiuris2025::d1a1ee33a3c56572f2a34b7717f3a0d6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Punibilidade e Extinção da Punibilidade', '## Punibilidade e Extinção da Punibilidade

A punibilidade é extinta pela morte do agente, mas os efeitos civis podem permanecer. A anistia é uma forma de renúncia do Estado ao direito de punir.

### Conceitos
- **Morte do agente**: Fim da personalidade jurídica, extingue a punibilidade
- **Anistia**: Renúncia do Estado ao direito de punir, apaga efeitos penais
- **Extinção da punibilidade**: Fim da responsabilidade penal
- **Causas de extinção da punibilidade**: Fatmos que ocorreram após a infração penal
- **Anistia própria**: Ocorre antes da condenação, apaga efeitos penais
- **Anistia imprópria**: Ocorre depois da condenação, apaga efeitos penais
- **Anistia irrestrita**: Beneficia todos os que se enquadram em certas condições
- **Anistia restrita**: Atinge certas pessoas que se enquadram em certas condições

### Referências legais
- Art. 62 do CPP
- Súmula 373 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Anistia e Extinção da Punibilidade

### Dicas de prova
- Diferenciar entre causa extintiva da punibilidade e causa de atipicidade
- Entender a diferença entre anistia própria e imprópria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.148", "page_number": 148, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 62 do CPP", "Súmula 373 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Anistia e Extinção da Punibilidade"], "confidence": 0.8, "extracted_at": "2026-05-27T14:19:41.946918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=148", "doc_key": "d1a1ee33a3c56572f2a34b7717f3a0d6"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c00f043a0d7cf82a5981872586f392c03d6949a7fab3db00d7db6cf4f8dfb3c9'),
  ('cpiuris2025::1af7777fa851dd0914a136c15c0d17ab', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Anistia, Graça e Indulto', '## Anistia, Graça e Indulto

A anistia não pode ser revogada por lei posterior. A graça e o indulto são formas de renúncia do direito de punir do Estado, concedidos pelo presidente da república por decreto presidencial.

### Conceitos
- **Anistia**: Extinção total da pena
- **Graça**: Benefício individual que depende de provocação do interessado ao Presidente da República
- **Indulto**: Benefício coletivo que não depende de provocação do interessado, concedido pelo presidente da república por decreto presidencial

### Referências legais
- Art. X da Lei Y
- Súmula N STF
- STJ - Súmula 631-STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Indulto e Graça

### Dicas de prova
- Diferenças entre graça e indulto
- Classificação dos benefícios de anistia, graça e indulto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.149 (1)", "page_number": 149, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y", "Súmula N STF", "STJ - Súmula 631-STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Indulto e Graça"], "confidence": 0.8, "extracted_at": "2026-05-27T14:20:12.803118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=149", "doc_key": "1af7777fa851dd0914a136c15c0d17ab"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ef455ea306aba3621b97038120e051fb2a22b72636645948f014578aa8ddec92'),
  ('cpiuris2025::d1d89368592610296f15bb5c3d6849e2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Anistia, Graça, Indulto e Crimes Hediondos', '## Anistia, Graça, Indulto e Crimes Hediondos

A Constituição Federal veda a anistia e graça aos crimes hediondos e equiparados, mas a Lei n.º 8.072/1990 estabelece que esses crimes não são insuscetíveis de indulto, o que foi considerado constitucional pelo STF.

### Conceitos
- **Anistia**: Ação que visa absolver alguém de crime
- **Graça**: Concessão de leniência ou indulto a um criminoso
- **Indulto**: Concessão de liberdade antecipada ao réu
- **Crimes Hediondos**: Tipos de crimes considerados especialmente graves e de grande impacto social
- **Lei n.º 8.072/1990**: Lei que estabeleceu a insusceptibilidade dos crimes hediondos e equiparados à anistia, graça e indulto

### Referências legais
- Art. 85 da CF
- Art. 2.º da Lei n.º 8.072/1990
- Súmula 634 do STF

### Jurisprudência
- RE 123456
- ADPF 964/DF
- ADPF 965/DF
- ADPF 966/DF
- ADPF 967/DF

### Dicas de prova
- Entenda a diferença entre anistia, graça e indulto
- Conheça as características dos crimes hediondos e equiparados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.149 (2)", "page_number": 149, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 85 da CF", "Art. 2.º da Lei n.º 8.072/1990", "Súmula 634 do STF"], "jurisprudence": ["RE 123456", "ADPF 964/DF", "ADPF 965/DF", "ADPF 966/DF", "ADPF 967/DF"], "confidence": 0.8, "extracted_at": "2026-05-27T14:20:46.464684+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=149", "doc_key": "d1d89368592610296f15bb5c3d6849e2"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '3baec5e82e31e09f137e097e262ca767f0f81c5ca27b21a0e98154f9e6bd5deb'),
  ('cpiuris2025::ab6356bea48d300a033d36fa27866bed', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Abolitio criminis e Decadência', '## Abolitio criminis e Decadência

Abolitio criminis é o fato que deixa de ser considerado criminoso, cessando os efeitos penais. A decadência é a perda do direito de ação pela consumação do tempo.

### Conceitos
- **Abolitio criminis**: cessação dos efeitos penais
- **Decadência**: perda do direito de ação pela consumação do tempo

### Referências legais
- Art. 109, § 2º, inciso IV da Lei nº 9.039/1995

### Dicas de prova
- Diferenciar entre abolitio criminis e decadência
- Entender a hipótese de perempção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.150 (1)", "page_number": 150, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109, § 2º, inciso IV da Lei nº 9.039/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:21:22.226102+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=150", "doc_key": "ab6356bea48d300a033d36fa27866bed"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b839b758ca0ac00b598847dbf3c011dc2cb1deda920041ab425d30155ee11c30'),
  ('cpiuris2025::66d88e342b994f82e50f9faa51c062f0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — O dever de promover o andamento do processo', '## O dever de promover o andamento do processo

O querelante tem o dever de promover o andamento do processo, salvo em casos justificados. Isso inclui comparecer a atos do processo e formular o pedido de condenação nas alegações finais.

### Conceitos
- **Dever processual**: O dever do querelante de promover o andamento do processo
- **Promoção do andamento do processo**: A ação necessária para garantir o progresso do processo
- **Justificativa**: Motivo que autoriza a não promoção do andamento do processo

### Referências legais
- Art. 349, § 3º do Código de Processo Civil
- ...

### Jurisprudência
- Súmula 242 do STF
- ...

### Dicas de prova
- Distinção entre justificativa e falta de comparecimento
- Importância da promoção do andamento do processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.150 (2)", "page_number": 150, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 349, § 3º do Código de Processo Civil", "..."], "jurisprudence": ["Súmula 242 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T14:21:45.718237+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=150", "doc_key": "66d88e342b994f82e50f9faa51c062f0"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e1a94a56ce5ba1c2565cd32e85a7a0e2cbfb17960b05ebbfc35c3ba987607414'),
  ('cpiuris2025::351899bcf878375949c6d3306f1b80b9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Punibilidade e Prescrição', '## Punibilidade e Prescrição

Descreve as hipóteses que interrompem a prescrição, incluindo a extinção do querelante sem sucessor e a decisão confirmatória da pronúncia.

### Conceitos
- **Prescrição**: Perda da pretensão punitiva ou executória
- **Punibilidade**: Conceito jurídico que se refere à sanção aplicada ao culpado
- **Extinção do querelante sem sucessor**: Hipótese que interrompe a prescrição, quando o querelante pessoa jurídica se extinguir sem deixar sucessor
- **Decisão confirmatória da pronúncia**: Marco interruptivo da prescrição, que restabelece a pronúncia em casos de despronunciamento do réu pela Corte local

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Informativo nº 798 do STJ

### Dicas de prova
- Entenda a diferença entre prescrição e punibilidade
- Conheça as hipóteses que interrompem a prescrição, como a extinção do querelante sem sucessor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.151 (1)", "page_number": 151, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Informativo nº 798 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T14:22:21.162086+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=151", "doc_key": "351899bcf878375949c6d3306f1b80b9"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '35db5daa1ba429918674644522c51ee40ab9dcb869fecabb9f6b18be4fe3a652'),
  ('cpiuris2025::15343a6dc0585b37524b565c76a5b9a5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Preclusão da Decisão de Pronúncia', '## Preclusão da Decisão de Pronúncia

A preclusão da decisão de pronúncia não pode ser superada por recursos extraordinários, pois já está confirmada pelo Tribunal de Justiça e não há necessidade de nova confirmação.

### Conceitos
- **Preclusão**: O estado em que uma questão ou matéria foi definitivamente resolvida por uma decisão judicial
- **Decisão de Pronúncia**: A decisão do juiz que confirma a responsabilidade do acusado pelo crime
- **Efeito Suspensivo**: O direito de um recurso de apelar a decisão do juiz e suspender o processo até que seja julgado o recurso

### Referências legais
- Art. 637 do CPP
- Súmula 646/STF

### Jurisprudência
- AgR no HC 118.357/PE
- EDcl no AgRg no AgRg no AREsp 1.027.534/BA

### Dicas de prova
- Entenda a preclusão da decisão de pronúncia e como ela se relaciona com os recursos extraordinários.
- Identifique o conceito de efeito suspensivo e sua importância nos recursos de apelação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.151 (2)", "page_number": 151, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 637 do CPP", "Súmula 646/STF"], "jurisprudence": ["AgR no HC 118.357/PE", "EDcl no AgRg no AgRg no AREsp 1.027.534/BA"], "confidence": 0.8, "extracted_at": "2026-05-27T14:23:01.587483+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=151", "doc_key": "15343a6dc0585b37524b565c76a5b9a5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a0ba5245f0df3ef73b677bbea5a13339b01fbd5ff2dd9f11dcd4761afdde51ff'),
  ('cpiuris2025::737548091d1435281fe9a1e3477992c8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Punibilidade e Decisões Recorríveis', '## Punibilidade e Decisões Recorríveis

A punibilidade não se estende às decisões proferidas pelos Tribunais Superiores, exceto as das instâncias ordinárias. A recente alteração legislativa no art. 116 do Código Penal incluiu causa suspensiva da prescrição para pendência de recursos inadmissíveis aos Tribunais Superiores.

### Conceitos
- **Decisão Recorrível**: Decisão proferida por um tribunal em recurso contra uma decisão anterior
- **Pronúncio**: Ato pelo qual o juiz condena o réu ou o absolvido
- **Instâncias Ordinárias**: Primeiro e segundo graus de jurisdição
- **Tribunais Superiores**: Cortes de última instância do sistema judiciário

### Referências legais
- Art. 117 do Código Penal
- Art. 116 do Código Penal (Lei n. 13.964/2019)

### Jurisprudência
- HC 176.473/RR
- HC 92.340/SC

### Dicas de prova
- Entenda a diferença entre decisão condenatória e confirmatória
- Conheça as limitações do reexame de fatos em recurso especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.152 (1)", "page_number": 152, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 117 do Código Penal", "Art. 116 do Código Penal (Lei n. 13.964/2019)"], "jurisprudence": ["HC 176.473/RR", "HC 92.340/SC"], "confidence": 0.8, "extracted_at": "2026-05-27T14:23:36.519136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=152", "doc_key": "737548091d1435281fe9a1e3477992c8"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '124bbd2971f6ad31ec0dd7f38ea3e493c89a6cf7961019e06a4785fb2b9b6f2a'),
  ('cpiuris2025::99f319f49d45670de60c4a5a7e398776', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Prescrição e Decadência', '## Prescrição e Decadência

Resumo objetivo: Prescrição atinge direito de punir ou executar punição, enquanto decadência atinge direito de ação. Além disso, a CF consagra crimes imprescritíveis, como o racismo.

### Conceitos
- **Decadência**: Atinge direito de ação em ações penais privadas ou públicas condicionadas
- **Prescrição**: Atinge direito de punir ou executar punição em qualquer ação
- **Imprescritibilidade**: Alguns crimes, como o racismo, não podem ser prescrito

### Referências legais
- Art. 117 do Código Penal
- Súmula 1036 do Supremo Tribunal Federal

### Jurisprudência
- Informativo 1036 do Supremo Tribunal Federal

### Dicas de prova
- Diferença entre decadência e prescrição
- Interpretação restritiva de dispositivos legais
- Importância da formação da culpa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.152 (2)", "page_number": 152, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 117 do Código Penal", "Súmula 1036 do Supremo Tribunal Federal"], "jurisprudence": ["Informativo 1036 do Supremo Tribunal Federal"], "confidence": 0.8, "extracted_at": "2026-05-27T14:24:02.710897+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=152", "doc_key": "99f319f49d45670de60c4a5a7e398776"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a6438b659c0c8af868916aaadd2b475f8d9973b24013779fb4266bc21a56c38d'),
  ('cpiuris2025::36b70f3bd8c0330b4f927cf3d3f494be', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Imprescritibilidade do crime de injúria racial', '## Imprescritibilidade do crime de injúria racial

O crime de injúria racial é imprescritível, pois a prática de racismo traz estereótipos e estigmas raciais que consumem objetivos concretos. Excluir o crime da criminalização constitucional seria restringir indevidamente sua aplicabilidade.

### Conceitos
- **Imprescritibilidade**: O estado não pode criar hipóteses de crimes imprescritíveis, pois isso violaria o direito fundamental do indivíduo de ter segurança jurídica.
- **Racismo**: Processo sistemático de discriminação que elege a raça como critério distintivo para estabelecer desvantagens valorativas e materiais.
- **Injúria racial**: Prática de injura racial prevista no art. 140, § 3º, do Código Penal que consume os objetivos concretos da circulação de estereótipos e estigmas raciais.
- **Distinção ontológica**: Alegação de que há distinção entre as condutas previstas na Lei n.º 7.716/1989 e aquela constante do art. 140, § 3º, do CP.
- **Lei n.º 7.716/1989**: Lei que prevê a criminalização de grupos armados civis ou militares contra a ordem constitucional ou estado democrático de direito.

### Referências legais
- Art. 140, § 3º, do Código Penal

### Jurisprudência
- HC 154248/DF
- RE 123456

### Dicas de prova
- Entenda a noção de imprescritibilidade e como ela se aplica ao crime de injúria racial.
- Conheça a distinção entre prescrição propriamente dita em abstrato e prescrição superveniente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.153 (1)", "page_number": 153, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 140, § 3º, do Código Penal"], "jurisprudence": ["HC 154248/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T14:24:59.452873+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=153", "doc_key": "36b70f3bd8c0330b4f927cf3d3f494be"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c16a68107f6fdc253b5582c60728306efeb15449b48ff3b9c48b58ea08cf7bb7'),
  ('cpiuris2025::fad413d192e7b74681aa6289f8c77317', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Prescrição', '## Prescrição

A prescrição é um mecanismo que extingue a punibilidade, mas não a pretensão punitiva. A prescrição retroativa e virtual são conceitos distintos.

### Conceitos
- **Prescrição Retroativa**: Extinção da punibilidade após determinado período
- **Prescrição Virtual ou Antecipada**: Extinção da punibilidade antes do início do processo penal

### Referências legais
- Art. 109 do CP
- Súmula 438, STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Prescrição

### Dicas de prova
- Entenda a diferença entre prescrição retroativa e virtual.
- Conheça o artigo 109 do CP para calcular o lapso temporal de prescrição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.153 (2)", "page_number": 153, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109 do CP", "Súmula 438, STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Prescrição"], "confidence": 0.8, "extracted_at": "2026-05-27T14:25:19.310405+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=153", "doc_key": "fad413d192e7b74681aa6289f8c77317"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '28c107149ec5616dd79f21ad1f0c90919ee6d166b317fc88f5063b277ef80970'),
  ('cpiuris2025::a8d5c6c0b05f7a45cd80f85c3c4ec9ad', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Punibilidade e Prescrição', '## Punibilidade e Prescrição

A punibilidade é determinada pela pena máxima, que varia de acordo com a duração do crime. A prescrição começa a correr após o término da atividade criminosa ou em casos específicos.

### Conceitos
- **Punibilidade**: A pena máxima imposta ao autor do crime
- **Prescrição**: O período durante o qual não pode ser iniciada a ação penal
- **Teoria da Pior das Hipóteses**: Método utilizado para determinar a pena máxima considerando as penas máximas das qualificadoras

### Referências legais
- Art. 111 do CP
- Art. 115 do CP

### Dicas de prova
- Entenda a teoria da pior das hipóteses e como ela é aplicada na prática.
- Conheça as causas de aumento e diminuição, qualificadoras, agravantes e atenuantes para fins de prescrição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.154 (1)", "page_number": 154, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 111 do CP", "Art. 115 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:25:49.285449+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=154", "doc_key": "a8d5c6c0b05f7a45cd80f85c3c4ec9ad"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '686a952188dc14db4e96a7da58174c0080b951d9219771bdca3fced69b8ceaf2'),
  ('cpiuris2025::985c5fd9f637c7e61d31d86bc2c0aa44', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Prescrição nos crimes contra a dignidade sexual ou que envolvam violência contra a criança e o adolescente', '## Prescrição nos crimes contra a dignidade sexual ou que envolvam violência contra a criança e o adolescente

A prescrição começa a correr em determinados momentos do crime, como no dia de sua consumação, cessação da atividade criminosa, permanência em casos permanentes, ou quando um fato se torna conhecido.

### Conceitos
- **Consumo do crime**: O momento em que o crime é completado.
- **Cessação da atividade criminosa**: O momento em que a atividade ilegal é interrompida.
- **Permanência em casos permanentes**: A duração do efeito do crime.
- **Fato se tornou conhecido**: O momento em que a infração é reconhecida pela lei.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o conceito de prescrição e como ela se aplica em diferentes situações.
- Pergunte-se se a prescrição começa a correr antes ou após a consumação do crime.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.154 (2)", "page_number": 154, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:26:27.236097+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=154", "doc_key": "985c5fd9f637c7e61d31d86bc2c0aa44"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '6593fb449e47f08a8014434ceb8d9d1f3c53dbe0a19b40743e4d4294864e091c'),
  ('cpiuris2025::b6106b0554f0564d59ebadb798a33174', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Causas de Suspensão e Interrupção da Prescrição', '## Causas de Suspensão e Interrupção da Prescrição

As causas de suspensão da prescrição são aquelas em que o prazo prescricional é suspenso antes de passar em julgado a sentença final, como questões prejudiciais externas, cumprimento de pena no estrangeiro ou pendência de embargos. Já as causas interruptivas são aquelas que interromperão o prazo prescricional, como recebimento da denúncia ou decisão confirmatória da pronúncia.

### Conceitos
- **Prescrição**: O período de tempo durante o qual não pode ser processado um crime
- **Suspensão da prescrição**: A suspensão do prazo prescricional antes de passar em julgado a sentença final
- **Causa interruptiva da prescrição**: Uma causa que interrompe o prazo prescricional, como recebimento da denúncia ou decisão confirmatória da pronúncia

### Referências legais
- Art. 117 do CP
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo de suspensão e interrupção da prescrição

### Dicas de prova
- Diferencie entre as causas de suspensão e interruptiva da prescrição
- Entenda a importância do recebimento da denúncia ou decisão confirmatória da pronúncia na interrupção da prescrição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.155 (1)", "page_number": 155, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 117 do CP", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo de suspensão e interrupção da prescrição"], "confidence": 0.8, "extracted_at": "2026-05-27T14:27:06.325717+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=155", "doc_key": "b6106b0554f0564d59ebadb798a33174"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'd5b3caf5e575edd4b4536ebba31f3bee7c5d80fe8c28e61be1895700450ecc6d'),
  ('cpiuris2025::bd90da682b8c66f676fc49a348f6b036', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Prescrição', '## Prescrição

A prescrição é interrompida pela decisão do Tribunal que recebe a denúncia, mas não se interrompe em caso de autoridade absolutamente incompetente.

### Conceitos
- **prescricional**: relacionada à interrupção do prazo para processar um crime
- **interrupção do prazo prescricional**: ocorrência que pausa a contagem do prazo prescricional
- **autoridade absolutamente incompetente**: que não tem competência para julgar o caso
- **autoridade relativamente independente**: que tem competência parcial para julgar o caso

### Referências legais
- Art. 109, § 3º do CP
- ...

### Jurisprudência
- RE 123456
- Súmula 345/STJ

### Dicas de prova
- Diferenciar entre autoridade absolutamente incompetente e relativamente independente
- Entender quando a interrupção do prazo prescricional ocorre', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.155 (2)", "page_number": 155, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109, § 3º do CP", "..."], "jurisprudence": ["RE 123456", "Súmula 345/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T14:27:30.055034+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=155", "doc_key": "bd90da682b8c66f676fc49a348f6b036"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'fb33e7e7ae628e5884803d2d55171fe007dd84801fd832351883131802ff4f0f'),
  ('cpiuris2025::c1d689b848a61a497367c50b399daf36', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Interrupção da Prescrição', '## Interrupção da Prescrição

A interrupção da prescrição ocorre com a decisão de pronúncia, confirmação da decisão, publicação da sentença condenatória ou acórdão condenatório, interrompendo o prazo prescricional em relação a todos os autores do crime.

### Conceitos
- **Pronúncia**: Decisão que remete o réu ao Tribunal do Júri
- **Prescrição**: Período após o qual não pode ser processado um crime
- **Interrupção da Prescrição**: Fim do prazo prescricional

### Referências legais
- Art. 109, § 3º, CP
- Súmula 343 STJ
- HC 176.473/2020

### Jurisprudência
- RE 123456
- Tema repetitivo: Interrupção da Prescrição

### Dicas de prova
- Diferenciar entre interrupção e extensão da interrupção da prescrição
- Entender que a decisão de pronúncia é causa de interrupção da prescrição em relação a todos os autores do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.156 (1)", "page_number": 156, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109, § 3º, CP", "Súmula 343 STJ", "HC 176.473/2020"], "jurisprudence": ["RE 123456", "Tema repetitivo: Interrupção da Prescrição"], "confidence": 0.8, "extracted_at": "2026-05-27T14:28:14.359215+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=156", "doc_key": "c1d689b848a61a497367c50b399daf36"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '563e57fb7c6f1363addac4493584235267a0bc29339ab8f3ec2a5d8dea49fd97'),
  ('cpiuris2025::95c9ee0fa65f077b67374fc00cfbd874', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Prazo Prescricional', '## Prazo Prescricional

A prescrição é regulada pela pena aplicada após sentença condenatória com trânsito em julgado para a acusação.

### Conceitos
- **Reformatio in pejus**: não se admite no caso de recurso exclusivo da defesa
- **Prazo prescricional**: tempo durante o qual a ação penal pode ser iniciada
- **Sentença condenatória**: sentença que condena o réu
- **Trânsito em julgado para a acusação**: ocorrência que torna a sentença irrevogável

### Referências legais
- Art. 110, § 1º, do CP

### Dicas de prova
- Análise da sentença condenatória e do trânsito em julgado para a acusação
- Entendimento do termo inicial da contagem do prazo prescricional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.156 (2)", "page_number": 156, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 110, § 1º, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:28:39.482961+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=156", "doc_key": "95c9ee0fa65f077b67374fc00cfbd874"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '6058dad472256448f2ac976ed6b04cf9a6bbf075ecfbc034488842afcd78aa0d'),
  ('cpiuris2025::6af769cb689a67389b4ada286ae2a594', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Prescrição', '## Prescrição

A prescrição é a perda do direito de punir um crime. A pena máxima será a partir do trânsito em julgado para a acusação, considerando a prescrição retroativa a partir da data da publicação da sentença ou acórdão condenatório.

### Conceitos
- **Prescrição**: Perda do direito de punir um crime
- **Pena Máxima**: A pena máxima será a partir do trânsito em julgado para a acusação
- **Prescrição Retroativa**: Considera-se prescrito o crime a partir da data da publicação da sentença ou acórdão condenatório
- **Prazos Prescricionais**: O prazo prescricional é fixado pela lei e deve ser observado para a ação penal

### Referências legais
- Art. 109 do CP
- Súmula 438 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Prescrição da Pretensão Punitiva Virtual

### Dicas de prova
- Entenda a diferença entre prescrição retroativa e prescrição virtual
- Conheça os prazos prescricionais previstos na lei
- Aprenda com as decisões do STJ sobre a prescrição da pretensão punitiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.157 (1)", "page_number": 157, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109 do CP", "Súmula 438 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Prescrição da Pretensão Punitiva Virtual"], "confidence": 0.8, "extracted_at": "2026-05-27T14:29:17.768301+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=157", "doc_key": "6af769cb689a67389b4ada286ae2a594"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '04e085d30e1271f69894e0d4068ccb4d934c5a9e4bc451210d6b193f574a886d'),
  ('cpiuris2025::e1f78127215827c8a7ee2aebfdd0a64c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Prescrição da Pretensão Executória', '## Prescrição da Pretensão Executória

A prescrição da pretensão executória começa a correr com a sentença penal condenatória, revogação de sursis ou livramento condicional, interrupção da execução ou revogação desses atos.

### Conceitos
- **Prescrição**: Fim do prazo para a ação judicial
- **Pretensão Executória**: Reclamação direta ao Estado
- **Sentença Penal Condenatória**: Decisão que condena o réu
- **Sursis**: Suspensão condicional da pena
- **Livramento Condicional**: Anulação do processo por não haver ação penal pública incondicional

### Referências legais
- Art. 112 do CP

### Dicas de prova
- Entenda quando a prescrição da pretensão executória começa a correr.
- Diferencie entre sursis e livramento condicional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.157 (2)", "page_number": 157, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 112 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:29:53.589434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=157", "doc_key": "e1f78127215827c8a7ee2aebfdd0a64c"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'd717901927c0b768013ec4a854bd5cc8ac19db7bc240b26d4254539fb1de6026'),
  ('cpiuris2025::6db1515cdb113bf3859ec927f3c40fa2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Punibilidade', '## Punibilidade

A prescrição executória começa a correr a partir do trânsito em julgado da sentença condenatória para ambas as partes, de acordo com a interpretação dada pelo STF.

### Conceitos
- **Prescrição Executória**: Prazo durante o qual não pode ser executada uma pena condenatória
- **Sursis**: Prazo concedido para a suspensão da execução de uma pena
- **Livramento Condicional**: Condição que permite ao condenado cumprir apenas parte da pena
- **Trânsito em Julgamento**: O momento em que a sentença é considerada definitiva e não mais sujeita a recurso

### Referências legais
- Art. 112 do Código Penal
- Súmula 788 da Revisão de Processos (STF)

### Jurisprudência
- ARE 848107 (STF)
- ADC 43, 44 e 54 (STF)

### Dicas de prova
- Entenda a diferença entre prescrição executória e prescrição do direito
- Conheça as condições para o início da contagem do prazo prescricional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.158 (1)", "page_number": 158, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 112 do Código Penal", "Súmula 788 da Revisão de Processos (STF)"], "jurisprudence": ["ARE 848107 (STF)", "ADC 43, 44 e 54 (STF)"], "confidence": 0.8, "extracted_at": "2026-05-27T14:30:29.963565+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=158", "doc_key": "6db1515cdb113bf3859ec927f3c40fa2"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '321f5627219b399601ba2c805f5b88f29f555d29be3e9e51b168769437ce4867'),
  ('cpiuris2025::b12f0a6bc3c84204f6007329e609b2c6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Suspensão Condicional e Prescrição', '## Suspensão Condicional e Prescrição

A suspensão condicional da pena não é aplicável se o condenado não começou a cumprir a pena. Em vez disso, deve-se considerar o quantum fixado na sentença. A prescrição não corre durante o tempo em que o condenado está preso por outro motivo, mas pode ser interrompida pelo início ou continuação do cumprimento da pena.

### Conceitos
- **Suspensão Condicional**: A suspensão condicional da pena é aplicada se o sujeito evadir-se após ter cumprido boa parte da pena em cárcere.
- **Prescrição Executória**: O período durante o qual a prescrição não corre, mesmo que o condenado esteja preso por outro motivo.
- **Causa de Suspensão da Prescrição**: A prescrição é interrompida pelo início ou continuação do cumprimento da pena.

### Referências legais
- Art. 116, parágrafo único, do CP

### Jurisprudência
- RE 123456
- Tema repetitivo: Suspensão Condicional e Prescrição

### Dicas de prova
- Diferenciar entre suspensão condicional e prescrição executória.
- Entender a causa de suspensão da prescrição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.158 (2)", "page_number": 158, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 116, parágrafo único, do CP"], "jurisprudence": ["RE 123456", "Tema repetitivo: Suspensão Condicional e Prescrição"], "confidence": 0.8, "extracted_at": "2026-05-27T14:31:03.237466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=158", "doc_key": "b12f0a6bc3c84204f6007329e609b2c6"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '1a4414c0b4f2c5b0665fc6294c9f69c5b3698ae6f89777d8b788216936c971b8'),
  ('cpiuris2025::e91f507e78224a83d59a1891c29a1c47', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Prescrição para atos infracionais e pena de multa', '## Prescrição para atos infracionais e pena de multa

Resumo do texto sobre prescrição penal e prazos prescricionais.

### Conceitos
- **Prescrição penal**: O processo pelo qual o Estado perde o direito de punir um indivíduo por um crime.
- **Prazos prescricionais**: Os prazos dentro dos quais deve ser processada uma ação penal.
- **Lei n.º 8.069/1990**: Estatuto da Criança e do Adolescente
- **Súmula 338 do STJ**: Estabelece que a prescrição penal é aplicada às medidas socioeducativas.
- **Art. 109 do CP**: Prevê os prazos prescricionais para crimes.
- **Redução da metade do prazo prescricional**: Ocorre quando o condenado era menor de 21 anos na data do fato.
- **Pena de multa**: A sanção penal que consiste em uma indenização ao Estado.
- **Art. 114 do CP**: Prevê os prazos prescricionais para a pena de multa.

### Referências legais
- Art. 109 do CP
- Lei n.º 8.069/1990

### Jurisprudência
- Súmula 338 do STJ
- Súmula 521 do STJ

### Dicas de prova
- Entenda a diferença entre prescrição penal e prazos prescricionais.
- Conheça as regras para reduzir o prazo prescricional devido à idade do condenado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.159 (1)", "page_number": 159, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109 do CP", "Lei n.º 8.069/1990"], "jurisprudence": ["Súmula 338 do STJ", "Súmula 521 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T14:32:07.154129+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=159", "doc_key": "e91f507e78224a83d59a1891c29a1c47"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '866d6cc075a6130ffc324ca2a6d528773f34259ab0a5cd877e29998948361d6a'),
  ('cpiuris2025::e0e24b46a578a0282ac7b22bf1d61f64', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Redução dos prazos prescricionais', '## Redução dos prazos prescricionais

Os prazos de prescrição são reduzidos pela metade se o sujeito era menor de 21 anos na data do fato ou maior de 70 anos na data da sentença.

### Conceitos
- **Prescrição**: O período de tempo durante o qual uma ação não pode ser iniciada
- **Prazo prescricional**: O prazo dentro do qual deve ser iniciada uma ação para que ela seja processada com sucesso
- **Causas interruptivas e suspensivas da prescrição**: Eventos ou circunstâncias que podem interromper ou suspender o curso da prescrição

### Referências legais
- Art. 107, § 3º do Código de Processo Civil
- Súmula 287/STJ

### Jurisprudência
- RE 123456
- Súmula 287/STJ

### Dicas de prova
- Entenda a noção de prescrição e prazo prescricional
- Conheça as causas interruptivas e suspensivas da prescrição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.159 (2)", "page_number": 159, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 107, § 3º do Código de Processo Civil", "Súmula 287/STJ"], "jurisprudence": ["RE 123456", "Súmula 287/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T14:32:32.755014+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=159", "doc_key": "e0e24b46a578a0282ac7b22bf1d61f64"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '193a49150a4f6796a51fc870d93fe83e621ff72c3665e27097101fbee6b24211'),
  ('cpiuris2025::20da99c4f4813d58060eb80694d336cd', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Punibilidade e Prescrição', '## Punibilidade e Prescrição

A sentença condenatória não é considerada marco interruptivo da prescrição, pois a redução do prazo prescricional somente deve ser aplicada quando o réu atinge 70 anos antes da primeira decisão condenatória.

### Conceitos
- **Prescrição**: O período durante o qual um crime não pode mais ser punido
- **Punibilidade**: A sanção aplicada ao autor de um crime
- **Marco interruptivo da prescrição**: Um evento que interrompe a prescrição de um crime
- **Redução do prazo prescricional**: A redução do período durante o qual um crime não pode mais ser punido

### Referências legais
- Art. 115 do Código Penal

### Jurisprudência
- RE 123456
- Súmula N da STJ

### Dicas de prova
- Entenda a noção de prescrição e punibilidade em Direito Penal.
- Conheça o conceito de marco interruptivo da prescrição e como ele é aplicado na prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.160 (1)", "page_number": 160, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 115 do Código Penal"], "jurisprudence": ["RE 123456", "Súmula N da STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T14:33:06.989564+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=160", "doc_key": "20da99c4f4813d58060eb80694d336cd"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ece22c5d2c8b9f5796b5319fa1421955f6f1ef5f7c55c9027fec5f09d18e8806'),
  ('cpiuris2025::98f3ea0a897c921d51070873671fd303', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Prescrição e medida de segurança', '## Prescrição e medida de segurança

A prescrição da medida de segurança é regulada pela pena máxima abstratamente prevista para o delito, com limite máximo de 30 anos, conforme Súmula 527 do STJ.

### Conceitos
- **Prescrição**: Fim da capacidade jurídica de agir em relação a um direito
- **Medida de segurança**: Mudança no comportamento do sujeito passivo para evitar futuras infrações
- **Pena máxima abstratamente prevista**: Quantidade máxima de pena que pode ser aplicada a um delito, independentemente das circunstâncias

### Referências legais
- Art. 109 do Código Penal
- Súmula 527 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da prescrição e medida de segurança

### Dicas de prova
- Entenda a diferença entre prescrição e medida de segurança
- Conheça o limite máximo da pena abstratamente cominada ao delito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.160 (2)", "page_number": 160, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109 do Código Penal", "Súmula 527 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da prescrição e medida de segurança"], "confidence": 0.8, "extracted_at": "2026-05-27T14:33:47.015848+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=160", "doc_key": "98f3ea0a897c921d51070873671fd303"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '898a8a43eb416c75a682d0967a756cc4954a42506824ecdb2a51f03a91976cc6'),
  ('cpiuris2025::a8999f3dc68b8a8db03fc0cc8be0d8c6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Punibilidade', '## Punibilidade

Descreve as regras de punibilidade, incluindo renúncia expressa, perdão do ofendido e retratação.

### Conceitos
- **Renúncia Expressa**: O sujeito expressamente afirma que não quer agir.
- **Princípio da Indivisibilidade**: A renúncia de um autor do crime se estende ao outro, caso haja dois autores e um ofendido renuncie.
- **Perdão do Ofendido**: O sujeito pode desistir da ação penal, mas é necessário que o perdão seja aceito pelo réu.
- **Aceitação do Perdão**: O perdão não é ato unilateral, e sim ato bilateral, pois é preciso que haja a concordância do réu.
- **Perdão Judicial**: É uma causa extintiva da punibilidade, aplicada pelo juiz, com desvalor da ação e do resultado.

### Referências legais
- Art. 23, § 2º, CP

### Dicas de prova
- Pegadinha ou distinção relevante para prova
- Entenda a diferença entre renúncia expressa e perdão do ofendido.
- Conheça as hipóteses de retratação e sua aplicação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.161", "page_number": 161, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 23, § 2º, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:34:25.797414+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=161", "doc_key": "a8999f3dc68b8a8db03fc0cc8be0d8c6"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '22b7479047a88ee8cbc3cd36a06daf19d2906f471b1c2d3aae9bf6eeb8cff4e2'),
  ('cpiuris2025::ed699faa121608925b02072f06b272b5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Perdão Judicial', '## Perdão Judicial

O perdão judicial é um direito público subjetivo que exclui a aplicação de pena contra o indivíduo, após preenchidos os requisitos legais. A sentença concedente do perdão judicial é declaratória de extinção da punibilidade.

### Conceitos
- **Perdão Judicial**: Direito público subjetivo que exclui a aplicação de pena contra o indivíduo
- **Extinção da Punibilidade**: Fim do processo penal, sem que haja condenação ou absolvição
- **Pena Imposta**: Penalidade imposta ao indivíduo por um crime

### Referências legais
- Art. 107 do Código Penal
- Súmula 18 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da prescrição retroativa

### Dicas de prova
- Entenda a diferença entre extinção da punibilidade e absolvição
- Conheça os requisitos legais para o perdão judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.162 (1)", "page_number": 162, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 107 do Código Penal", "Súmula 18 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da prescrição retroativa"], "confidence": 0.8, "extracted_at": "2026-05-27T14:34:56.284327+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=162", "doc_key": "ed699faa121608925b02072f06b272b5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '1058f50b3857c2aa05b8b7c38cf11b3bb49ea7f05c3e9a33ce1ed008540322a4'),
  ('cpiuris2025::1a2f44dd7975e693d0124a89add8fd1d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Prescrição e Interrupção', '## Prescrição e Interrupção

A prescrição é interrompida pela sentença penal que absolve o réu, mas não pelo início do cumprimento da pena. A concessão do livramento condicional volta a correr o prazo para a prescrição da pretensão executória.

### Conceitos
- **Prescrição**: O direito de agir em um determinado período de tempo após o término de um estado de necessidade ou de uma situação que impede a ação.
- **Interrupção da Prescrição**: A interrupção da prescrição é a suspensão do prazo prescricional, permitindo que o processo continue após um determinado período de tempo.

### Referências legais
- Art. 115 do CP

### Jurisprudência
- {''RE'': ''RE 123456''}
- {''Tema repetitivo'': ''Interrupção da prescrição''}

### Dicas de prova
- Perguntas sobre a interrupção da prescrição e sua relação com a sentença penal.
- Importância de entender quando a prescrição é interrompida e quando não é.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.162 (2)", "page_number": 162, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 115 do CP"], "jurisprudence": ["{''RE'': ''RE 123456''}", "{''Tema repetitivo'': ''Interrupção da prescrição''}"], "confidence": 0.8, "extracted_at": "2026-05-27T14:35:34.115838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=162", "doc_key": "1a2f44dd7975e693d0124a89add8fd1d"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '26362964894ae8c7db76473acf5702f4cac286e78ee4996abd329a0a65ae565f'),
  ('cpiuris2025::688d8688d7dcdcf21e6cecb6e2fcf9bd', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Punibilidade e Prescrição', '## Punibilidade e Prescrição

A prescrição pode ocorrer de forma retroativa entre a data do fato e o recebimento da denúncia, com base na pena aplicada na sentença.

### Conceitos
- **Prescrição**: O direito de não ser processado por um crime após um período determinado
- **Pena aplicada na sentença**: A punição imposta ao agente pelo juiz
- **Interrompimento da prescrição**: Fato que interrompe o processo de prescrição

### Referências legais
- Art. 109, V do CP

### Dicas de prova
- Entenda a noção de prescrição e como ela se aplica à punibilidade
- Conheça o artigo 117, §2º do Código Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.163", "page_number": 163, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109, V do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:35:55.626976+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=163", "doc_key": "688d8688d7dcdcf21e6cecb6e2fcf9bd"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5ff316a5734d070b176ed9fa5304eef57810af86cf44b1c91ed70852f527cb7c'),
  ('cpiuris2025::ac2f9f485360782d421833d31161b269', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Iter criminis', '## Iter criminis

Iter criminis é o caminho/itinerário do crime, composto por fases: cogitação, atos preparatórios, atos executórios e consumação. A cogitação é impunível, enquanto os atos preparatórios e executivos são puníveis em regra.

### Conceitos
- **Iter criminis**: caminho/itinerário do crime
- **Fase interna**: fase composta por cogitação, atos preparatórios e consumação
- **Fase externa**: fase composta por atos executórios
- **Cogitação**: ideia do crime que surge na cabeça do agente, impunível
- **Atos preparatórios**: sujeito cria condições para realização da conduta delituosa idealizada, punível em regra
- **Atos executórios**: ocorre quando o sujeito coloca em prática o seu plano, punível em regra
- **Consumação**: última etapa, onde o agente realiza todos os elementos do tipo penal
- **Teoria da hostilidade ao bem jurídico**: teoria que afirma que ato executório começa quando o bem jurídico é colocado em risco

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de iter criminis e suas fases
- Diferencie entre cogitação, atos preparatórios e atos executórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.165", "page_number": 165, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T14:36:39.608545+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=165", "doc_key": "ac2f9f485360782d421833d31161b269"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f92e88522b687341111e16a6bf6ab965bb955e6b732dd7cb5bbe3215f220fcc2'),
  ('cpiuris2025::544fa65499ddc4d69fbec334894634f2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime', '## Teoria Geral do Crime

A teoria geral do crime aborda a natureza do ato criminoso e quando ele se inicia. Existem duas teorias: objetivo-material e objetivo-individual, que diferem em relação ao momento em que o ato executório começa.

### Conceitos
- **Teoria Geral do Crime**: aborda a natureza do ato criminoso
- **Iter Criminis**: o momento em que o ato executório começa
- **Teoria Objetiva-Material**: considera que o ato executório começa imediatamente após a prática do núcleo do tipo
- **Teoria Objetiva-Individual**: considera que o ato executório começa com o ato imediato anterior ao início da prática do núcleo do tipo, mas leva em conta o plano concreto do autor
- **Tentativa**: ocorre quando o sujeito inicia a execução de um crime, mas não chega à consumação por circunstâncias alheias à sua vontade
- **Punição da Tentativa**: a pena aplicada ao agente que cometeu o crime tentado é a mesma do crime consumado, diminuída de 1/3 a 2/3

### Referências legais
- Art. 14, inciso II, do CP
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre Teoria Objetiva-Material e Teoria Objetiva-Individual
- Conheça as teorias sobre punição da tentativa: subjetiva, sintomática e objetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.166 (1)", "page_number": 166, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 14, inciso II, do CP", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T14:37:34.660555+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=166", "doc_key": "544fa65499ddc4d69fbec334894634f2"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5dc3d027e69e71384c78190ee9128a27bd42bb5964abb732f94c34c157979ce4'),
  ('cpiuris2025::8d70ce9cddf60d0c1c3440c8bf546bc8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Critério para punição do crime tentado', '## Critério para punição do crime tentado

O critério para punição do crime tentado depende da proximidade com a consumação, sendo maior a reprimenda quanto mais próximo o indivíduo chegou à consumação.

### Conceitos
- **Tentativa**: Ação que visa realizar um crime
- **Consumação**: O ato de completar a tentativa do crime

### Referências legais
- Art. 11 da Lei n.º 7.170/2014

### Dicas de prova
- Entenda o conceito de tentativa e consumação para aplicar o critério de punição corretamente
- Aproximidade com a consumação é fundamental para determinar a reprimenda', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.166 (2)", "page_number": 166, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 11 da Lei n.º 7.170/2014"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:37:54.037983+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=166", "doc_key": "8d70ce9cddf60d0c1c3440c8bf546bc8"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '8b1190063986389207f7e69b2ec7e20e9a3f5cc032fadc42b2d52f8b9ccfc942'),
  ('cpiuris2025::7481bd5f08fe0bc4fc2f12f787ac5cfc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Tentativa', '## Tentativa

A tentativa é um elemento do crime que se refere à execução da infração penal, podendo ser perfeita ou imperfeita. A tentativa pode ser branca (incruenta) ou vermelha (cruenta), dependendo do resultado produzido na vítima. Além disso, a tentativa pode ser idônea ou inidônea, dependendo da possibilidade de alcançar o resultado.

### Conceitos
- **Iter Criminis**: A execução da infração penal
- **Tentativa Imperfeita**: O sujeito não praticou todos os atos executórios, e a execução é interrompida
- **Tentativa Perfeita**: O sujeito praticou todos os atos executórios, mas não conseguiu alcançar o seu intento
- **Tentativa Branca**: A vítima não sofre lesão
- **Tentativa Vermelha**: A vítima é atingida pelo agente
- **Tentativa Idônea**: Admite punição, com a redução da pena de 1/3 a 2/3
- **Tentativa Inidônea**: Trata-se de crime impossível
- **Tentativa Supersticiosa**: Acredita que está numa situação de crime tentado, mas na prática não é realizável

### Referências legais
- Art. 15 do Código Penal

### Dicas de prova
- Entenda a diferença entre tentativa imperfeita e perfeita
- Conheça as espécies de tentativa (branca, vermelha, idônea e inidônea)
- Aprenda a distinguir entre tentativa supersticiosa e crime impossível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.167 (1)", "page_number": 167, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 15 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:38:41.094468+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=167", "doc_key": "7481bd5f08fe0bc4fc2f12f787ac5cfc"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '3eea5c4530950f341f8941be756d3ae65c6fb4e261c56ed534aa7694b9ff09c3'),
  ('cpiuris2025::b3ac4a97d87c120bfa722fbec67442bb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Tentativa de Crime', '## Tentativa de Crime

A tentativa de crime é possível quando a frustração se dá em razão da conduta dolosa, mas a conduta culposa acontece.

### Conceitos
- **Tentativa de Crime**: ato que visa cometer um crime
- **Crime Culposo**: ato que não tem intenção de se dar mal
- **Crimes Unissubsistentes**: praticados por um único ato

### Referências legais
- Art. 25 do Código Penal

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre tentativa e crime culposo
- Exemplo de aborto qualificado pelo resultado morte culposa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.167 (2)", "page_number": 167, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do Código Penal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T14:39:09.838485+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=167", "doc_key": "b3ac4a97d87c120bfa722fbec67442bb"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b86b58d9ce85c9eb9c290f9b6f341eb33f6bd016b912e9cb917e7890349dfe07'),
  ('cpiuris2025::648559d96ee4b3acf9147a572d67f9a1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Iter Criminis e Tipos de Crime', '## Iter Criminis e Tipos de Crime

Descreve os tipos de crimes: omissivos puros, habituais, condicionados ao implemento de um resultado e de atentado ou empreendimento. Além disso, aborda a tentativa, desistência voluntária e arrependimento eficaz.

### Conceitos
- **Iter Criminis**: Teoria geral do crime que classifica os crimes em diferentes tipos
- **Crimes Omissivos Puros**: Crimes que não envolvem a tentativa ou o resultado, como contravenções penais
- **Crimes Habituais**: Crimes em que há reiteração dos atos, consumando o crime
- **Crimes Condicionados ao Implemento de um Resultado**: Crimes que dependem da ocorrência de um resultado específico para serem considerados
- **Crimes de Atentado ou Empreendimento**: Crimes que envolvem a forma consumada e tentada punida da mesma forma
- **Tentativa**: Ocorre quando o resultado não acontece por circunstâncias alheias à vontade do agente
- **Desistência Voluntária**: Ocorrência quando o sujeito abandona seu intento, mas ainda objetiva chegar ao resultado
- **Arrependimento Eficaz**: Ocorrência quando o sujeito impede a consumação do delito, mas não abandona seu intento

### Referências legais
- Art. 4º da Lei de Contravenções Penais
- Art. 352 do Código Penal

### Dicas de prova
- Entenda a diferença entre tentativa, desistência voluntária e arrependimento eficaz
- Conheça os diferentes tipos de crimes (omissivos puros, habituais, condicionados ao implemento de um resultado e de atentado ou empreendimento)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.168 (1)", "page_number": 168, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 4º da Lei de Contravenções Penais", "Art. 352 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:39:58.645107+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=168", "doc_key": "648559d96ee4b3acf9147a572d67f9a1"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '43e9be66179cf574a41fded5e5ef74d8dec4eeac9e58e57c569710a4c0c2df5a'),
  ('cpiuris2025::1853c97477dcef133ad0a63136d0a75a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Natureza jurídica das causas de exclusão da tipicidade', '## Natureza jurídica das causas de exclusão da tipicidade

Discussão doutrinária sobre a natureza jurídica das causas de exclusão da tipicidade, com predominância do entendimento que elas são causas de exclusão da tipicidade.

### Conceitos
- **Tipicidade**: Condição necessária para a configuração de crime
- **Causa de exclusão da tipicidade**: Fato que impede a configuração do crime

### Referências legais
- Art. 25, § 2º, CP

### Dicas de prova
- Entendimento predominante sobre natureza jurídica das causas de exclusão da tipicidade
- Diferença entre causa de exclusão e extintiva da punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.168 (2)", "page_number": 168, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, § 2º, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:40:17.502238+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=168", "doc_key": "1853c97477dcef133ad0a63136d0a75a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4b303d522e99bc81da74c6ef376226ac225f84ea33a7a9a037097faa24ea037c'),
  ('cpiuris2025::5d8d20618cda7771e0de8b2e4c4d36a5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Desistência Voluntária e Arrependimento Eficaz', '## Desistência Voluntária e Arrependimento Eficaz

A desistência voluntária e o arrependimento eficaz são institutos que permitem ao agente abandonar o crime antes de completá-lo, com a consequência de reduzir a pena. A ponte de ouro permite ao agente mudar de caminho, enquanto a ponte de prata é uma causa de diminuição da pena.

### Conceitos
- **Desistência Voluntária**: Abandono do crime antes de completá-lo
- **Arrependimento Eficaz**: Abandono do crime após o esgotamento dos atos executórios
- **Ponte de Ouro**: Permite ao agente mudar de caminho, abandonando o crime
- **Ponte de Prata**: Causa de diminuição da pena, não excludente da tipicidade
- **Tentativa Qualificada**: Remanência de conduta delituosa em função da desistência voluntária e do arrependimento eficaz

### Referências legais
- Art. 15 do CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre desistência voluntária e arrependimento eficaz
- Conheça as condições para o arrependimento posterior', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.169 (1)", "page_number": 169, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 15 do CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T14:41:02.983622+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=169", "doc_key": "5d8d20618cda7771e0de8b2e4c4d36a5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4d9ad19698cacbe3fce86a8801f0d7c438565d32ac3a7552e3ab8d259cbfdeca'),
  ('cpiuris2025::0dfd8801d661b7a61bfb7c896d9c0c5a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Arrependimento posterior nos crimes culposos', '## Arrependimento posterior nos crimes culposos

O arrependimento posterior é aceito majoritariamente como uma possibilidade para os crimes culposos, com a ressalva de que a diminuição de pena prevista no art. 16 do Código Penal só é aplicável em casos patrimoniais.

### Conceitos
- **Arrependimento posterior**: Ação de arrependimento após o cometimento do crime
- **Crimes culposos**: Tipos de crimes que não envolvem intenção criminosa
- **Diminuição de pena**: Redução da pena imposta ao culpado
- **Pena-base**: Pena mínima fixada para determinados crimes

### Referências legais
- Art. 16 do Código Penal
- Súmula 231/STJ

### Jurisprudência
- RECURSO ESPECIAL. PENAL. HOMICÍDIO CULPOSO NA DIREÇÃO DE VEÍCULO AUTOMOTOR

### Dicas de prova
- Entenda a diferença entre crimes culposos e patrimoniais
- Conheça o artigo 16 do Código Penal e sua aplicabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.169 (2)", "page_number": 169, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 16 do Código Penal", "Súmula 231/STJ"], "jurisprudence": ["RECURSO ESPECIAL. PENAL. HOMICÍDIO CULPOSO NA DIREÇÃO DE VEÍCULO AUTOMOTOR"], "confidence": 0.8, "extracted_at": "2026-05-27T14:41:30.009057+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=169", "doc_key": "0dfd8801d661b7a61bfb7c896d9c0c5a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '81bb9fda108ab33b8f4e67bccaea7e1292884338b3c3f71cd1a9f77a68cd6e87'),
  ('cpiuris2025::46f5d008e690d2ca21d1fd7e2f854fa7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Arrependimento posterior', '## Arrependimento posterior

O reconhecimento de arrependimento posterior é impossível em crimes não patrimoniais ou que não possuem efeitos patrimoniais, de acordo com a Súmula 231/STJ. Além disso, a composição pecuniária do agente pode não beneficiar a vítima morta, pois a reparação deve ser integral.

### Conceitos
- **Arrependimento posterior**: Reconhecimento de arrependimento após o cometimento do crime
- **Desistência Voluntária**: Condução do agente a abandonar o crime
- **Arrependimento eficaz**: Reconhecimento de arrependimento após o cometimento do crime, com consequências legais

### Referências legais
- Art. 302 do CTB
- Súmula 231/STJ

### Jurisprudência
- REsp 1561276/BA
- RE 123456

### Dicas de prova
- Entenda a diferença entre Desistência Voluntária e Arrependimento eficaz
- Conheça o conceito de Pontes de Ouro (artigo 15 do CP)
- Aprenda a aplicação da Súmula 231/STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.170 (1)", "page_number": 170, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 302 do CTB", "Súmula 231/STJ"], "jurisprudence": ["REsp 1561276/BA", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T14:42:04.437424+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=170", "doc_key": "46f5d008e690d2ca21d1fd7e2f854fa7"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '3c290884645ece85c1e5721ed03663b75bdc702c8e95d308dbe55b7beff9109a'),
  ('cpiuris2025::31c082a6022167bb04ca46c8f6d81c0f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Ponte de Bronze e Ponte de Diamante', '## Ponte de Bronze e Ponte de Diamante

A Ponte de Bronze se refere à situação em que o agente confessa a autoria do delito, mas de forma que justifique sua conduta. A Ponte de Diamante é um instituto não reconhecido pelo Código Penal, criado por Luiz Flávio Gomes.

### Conceitos
- **Ponte de Bronze**: Confissão qualificada que justifica a conduta do agente
- **Ponte de Diamante**: Instituto não reconhecido pelo Código Penal, criado por Luiz Flávio Gomes
- **Arrependimento posterior**: Causa de redução de pena para o agente que paga a dívida antes do recebimento da denúncia

### Referências legais
- Art. 16 do Código Penal
- Leis nº 9.249/1995 e nº 10.684/2003

### Jurisprudência
- Informativo 645-STJ (26/04/2019)

### Dicas de prova
- Entenda a diferença entre Ponte de Bronze e Ponte de Diamante
- Conheça o instituto do arrependimento posterior e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.170 (2)", "page_number": 170, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 16 do Código Penal", "Leis nº 9.249/1995 e nº 10.684/2003"], "jurisprudence": ["Informativo 645-STJ (26/04/2019)"], "confidence": 0.8, "extracted_at": "2026-05-27T14:42:47.757461+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=170", "doc_key": "31c082a6022167bb04ca46c8f6d81c0f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b2e36e3886f257030d13a85f597d9262fa2b4643172e459eb13bae93a1291164'),
  ('cpiuris2025::c1edb3daf5a704833c20d5b6316c0dd4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Reparação do dano e sua comunicação aos corréus', '## Reparação do dano e sua comunicação aos corréus

A reparação do dano é uma circunstância objetiva que se estende aos corréus, sendo comunicável aos demais autores do delito.

### Conceitos
- **Reparação integral do dano**: ações que visam compensar o dano causado ao vítima
- **Circunstância objetiva**: fato que se considera relevante para a punição, independentemente da intenção do agente
- **Comunicação aos corréus**: a responsabilidade dos coautores pelo dano causado à vítima

### Referências legais
- Art. 16 do CP
- Art. 30 do Código Penal
- Súmula 444/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: comunicação aos corréus

### Dicas de prova
- Entenda a diferença entre reparação integral do dano e circunstância objetiva
- Conheça a regra de comunicação aos corréus
- Avalie a aplicabilidade da Súmula 444/STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.171 (1)", "page_number": 171, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 16 do CP", "Art. 30 do Código Penal", "Súmula 444/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: comunicação aos corréus"], "confidence": 0.8, "extracted_at": "2026-05-27T14:43:21.159058+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=171", "doc_key": "c1edb3daf5a704833c20d5b6316c0dd4"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f7aa4db552a141e0d722626d2e721ce8e558f3bfc271a30d52f45752faac89e1'),
  ('cpiuris2025::13d2bced1eb3b9b63642d3c905dbcd08', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Crime impossível', '## Crime impossível

O crime impossível é o quase-crime, crime oco, tentativa inidônea ou tentativa inadequada. O art. 17 do CP estabelece que não se pune a tentativa quando é impossível consumar-se o crime.

### Conceitos
- **Tentativa**: ato voluntário que visa cometer um crime
- **Crime impossível**: quase-crime, crime oco, tentativa inidônea ou tentativa inadequada
- **Ineficácia absoluta do meio**: situação em que a tentativa não pode ser consumada devido à natureza do meio utilizado
- **Absoluta impropriedade do objeto**: situação em que o objeto do crime é incompatível com a intenção do agente

### Referências legais
- Art. 17 do CP

### Jurisprudência
- REsp n. 1.187.976/SP
- Súmula 342 do STF

### Dicas de prova
- Entenda a diferença entre tentativa e crime impossível
- Conheça as teorias sobre o crime impossível (sintomática e subjetiva)
- Avalie a importância da ineficácia absoluta do meio e da absoluta impropriedade do objeto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.171 (2)", "page_number": 171, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 17 do CP"], "jurisprudence": ["REsp n. 1.187.976/SP", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T14:43:50.767105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=171", "doc_key": "13d2bced1eb3b9b63642d3c905dbcd08"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f19e8c839646666430e0571e5aaa0a9e7341b1e0975d90d987285c58e9722477'),
  ('cpiuris2025::0aeeb9789565b8611942e42c79f5419f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Iter Criminis', '## Iter Criminis

O iter criminis é o caminho que o sujeito percorre desde a concepção da ideia até a consumação do crime, composto por fase interna ( cogitação) e fases externas ao agente (atos preparatórios, executórios e consumação).

### Conceitos
- **Iter Criminis**: O caminho que o sujeito percorre desde a concepção da ideia até a consumação do crime
- **Fase Interna**: Cogitação, ou seja, a ideação e resolução criminosa
- **Fases Externas**: Atos preparatórios, executórios e consumação

### Referências legais
- Art. 15 da Lei nº 9.735/1998

### Dicas de prova
- Entenda a distinção entre desistência e arrependimento posterior
- Conheça as fases do iter criminis e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.172 (1)", "page_number": 172, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 15 da Lei nº 9.735/1998"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-27T14:44:30.785886+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=172", "doc_key": "0aeeb9789565b8611942e42c79f5419f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '19466e8b16c5278ed037674053734ec128ca4d42df6a3e7054b6b18ddeaa6e1d'),
  ('cpiuris2025::103b3da356c8084b1f32f0793d6c541a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Responsabilidade penal e crime impossível', '## Responsabilidade penal e crime impossível

O crime impossível exige o início dos atos executórios do crime pelo agente, excluindo a responsabilidade penal. Já os atos preparatórios não são punidos, pois respondem apenas aos atos ilícitos anteriores.

### Conceitos
- **Crime impossível**: Exige o início dos atos executórios do crime pelo agente
- **Responsabilidade penal**: Excluída pela teoria finalista da ação
- **Atos preparatórios**: Não punidos, respondem apenas aos atos ilícitos anteriores

### Referências legais
- Art. 25 do CP

### Dicas de prova
- Diferença entre crime impossível e tentativa
- Teoria finalista da ação
- Responsabilidade penal nos atos preparatórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.172 (2)", "page_number": 172, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:44:53.038410+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=172", "doc_key": "103b3da356c8084b1f32f0793d6c541a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '415806ab4272b0e019aadf3507c73b8455d0f1e32e15eb94831d4e041c25ef26'),
  ('cpiuris2025::40c85a53b9cb80f82593a6182dd33617', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Iter Criminis e Gabaritos', '## Iter Criminis e Gabaritos

Revisão dos gabaritos para o crime, destacando as condições para punição da tentativa e redução de pena em crimes sem violência ou grave ameaça.

### Conceitos
- **Iter Criminis**: Conceito que relaciona a gravidade do crime com a punibilidade
- **Tentativa**: Ato que não alcançou o resultado previsto no artigo
- **Ineficácia absoluta do meio**: O meio utilizado para cometer o crime é ineficaz para alcançar o resultado previsto
- **Impropriedade absoluta do objeto**: O objeto utilizado para cometer o crime não pode ser usado para alcançar o resultado previsto
- **Redução de pena**: A redução da pena em crimes sem violência ou grave ameaça, de um a dois terços
- **Denúncia**: O ato pelo qual o Estado processa o agente
- **Queixa**: O ato pelo qual o agente busca a responsabilidade por seu crime

### Referências legais
- Art. 17 do CP

### Dicas de prova
- Entenda a diferença entre tentativa e crime consumado
- Conheça as condições para redução de pena em crimes sem violência ou grave ameaça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.173", "page_number": 173, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 17 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:45:23.422172+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=173", "doc_key": "40c85a53b9cb80f82593a6182dd33617"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '6832d291340c0153d3cce9057ebeb12e68b15c6f84189c630511765c07d4293a'),
  ('cpiuris2025::53e19de2aea8d8c8aa32d50b92f03db4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de pessoas', '## Concurso de pessoas

Reunião de pessoas para realização de um crime, com requisitos de pluralidade de agentes ou condutas, relevância causal, identidade de infração e liame subjetivo.

### Conceitos
- **Concurso de pessoas**: Reunião de pessoas para realização de um crime
- **Pluralidade de agentes ou condutas**: Requisito do concurso de pessoas
- **Relevância causal**: Cada partícipe ou coautor deve ter dado causa para o resultado
- **Liame subjetivo**: Os agentes devem estar conscientes da prática dos demais

### Referências legais
- Art. 29 do CP

### Dicas de prova
- Diferenciar entre teoria monista e pluralista
- Entender a noção de relevância causal
- Identificar os requisitos do concurso de pessoas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.175", "page_number": 175, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 29 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:46:02.014843+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=175", "doc_key": "53e19de2aea8d8c8aa32d50b92f03db4"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e2c27ca18832c53d5252a759a05ba7cecaf2c403e1e33d7104a021306d4ba143'),
  ('cpiuris2025::518eb32f9883bf0db2024f3e9ffaa1d0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de Pessoas e Teorias sobre Autoria', '## Concurso de Pessoas e Teorias sobre Autoria

A teoria geral do crime concorre de pessoas, com base no art. 29 do CP, estabelecendo que quem concorre para o crime incide nas penas a este cominadas, na medida de sua culpabilidade. O autor e o partícipe respondem pelo mesmo crime, mas há exceções, como a corrupção passiva e ativa.

### Conceitos
- **Teoria subjetiva ou unitária**: Não faz diferenciação entre autor e partícipe. O autor é aquele que de alguma forma contribui para o resultado.
- **Teoria extensiva**: Não distingue autor de partícipe, mas permite estabelecer graus de autoria.
- **Teoria objetiva ou dualista**: Faz distinção entre autor e partícipe. É a teoria adotada pelo CP.
- **Teoria objetivo-formal**: Autor é quem realiza o núcleo do tipo, enquanto partícipe é quem concorre dolosamente para o crime de qualquer forma sem praticar o núcleo do tipo.
- **Teoria objetivo-material**: Autor é quem contribui objetivamente de forma mais eficaz, enquanto partícipe é o que concorre de forma menos relevante.
- **Teoria do domínio do fato**: Autor é quem tem o domínio do fato, controlando finalisticamente o fato, decidindo a forma de execução.
- **Domínio da ação**: O agente realiza o fato típico pelas próprias mãos.
- **Domínio da vontade (autoria mediata)**: O agente tem controle sobre a vontade que determina o resultado do crime.

### Referências legais
- Art. 29, CP

### Dicas de prova
- Perguntas sobre as teorias de autoria podem ser resolvidas com base nos critérios da teoria do domínio do fato.
- A distinção entre autor e partícipe é fundamental para a aplicação das penas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.176 (1)", "page_number": 176, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 29, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:46:53.599432+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=176", "doc_key": "518eb32f9883bf0db2024f3e9ffaa1d0"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f20354c531082cde3b8823ea64491a9906f16668ba4b020d200b4eb0b596b13a'),
  ('cpiuris2025::93d5595faa4a44e8ac843037928f00fc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Responsabilidade Coletiva', '## Responsabilidade Coletiva

A responsabilidade coletiva é um conceito que se aplica quando o sujeito realiza o tipo penal valendo-se de erro, coação ou em contexto de uma organização delitiva. Esta teoria foi criada para lidar com crimes relacionados ao nacional-socialismo e tem sido aplicada no Peru.

### Conceitos
- **Responsabilidade Coletiva**: Conceito que se aplica quando o sujeito realiza o tipo penal valendo-se de erro, coação ou em contexto de uma organização delitiva
- **Erro**: Ouvido ou interpretação incorreta de fatos
- **Coação**: Ato que impede a liberdade de escolha
- **Organização Delitiva**: Grupamento de pessoas unidas para cometer crimes

### Referências legais
- Art. 25 do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre erro e coação
- Identifique os pressupostos da responsabilidade coletiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.176 (2)", "page_number": 176, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T14:47:18.432011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=176", "doc_key": "93d5595faa4a44e8ac843037928f00fc"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '9dd75613127895e55160c81ab6fd4d1cf844191691fc0263103efe35f659ae55'),
  ('cpiuris2025::673047f47f4cbfafc633c663882be685', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de Pessoas', '## Concurso de Pessoas

A teoria geral do crime aborda o concurso de pessoas, onde detentores de poder estatal podem ser responsabilizados por delitos limitados a determinados campos de atividade. A autoria mediata ocorre quando o agente se utiliza de pessoa para executar o fato sem dolo ou de forma não culpável.

### Conceitos
- **Concurso de Pessoas**: Teoria geral do crime que aborda a responsabilidade de detentores de poder estatal por delitos limitados a determinados campos de atividade.
- **Autoria Mediata**: Ocorre quando o agente se utiliza de pessoa para executar o fato sem dolo ou de forma não culpável.

### Referências legais
- Art. 85, § 2º, CP

### Jurisprudência
- RE 123456
- Súmula 343/STF

### Dicas de prova
- Entenda a diferença entre autoria imediata e mediata.
- Conheça as hipóteses de autoria mediata, como o caso do médico que indica a injeção letal para a enfermeira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.177 (1)", "page_number": 177, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 85, § 2º, CP"], "jurisprudence": ["RE 123456", "Súmula 343/STF"], "confidence": 0.8, "extracted_at": "2026-05-27T14:48:00.068584+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=177", "doc_key": "673047f47f4cbfafc633c663882be685"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'dcdd238cbc79359aad54d673e4d6825cfeec20f83f4dbc2252eb6b4c68186e06'),
  ('cpiuris2025::b793a70d418ba5a7e749a5fef128ca8a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Autoria Mediada', '## Autoria Mediada

A autoria mediada ocorre quando um indivíduo emite uma ordem para que outro a cumpra, resultando na morte de uma terceira pessoa. O autor mediato é igualmente culpado do subordinado.

### Conceitos
- **Autoria Mediata**: Ocorre quando um indivíduo emite uma ordem para que outro a cumpra, resultando na morte de uma terceira pessoa.
- **Autor Mediato**: É o indivíduo que emite a ordem para que outro a cumpra
- **Subordinado**: É o indivíduo que recebe a ordem e a cumprir

### Referências legais
- Art. 342, CP

### Dicas de prova
- Entenda a diferença entre autoria mediada e autoria colateral
- Identifique o autor mediato e o subordinado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.177 (2)", "page_number": 177, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 342, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:48:24.451128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=177", "doc_key": "b793a70d418ba5a7e749a5fef128ca8a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '252f08a183e79eb62f3755fd375f05798fefecef597869460493aff2fa5acd39'),
  ('cpiuris2025::d91be200e88095d02ed9a1310fd9ea1c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de Pessoas', '## Concurso de Pessoas

O concurso de pessoas ocorre quando há liame subjetivo entre os autores do crime, mas é difícil identificar a conduta de cada um. Nesse caso, o agente pode contribuir para a ocorrência do resultado sem ser individualizado.

### Conceitos
- **Concurso de Pessoas**: Ocorre quando há liame subjetivo entre os autores do crime
- **Máxima do In Dubio Pro Reo**: Se não se sabe quem foi o autor responsável pelo disparo fatal, ambos deverão responder por tentativa de homicídio

### Referências legais
- Art. 155, § 4º, inciso IV, do CP
- Art. 65, inciso III, do CP

### Dicas de prova
- Pergunte sobre o concurso de pessoas e a máxima do in dubio pro reo
- Entenda que não é necessário individualizar a conduta de cada agente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.178 (1)", "page_number": 178, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 155, § 4º, inciso IV, do CP", "Art. 65, inciso III, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:48:52.210066+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=178", "doc_key": "d91be200e88095d02ed9a1310fd9ea1c"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4fc61dad1d6e93fab4e2b531aff5276abe4edfd1c5d9a610bab38919e0615785'),
  ('cpiuris2025::8c07c9a53361bb2b8f8b836c4e79a477', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Coautoria', '## Coautoria

A coautoria é a prática de uma conduta criminosa por dois ou mais autores ligados subjetivamente, unidos para alcançar o resultado pretendido.

### Conceitos
- **Coautoria parcial**: Cada autor pratica um ato de execução diferente do outro, mas juntos alcançam o resultado pretendido.
- **Coautoria direta**: Todos praticam a mesma conduta

### Referências legais
- Art. 28 do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre coautoria parcial e direta.
- Conheça o exemplo de João e José que colocam a arma na bolsa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.178 (2)", "page_number": 178, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 28 do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T14:49:23.618261+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=178", "doc_key": "8c07c9a53361bb2b8f8b836c4e79a477"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '8d17e1f15aa6cdac01610cd4395f09f4fd1cf36a682d9fd3f81b3c0e47997ad7'),
  ('cpiuris2025::6739dbe0154dbc2ed4b28e863f0d5f5b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Coautoria e Participação', '## Coautoria e Participação

Resumo objetivo: Coautoria e participação são conceitos importantes no Direito Penal. A coautoria ocorre quando dois ou mais indivíduos executam o núcleo do tipo, enquanto a participação ocorre quando um indivíduo contribui para o crime sem executar o núcleo do tipo.

### Conceitos
- **Coautoria**: Execução conjunta do núcleo do tipo pelo mesmo sujeito
- **Participação**: Contribuição para o crime sem executar o núcleo do tipo
- **Instigação**: Alimentar a ideia já existente em alguém para que ele cometa o crime
- **Induzimento**: Fazer nascer o pensamento no agente para que ele cometa o crime
- **Acessoriedade mínima**: Teoria que considera que basta que o autor pratique o fato típico para punir o partícipe
- **Acessoriedade limitada (ou média)**: Teoria que considera que basta que o autor pratique o fato típico e ilícito para punir o partícipe
- **Acessoriedade máxima**: Teoria que considera que é necessário que o autor pratique o fato típico, ilícito e seja culpável para punir o partícipe
- **Hiperacessoriedade**: Teoria que considera que é necessário que o autor pratique o fato típico, ilícito, seja culpável e punível para punir o partícipe

### Referências legais
- Art. 342, CP
- Art. 286, CP

### Dicas de prova
- Entenda a distinção entre coautoria e participação
- Conheça as teorias da punição do partícipe
- Identifique o tipo de participação (moral ou material)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.179", "page_number": 179, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 342, CP", "Art. 286, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:50:13.854731+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=179", "doc_key": "6739dbe0154dbc2ed4b28e863f0d5f5b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ba65c4c95fb3006bc1ef2bb7bca9da454e994f8a60234aa66bdceb731d45f81c'),
  ('cpiuris2025::38ab6dea7439c63bcfc9a0d771a38335', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de Pessoas', '## Concurso de Pessoas

A coautoria é possível em crimes culposos e omissivos, desde que haja vínculo subjetivo entre as pessoas envolvidas. Em crimes culposos, a conduta imprudente ou negligente causa resultado previsível, enquanto em crimes omissivos, a ausência de ação pode ser coautoria se houver vínculo subjetivo e concordância para não agir.

### Conceitos
- **Coautoria**: Participação conjunta de duas ou mais pessoas em um crime
- **Vínculo Subjetivo**: Conexão emocional ou jurídica entre as pessoas envolvidas no crime
- **Conduta Imprudente**: Ação negligente ou imprudente que causa resultado previsível
- **Crime Culposo**: Crime cometido por negligência ou imprudência, causando resultado previsível
- **Crime Omissivo**: Crime cometido pela ausência de ação, em vez de ação
- **Participação**: Involvement direto no crime, não necessariamente com vínculo subjetivo

### Referências legais
- Art. 269, CP
- Súmula 378 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Concurso de Pessoas

### Dicas de prova
- Entenda o conceito de vínculo subjetivo e sua importância na coautoria
- Diferencie entre conduta imprudente e ausência de ação em crimes culposos e omissivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.180 (1)", "page_number": 180, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 269, CP", "Súmula 378 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Concurso de Pessoas"], "confidence": 0.8, "extracted_at": "2026-05-27T14:50:55.146219+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=180", "doc_key": "38ab6dea7439c63bcfc9a0d771a38335"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '1a86f77e791bd8374b89bc87d6a749c020bea92429551f8ad745d2fccca2d3ca'),
  ('cpiuris2025::e5d4c5f3488fcaae601f5565d5689e25', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Causação e Omissão', '## Causação e Omissão

A existência de um crime depende do resultado causado por uma ação ou omissão do agente. A omissão é penalmente relevante quando o omitente devia e podia agir para evitar o resultado.

### Conceitos
- **Causação**: Relação entre a conduta do agente e o resultado
- **Omissão**: Ação ou falta de ação que não produz um resultado
- **Dever de cuidado, proteção ou vigilância**: Obrigação legal de agir para evitar um resultado

### Referências legais
- Art. 13 do CP

### Dicas de prova
- Entenda a noção de causação e sua relação com o resultado
- Conheça as hipóteses de omissão penalmente relevante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.180 (2)", "page_number": 180, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 13 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:51:26.863715+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=180", "doc_key": "e5d4c5f3488fcaae601f5565d5689e25"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '0be91ad9d0a737aee45e0172cfd67d7565561f33aee844eb872ecfe707d1383d'),
  ('cpiuris2025::09b7c88e2aded0636902a3031dbe8b09', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de Pessoas e Comunicabilidade', '## Concurso de Pessoas e Comunicabilidade

O artigo 29, § 2º, do CP estabelece que os agentes podem ter dolos distintos. Para praticar o crime menos grave, deve-se responder por ele caso seja imprevisível o resultado mais grave. Por outro lado, deve-se aplicar a pena do crime que o agente gostaria de ter praticado, aumentada de metade, caso seja previsível o crime mais grave.

### Conceitos
- **Concurso de Pessoas**: A teoria segundo a qual dois ou mais agentes podem ser responsáveis pelo mesmo crime
- **Dolos Distintos**: Diferentes intenções ou motivações dos agentes que praticam o mesmo crime
- **Comunicabilidade**: A regra segundo a qual as circunstâncias e condições de caráter pessoal não se comunicam com as elementares do crime, salvo quando forem elementares
- **Circunstâncias**: Dados acessórios ao crime que dispensam para a configuração da figura penal básica
- **Condições**: Elementos inerentes ao indivíduo que existem independentemente da prática do crime

### Referências legais
- Art. 29, § 2º, do CP

### Dicas de prova
- Entenda a diferença entre dolos distintos e comunicabilidade
- Conheça as regras de comunicação das circunstâncias e condições com as elementares do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.181 (1)", "page_number": 181, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 29, § 2º, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:52:05.139927+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=181", "doc_key": "09b7c88e2aded0636902a3031dbe8b09"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '94d151a9c219eccff88586018a5e33ca83ad8a0247e02469ae319d723efa6f34'),
  ('cpiuris2025::f2b5d664379043148eb35f38285fbf78', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Elementar e Circunstância no Direito Penal', '## Elementar e Circunstância no Direito Penal

Resumo objetivo: Elementar é o tipo penal que constitui o crime, enquanto circunstância é fato que se comunica com os demais agentes. Exemplos de elementares e circunstâncias são dados na parte do texto.

### Conceitos
- **Elementar**: O tipo penal que constitui o crime
- **Circunstância**: Fato que se comunica com os demais agentes

### Referências legais
- Art. 217-A, CP

### Dicas de prova
- Distinção entre elementar e circunstância
- Comunicação de fatos entre agentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.181 (2)", "page_number": 181, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 217-A, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:52:23.823984+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=181", "doc_key": "f2b5d664379043148eb35f38285fbf78"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c6a48a617b02cbf5bd1600da89683bf045e0dcccd7822c71e2f96341e212f019'),
  ('cpiuris2025::28fb112db0808055f3151850adbf3dd0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de Pessoas', '## Concurso de Pessoas

Requisitos necessários para a configuração do concurso de pessoas: pluralidade de agentes, relevância causal, identidade de infração penal e liame subjetivo.

### Conceitos
- **Pluralidade de agentes**: Maior que um agente é necessário para o crime
- **Relevância causal**: A conduta dos participantes deve estar relacionada ao resultado do crime
- **Identidade de infração penal**: O mesmo tipo de crime deve ser cometido por mais de um agente
- **Liame subjetivo**: A intenção ou o objetivo dos participantes devem estar relacionados ao resultado do crime

### Referências legais
- Art. 31 do CP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre vínculo subjetivo e objetivo.
- Não confunda autoria colateral com concurso de pessoas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.182", "page_number": 182, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 31 do CP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.9, "extracted_at": "2026-05-27T14:53:03.633831+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=182", "doc_key": "28fb112db0808055f3151850adbf3dd0"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '729baaf154c3b9a6501430e39c6bfa1561ae8cc8febe24c4c0635c1d4eb86ccb'),
  ('cpiuris2025::f1ce3001e1e26cc03dd92e5fbf80292a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Pena', '## Teoria Geral da Pena

A pena é a sanção penal que restringe ou priva um bem jurídico do agente, responsabilizando-o pelo delito. A pena tem finalidades como retribuição, prevenção geral e especial.

### Conceitos
- **Pena**: Sanção penal que restringe ou priva um bem jurídico do agente
- **Retribuição**: Finalidade da pena de punir o agente pelo delito cometido
- **Prevenção Geral**: Intimidar a sociedade para que evite cometer delitos
- **Prevenção Especial**: Dirigir-se ao criminoso para ressocializá-lo
- **Teoria Agnóstica**: Teoria que questiona a eficácia da pena na ressocialização do condenado

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a teoria agnóstica e sua crítica à ressocialização
- Conheça as finalidades da pena: retribuição, prevenção geral e especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.184", "page_number": 184, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T14:53:38.601988+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=184", "doc_key": "f1ce3001e1e26cc03dd92e5fbf80292a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ba90aa5bcd69375e242771d3590e189d05578bcfaa262a583f77e76039ee9a18'),
  ('cpiuris2025::86e9b8d7c6bdee58d4c3aae3edaa213d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria dialética da pena e teorias retributivas', '## Teoria dialética da pena e teorias retributivas

Discute a teoria dialética da pena, que afirma que a retribuição penal é um fenômeno específico das sociedades capitalistas, e as teorias retributivas, que visam punir o autor de uma infração penal.

### Conceitos
- **Teoria dialética da pena**: afirma que a retribuição penal é um fenômeno específico das sociedades capitalistas
- **Teoria retributiva**: visam punir o autor de uma infração penal e restaurar a ordem jurídica violada
- **Pena retributiva**: representa a forma de punição específica da sociedade capitalista
- **Teoria preventiva geral intimidatória (negativa)**: não é mencionada neste trecho

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre teoria dialética e teoria retributiva
- Conheça as características da pena retributiva em sociedades capitalistas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.185 (1)", "page_number": 185, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:54:10.508963+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=185", "doc_key": "86e9b8d7c6bdee58d4c3aae3edaa213d"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '678900dcc6fdeb07b3f10f01715fe9c6c2caf6923c44b75f7cdb89ad096cb489'),
  ('cpiuris2025::345e71d987f27394714f95fe4aa0e39e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Preventiva', '## Teoria Preventiva

A pena pode ser concebida como forma de intimidação, mas também busca fortalecer a consciência jurídica dos cidadãos e manter a confiança na validade das normas do ordenamento jurídico-penal.

### Conceitos
- **Teoria Preventiva**: teoria que visa prevenir o crime antes de sua comissão
- **Generalidade dos Cidadãos**: aplicação da pena a todos os cidadãos, independentemente de sua conduta
- **Consciência Jurídica**: conhecimento e compreensão das normas do ordenamento jurídico-penal

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre Teoria Preventiva Geral e Especial
- Conheça o conceito de Generalidade dos Cidadãos
- A importância da Consciência Jurídica para a aplicação da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.185 (2)", "page_number": 185, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T14:54:47.040698+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=185", "doc_key": "345e71d987f27394714f95fe4aa0e39e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '8c84810b511af037a1f7043979c835547eb6e6de377a49cb6e55f5dc2d354898'),
  ('cpiuris2025::f93c354b7c2696b91708538a13675bc1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Pena: Conceitos e Fundamentos', '## Teoria Geral da Pena: Conceitos e Fundamentos

A teoria geral da pena tem tríplice finalidade: retributiva, preventiva e reeducativa. A justiça restaurativa busca restaurar a situação anterior ao crime, enquanto os princípios informadores da pena são a legalidade, a personalidade e a individualização.

### Conceitos
- **Teoria Geral da Pena**: Conceito que abrange as três finalidades da pena: retributiva, preventiva e reeducativa.
- **Justiça Restaurativa**: Ideia de restaurar a situação anterior ao crime, recompondo os danos sofridos pela vítima.
- **Princípio da Legalidade**: Não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal.
- **Princípio da Personalidade**: A pena não passará da pessoa do condenado.
- **Princípio da Individualização da Pena**: A lei regulará a individualização da pena, observada em vários momentos: pelo legislador, pelo juiz na dosimetria e pelo juiz na execução da pena.

### Referências legais
- Art. 5º, XLV, CF

### Dicas de prova
- Entenda a tríplice finalidade da pena e os princípios informadores que a regem.
