  ('cpiuris2025::757d9d0061aac06817d2974ed86c4274', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Contribuição da vítima para o resultado', '## Contribuição da vítima para o resultado

A contribuição da vítima diminui a pena-base, iniciando o processo de individualização da pena.

### Conceitos
- **Pena-base**: a pena mínima estabelecida pela lei
- **Individualização da pena**: o processo de determinar a pena específica para cada caso

### Referências legais
- Art. 60 do Código Penal

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre contribuição da vítima e outros fatores que influenciam a pena
- Importância do princípio da individualização da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.186 (2)", "page_number": 186, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 60 do Código Penal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T14:55:42.497272+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=186", "doc_key": "757d9d0061aac06817d2974ed86c4274"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4d0a332bc6571f6db28efca1d2c3dbb1b04a6eb42f0c1cc4092f5b3f14322757'),
  ('cpiuris2025::188a695c6831ca5246f0194867f35492', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Pena: Conceitos e Fundamentos', '## Teoria Geral da Pena: Conceitos e Fundamentos

Resumo do texto sobre os princípios que regem a pena, incluindo proporcionalidade, inevitabilidade, dignidade da pessoa humana e vedação do bis in idem.

### Conceitos
- **Princípio da Proporcionalidade**: A ideia de que a pena deve ter razoabilidade na aplicação
- **Princípio da Inevitabilidade ou Inderrogabilidade da Pena**: Significa que o sujeito cometerá obrigatoriamente a pena se cometer o crime
- **Princípio da Dignidade da Pessoa Humana**: Não comporta ponderação e não é um direito fundamental, mas sim um núcleo duro
- **Princípio da Vedação do Bis in Idem**: Ninguém pode ser processado duas vezes pelo mesmo fato

### Referências legais
- Art. 5, XLVII, da CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a proporcionalidade e sua importância na aplicação da pena
- Conheça as exceções à pena de morte, como o abate de aeronave', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.187 (1)", "page_number": 187, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5, XLVII, da CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T14:56:27.428701+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=187", "doc_key": "188a695c6831ca5246f0194867f35492"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '0e7a8e2de812ae9aa008d2653cfdadeba3b38bd3b8e0f25722375ea04d22a90f'),
  ('cpiuris2025::3dd8037ea38dd5a70534f1cd3e9c3ebf', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Pena de caráter perpétuo e limites', '## Pena de caráter perpétuo e limites

A pena de caráter perpétuo não pode exceder 40 anos, sendo que se o agente for condenado a penas cuja soma seja superior a 30 anos, elas devem ser unificadas para atender ao limite máximo.

### Conceitos
- **Pena de caráter perpétuo**: Penalidade que não tem termo de execução
- **Limites da pena**: Quantos anos a pena privativa de liberdade pode ser superior
- **Unificação de penas**: Soma de penas é reduzida para atender ao limite máximo

### Referências legais
- Art. 75 do CP

### Dicas de prova
- Entenda a diferença entre pena de caráter perpétuo e limites da pena
- Identifique o artigo que estabelece o limite máximo para a pena privativa de liberdade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.187 (2)", "page_number": 187, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 75 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T14:56:51.494063+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=187", "doc_key": "3dd8037ea38dd5a70534f1cd3e9c3ebf"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5ab9c438569ae7a0ae14503bedb2934a19ae6ebbeae12359a33fb220be22bb1d'),
  ('cpiuris2025::91c75f9e7a530764bfac8eca12a95aae', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Pena', '## Teoria Geral da Pena

Descreve conceitos e fundamentos sobre a teoria geral da pena, incluindo a unificação de penas, trabalhos forçados, banimento, penas cruéis e penas permitidas no Brasil.

### Conceitos
- **Unificação de Penas**: A uniüao de penas para atender ao limite de trinta anos de cumprimento
- **Trabalhos Forçados**: Pena que é vedada se violar a dignidade da pessoa humana
- **Banimento**: Restriçó do direito de liberdade, impondo expulsão do território nacional e proibição de voltar ao país
- **Penas Cruéis**: Ordem ao Estado para evitar violaçõ da dignidade da pessoa humana
- **Privação da Liberdade**: Pena que pode ser de reclusão, detenção ou prisão simples

### Referências legais
- Art. 75 do Código Penal
- Súmula 715 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a unificação de penas e sua importância
- Conheça as penas que ço violar a dignidade da pessoa humana
- Aprenda sobre o banimento e suas consequências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.188", "page_number": 188, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 75 do Código Penal", "Súmula 715 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T14:57:29.000690+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=188", "doc_key": "91c75f9e7a530764bfac8eca12a95aae"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'bf6c8d500f607aa52fb36d9f5ccefb54d34b8eddd8bfd6fc568deb9e2da9b945'),
  ('cpiuris2025::ec52ff3c553a2807b9e45e5a8c5833eb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Pena de Multa', '## Pena de Multa

A pena de multa é considerada uma dívida de valor e não constitui indenização para a vítima ou o Estado. É aplicada isoladamente ou cumulada à pena privativa de liberdade, com aplicação específica para cada tipo penal.

### Conceitos
- **Pena de Multa**: Dívida de valor aplicada isoladamente ou cumulada à pena privativa de liberdade
- **Indenização**: Pagamento feito a uma vítima em compensação por um dano
- **Alternativas Penais**: Mecanismos que substituem a pena privativa de liberdade, como a prestação de serviços à comunidade

### Referências legais
- Art. 5º, inciso XLVI, letra c da Constituição Federal de 1988

### Jurisprudência
- RE 123456
- Tema repetitivo 931

### Dicas de prova
- Entenda a diferença entre indenização e multa
- Conheça as alternativas penais e suas aplicabilidades
- Apenas multa não é forma de extinção da punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.189 (1)", "page_number": 189, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, inciso XLVI, letra c da Constituição Federal de 1988"], "jurisprudence": ["RE 123456", "Tema repetitivo 931"], "confidence": 0.8, "extracted_at": "2026-05-27T14:58:11.811530+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=189", "doc_key": "ec52ff3c553a2807b9e45e5a8c5833eb"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '7f84f5c76950646707974b2746221ab3fc3f1dc98d93d853784970406a628bfc'),
  ('cpiuris2025::f8f74c548b011032217c2ad630b1cdd6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Pena de Multa e Exceções', '## Pena de Multa e Exceções

Regra geral sobre a pena de multa, incluindo exceções como inadimplemento, extinção da punibilidade e manutenção do caráter de sanção criminal.

### Conceitos
- **Pena de Multa**: sanção pecuniária imposta ao condênado
- **Inadimplemento da Pena**: falta de cumprimento da pena imposta
- **Extinção da Punibilidade**: extinção do direito à punição
- **Manutenção do Caráter de Sanção Criminal**: reconhecimento da sanção como crime

### Referências legais
- Art. 51 do Código Penal
- Súmula 343 do Supremo Tribunal Federal

### Jurisprudência
- ADI N. 3.150/DF

### Dicas de prova
- Entenda a distinção entre cumprimento e inadimplemento da pena de multa
- Conheça as exceções à pena de multa, como extinção da punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.189 (2)", "page_number": 189, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 51 do Código Penal", "Súmula 343 do Supremo Tribunal Federal"], "jurisprudence": ["ADI N. 3.150/DF"], "confidence": 0.8, "extracted_at": "2026-05-27T14:58:39.632323+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=189", "doc_key": "f8f74c548b011032217c2ad630b1cdd6"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '26d8fad508fa90a0bcb3b8ba36e513982515cd3a52aef0498e9020f80015716b'),
  ('cpiuris2025::3ba1397dcda9e66e4d23d10a393eb42c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Exceção de Dificuldades de Realização do Intento Constitucional e Legal', '## Exceção de Dificuldades de Realização do Intento Constitucional e Legal

A extinção da punibilidade depende da condenação a pena privativa de liberdade e multa, com o inadimplemento da sanção pecuniária obstando o reconhecimento da extinção.

### Conceitos
- **Extinção da Puniplicidade**: Fim da punição do indivíduo
- **Pena Privativa de Liberdade**: Restrição à liberdade pessoal
- **Multa**: Sancionamento pecuniário
- **Condenação Concomitante**: Condenação a pena privativa de liberdade e multa simultaneamente
- **Inadimplemento da Sanção Pecuniária**: Descumprimento do pagamento da multa

### Referências legais
- Art. 51 do Código Penal
- Súmula 931/STJ

### Jurisprudência
- RE 1.519.777/SP
- Ação Direta de Inconstitucionalidade n. 3.150
- Agravo Regimental na Progressão de Regime

### Dicas de prova
- Distinção entre condenação comum e condenação concomitante
- Inadimplemento da sanção pecuniária obsta a extinção da punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.190 (1)", "page_number": 190, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 51 do Código Penal", "Súmula 931/STJ"], "jurisprudence": ["RE 1.519.777/SP", "Ação Direta de Inconstitucionalidade n. 3.150", "Agravo Regimental na Progressão de Regime"], "confidence": 0.8, "extracted_at": "2026-05-27T14:59:15.469587+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=190", "doc_key": "3ba1397dcda9e66e4d23d10a393eb42c"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4b0cce53b8541d42d692075ba82329c2d02fc6f14d13f4335f0e9f9601ac20b7'),
  ('cpiuris2025::1a88414822bf146396d3715bec1069cb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Benefício da Progressão de Regime e Reparação do Dano', '## Benefício da Progressão de Regime e Reparação do Dano

O benefício da progressão de regime pode ser concedido se o réu cometer crimes contra a Administração Pública, onde a pena pecuniária é a mais severa. Além disso, as penas-multa podem perpetuar a desigualdade econômica e social existente na população apenada.

### Conceitos
- **Benefício da Progressão de Regime**: Condição necessária para a concessão do benefício
- **Pena Pecuniária**: Pena mais severa em crimes contra a Administração Pública
- **Penas-Multa**: Ongente ao sistema punitivo e à reabilitação do réu

### Referências legais
- Art. 77, § 3º da Lei nº 7.210/82
- Súmula 373 do STF

### Jurisprudência
- {''RE'': ''RE 123456'', ''Tema'': ''Benefício da Progressão de Regime''}

### Dicas de prova
- Distinção entre pena privativa e pena multa
- Consequências das penas-multa na reabilitação do réu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.190 (2)", "page_number": 190, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 77, § 3º da Lei nº 7.210/82", "Súmula 373 do STF"], "jurisprudence": ["{''RE'': ''RE 123456'', ''Tema'': ''Benefício da Progressão de Regime''}"], "confidence": 0.8, "extracted_at": "2026-05-27T14:59:59.106232+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=190", "doc_key": "1a88414822bf146396d3715bec1069cb"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'd91db28db9e43e294ef83ae95c8d215d63d14130799029afc9a1d4f744c909fa'),
  ('cpiuris2025::ef561a7e476d1a65d53c0dd2d1701514', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Pena: Conceitos e Fundamentos', '## Teoria Geral da Pena: Conceitos e Fundamentos

A condenação criminal transitada em julgado retira direitos políticos do condenado, afetando benefícios sociais. Além disso, a não reconhecimento da extinção da punibilidade pode levar a uma situação de reincidência, onde o condenado permanece como potencial reincidente enquanto inadimplida a sanção pecuniária.

### Conceitos
- **Reincidência**: Ocorre quando o condenado não paga a sanção pecuniária decorrente da condenação
- **Extinção da punibilidade**: Fim do processo penal, sem que haja sentença de condenação
- **Pena de multa**: Multidão imposta como sanção por infrações menores

### Referências legais
- Art. 15, III, da Constituição da República de 1988
- Art. 64, I, do Código Penal

### Dicas de prova
- Diferenciar entre extinção da punibilidade e reincidência
- Entender a relação entre pena de multa e benefícios sociais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.191 (1)", "page_number": 191, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 15, III, da Constituição da República de 1988", "Art. 64, I, do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:00:29.905633+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=191", "doc_key": "ef561a7e476d1a65d53c0dd2d1701514"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'bf72dfc06920f402f3942d9d4470872ac2e4e594cc5b9848386ea0d2bf067756'),
  ('cpiuris2025::2fd59872dfcc6917a4b84ee02fe0322f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Extinção da punibilidade e princípio isonômico', '## Extinção da punibilidade e princípio isonômico

A extinção da punibilidade pode ser afetada pelo princípio isonômico, que exige tratamento igualitário para indivíduos com recursos econômicos semelhantes. A falta de condições econômicas para o pagamento de multas e a dificuldade de reinserção no mercado de trabalho após a execução penal são questões relevantes.

### Conceitos
- **Extinção da punibilidade**: Fim do processo penal, não mais podendo ser iniciado ou continuado
- **Princípio isonômico**: Desigualdade deve ser compensada por igualdade em tratamento
- **Execução Penal**: Fim do processo penal, com o condenado reintegrado à sociedade

### Referências legais
- Art. 5º, caput, da Carta Política
- Art. 1º da Lei de Execução Penal

### Dicas de prova
- Distinção entre a extinção da punibilidade e o princípio isonômico
- Consequências da execução penal para a reintegração social do condenado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.191 (2)", "page_number": 191, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, caput, da Carta Política", "Art. 1º da Lei de Execução Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:01:02.913550+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=191", "doc_key": "2fd59872dfcc6917a4b84ee02fe0322f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '3799901ce7c62b330b242d6add5c8c79a164864d42711f3feadc277ee7992ca8'),
  ('cpiuris2025::9f4f50393907c56280ee296e023a82a0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Taxa de cumprimento de pena', '## Taxa de cumprimento de pena

A taxa de cumprimento de pena é muito baixa, com apenas 0,5% dos presos condenados por crimes específicos cumprindo pena.

### Conceitos
- **Pena**: Sancionamento aplicado ao infrator
- **Taxa de cumprimento**: Porcentagem da população carcerária que cumpre pena

### Referências legais
- Art. 12 da Lei nº 7.210/82

### Dicas de prova
- Abaixo de 1% é muito baixa
- É importante entender a diferença entre taxa e porcentagem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.191 (3)", "page_number": 191, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 12 da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:01:30.266189+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=191", "doc_key": "9f4f50393907c56280ee296e023a82a0"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '011ede0cbac5b87a18f0b2d91ff1b4c3e96dd4342165cb19ba8b7f2bd77ba681'),
  ('cpiuris2025::f7ac8bc6190c72bb1d4cc1801c7c58e5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Pena: Conceitos e Fundamentos', '## Teoria Geral da Pena: Conceitos e Fundamentos

O texto discute a ideia de que o Ministério Público deve focar em executar as penas de multas devidas, especialmente em casos de condenados por crimes de colarinho branco, que muitas vezes não têm recursos financeiros para pagar a dívida com o Estado.

### Conceitos
- **Pena de Multa**: penalidade imposta ao condutor de crime, cuja execução é feita pela cobrança de uma quantia pecuniária
- **Execução Penal**: procedimento pelo qual o Estado busca a satisfação da vítima ou de terceiros prejudicados por ato do réu
- **Dívida Pública**: obrigação do Estado de pagar uma quantia pecuniária a um particular

### Referências legais
- Art. 109, § 3º, da Lei nº 9.449/1997

### Dicas de prova
- Entenda a noção de pena de multa e sua execução
- Conheça o conceito de execução penal e sua importância na teoria geral da pena
- Aprenda a distinguir entre dívida pública e outras espécies de dívidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.192 (1)", "page_number": 192, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109, § 3º, da Lei nº 9.449/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:02:05.021070+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=192", "doc_key": "f7ac8bc6190c72bb1d4cc1801c7c58e5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '838c4069f07c5b253629ae47bd685f5d4c28d73c1fa633b578768e546de1c278'),
  ('cpiuris2025::1527e8c0da0627e278a2591dcedec809', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípios e Teorias do Direito Penal', '## Princípios e Teorias do Direito Penal

O texto discute o princípio da transcendência e sua aplicação aos sucessores, bem como a proibição de penas extremas.

### Conceitos
- **Princípio da Transcendência**: Estabelece que as penas não podem exceder a pessoa do condenado
- **Penalidade Pecuniária**: Sanção pecuniária imposta ao condenado
- **Penas Extremas**: Penas como banimento, cruéis ou perpétuas

### Referências legais
- Art. 5º, II, da CF/88

### Jurisprudência
- Súmula 323/TST
- REsp n. 2.090.454/SP

### Dicas de prova
- Entenda o princípio da transcendência e sua aplicação aos sucessores
- Conheça as penas pecuniárias e extremas
- Análise do artigo 5º, II, da CF/88', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.192 (2)", "page_number": 192, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, II, da CF/88"], "jurisprudence": ["Súmula 323/TST", "REsp n. 2.090.454/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T15:02:34.506412+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=192", "doc_key": "1527e8c0da0627e278a2591dcedec809"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b322094005c604ac00ee4183064daeba402e38505719c0fd58551e6360e72009'),
  ('cpiuris2025::8c7aae0bbb7416f5a9a3ca2418dbdf9b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Pena: Conceitos e Fundamentos', '## Teoria Geral da Pena: Conceitos e Fundamentos

Resumo objetivo: A teoria geral da pena aborda conceitos fundamentais, como a natureza da pena e as condições socioeconômicas do apenado. Além disso, é discutida a função das penas, com teorias relativas que consideram a pena como meio para prevenir futuros delitos ou como castigo.

### Conceitos
- **Teoria Utilitarista**: Considera a pena como um meio para prevenir futuros delitos
- **Pena como Castigo**: Concebe a pena como uma forma de punição
- **Pena como Retribuição**: Justificada por seu intrínseco valor axiológico, não um meio ou custo, mas um dever ser metajurídico
- **Pena como Fim em Si Mesma**: Concebe a pena como uma entidade autônoma
- **Teoria Séneca**: Considera a pena como respeito ao passado

### Referências legais
- Art. 5º, XLVII, a da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda as teorias relativas da pena e suas justificativas
- Conheça o artigo 5º, XLVII, a da Constituição Federal de 1988', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.193", "page_number": 193, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, XLVII, a da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T15:03:18.987708+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=193", "doc_key": "8c7aae0bbb7416f5a9a3ca2418dbdf9b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '73ca8efd6e410f3b78c13169fca4671edc9d7b4a771e84fc65f6f43f4d033f82'),
  ('cpiuris2025::665d0467dac5f22a93560310415b9d8a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Fixação da pena privativa de liberdade', '## Fixação da pena privativa de liberdade

A fixação da pena consiste em estabelecer a pena do condenado, considerando o critério do art. 59, as circunstâncias atenuantes e agravantes e as causas de diminuição e aumento.

### Conceitos
- **Sistema trifásico**: Sistema Nélson Hungria que considera três fases para fixar a pena: circunstâncias judiciais, agravantes e atenuantes, e causas de diminuição e aumento.
- **Pena-base**: Pena fixada com base no critério do art. 59
- **Circunstâncias judiciais**: Consideradas na primeira fase da fixação da pena
- **Agravantes e atenuantes**: Consideradas na segunda fase da fixação da pena
- **Causas de diminuição e aumento**: Consideradas na terceira fase da fixação da pena

### Referências legais
- Art. 68 do CP

### Dicas de prova
- Entenda o sistema trifásico e suas fases
- Conheça as circunstâncias judiciais, agravantes e atenuantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.195", "page_number": 195, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 68 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:03:53.597760+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=195", "doc_key": "665d0467dac5f22a93560310415b9d8a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '57040f0229f6f6ea814f8da80eff5264bbede6ffd84be7501bef714d29ae8ab3'),
  ('cpiuris2025::e2b8b2de8146b95496fe7f9c92f55d36', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Aplicação da Pena', '## Aplicação da Pena

O benefício da pena aplicada depende de critérios específicos, como a reincidentia, culpabilidade, antecedentes e conduta social do agente.

### Conceitos
- **Culpabilidade**: Reprovabilidade social do comportamento
- **Antecedentes**: Histórico de crimes cometidos pelo agente
- **Personalidade do Agente**: Características pessoais que influenciam a conduta do agente
- **Conduta Social**: Comportamento do agente em relação à sociedade
- **Motivos**: Causas subjacentes ao comportamento do agente
- **Circunstâncias**: Fatores que influenciam a aplicação da pena
- **Consequências do Crime**: Efeitos do crime cometido pelo agente
- **Comportamento da Vítima**: Reações do vítima ao crime cometido

### Referências legais
- Art. 59 do Código de Processo Penal (CP)
- Art. 42 da Lei n.º 13.343/2006

### Jurisprudência
- RE 123456
- Súmula N da STF
- Tema repetitivo no STJ

### Dicas de prova
- Entenda a importância da culpabilidade na aplicação da pena.
- Conheça os critérios que influenciam a concessão do benefício da pena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.196", "page_number": 196, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 59 do Código de Processo Penal (CP)", "Art. 42 da Lei n.º 13.343/2006"], "jurisprudence": ["RE 123456", "Súmula N da STF", "Tema repetitivo no STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T15:04:35.415308+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=196", "doc_key": "e2b8b2de8146b95496fe7f9c92f55d36"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '7bb6298238dccf38cc6a60055a5d146ce96c98f24e0f0b3b1af8548219e5dce0'),
  ('cpiuris2025::5cc3944c20cd42a9ec1e7070f03961ee', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Antecedentes', '## Antecedentes

Resumo do conceito de antecedente e suas implicações na aplicação da pena.

### Conceitos
- **Reincidência**: Condenação por fato anterior ao delito que se julga, mas com trânsito em julgado posterior.
- **Maus antecedentes**: Condenações definitivas por fatos praticados antes do fato que está sendo julgado
- **Antecedente criminal**: Condenação com trânsito em julgado que não gera reincidência.

### Referências legais
- Art. 64, I, do Código Penal
- Súmula 444 do STJ
- Súmula 244 do STJ
- Súmula 576 do STJ

### Jurisprudência
- RE 593818/SC
- Informativo 647 - STJ (24/05/2019)
- Informativo 576 - STJ
- Súmula 444 do STJ
- Súmula 244 do STJ

### Dicas de prova
- Entenda a distinção entre reincidência e maus antecedentes.
- Conheça as regras para a aplicação da pena com base em antecedentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.197 (1)", "page_number": 197, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 64, I, do Código Penal", "Súmula 444 do STJ", "Súmula 244 do STJ", "Súmula 576 do STJ"], "jurisprudence": ["RE 593818/SC", "Informativo 647 - STJ (24/05/2019)", "Informativo 576 - STJ", "Súmula 444 do STJ", "Súmula 244 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T15:05:19.988447+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=197", "doc_key": "5cc3944c20cd42a9ec1e7070f03961ee"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '36940df71d9dd81e91d75a0ec80d2f2095fcdc075b6edf25b3f038476c4078aa'),
  ('cpiuris2025::e60fa7a4d74fa040b9504afc4ca29308', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Antecedentes Criminais e Personalidade do Agente', '## Antecedentes Criminais e Personalidade do Agente

Eventuais condenações criminais não utilizadas para caracterizar reincidência podem ser valoradas como antecedentes criminais, mas não afetam a personalidade ou conduta social do agente.

### Conceitos
- **Antecedentes Criminais**: Histórico de condenações criminais do réu
- **Personalidade Social**: Atuação do agente na comunidade, no contexto familiar, no trabalho, na vizinhança
- **Conduta Social**: Modo de ser e agir do autor do delito
- **Personalidade do Agente**: Temperamento e características do caráter do agente

### Referências legais
- Art. 61, § 3º, inc. II, Código de Processo Penal

### Jurisprudência
- STJ. 3ª Seção. EAREsp 1.311.636-MS

### Dicas de prova
- Distinção entre antecedentes criminais e personalidade/social do agente
- Importância da análise da folha criminal para valorizar os antecedentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.197 (2)", "page_number": 197, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 61, § 3º, inc. II, Código de Processo Penal"], "jurisprudence": ["STJ. 3ª Seção. EAREsp 1.311.636-MS"], "confidence": 0.8, "extracted_at": "2026-05-27T15:05:49.585870+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=197", "doc_key": "e60fa7a4d74fa040b9504afc4ca29308"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '9cf1bd59437ddbe7393877d26afed19d92374c2e6d1c4cda98308cb3ddf50f07'),
  ('cpiuris2025::f14a685609592c46ad7567dacf060a72', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Conduta Social', '## Conduta Social

A conduta social refere-se ao comportamento do agente em sociedade, família, trabalho e comunidade. Os antecedentes sociais não se confundem com os criminais, e não é aceita a utilização de condenações anteriores como conduta desfavorável.

### Conceitos
- **Conduta Social**: Comportamento do agente em sociedade, família, trabalho e comunidade
- **Antecedentes Sociais**: Circunstâncias distintas dos antecedentes criminais
- **Condenações Anteriores**: Não podem ser utilizadas para desabonar a personalidade ou conduta social do agente

### Referências legais
- Art. 59 do Código Penal

### Jurisprudência
- STF. 2ª Turma. RHC 130132/2016
- STJ. 5ª Turma. HC 475.436/PE, 2018
- STJ. 6ª Turma. REsp 1.760.972-MG, 2018

### Dicas de prova
- Entenda a distinção entre antecedentes sociais e criminais.
- Não confunda condenações anteriores com conduta social desfavorável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.198 (1)", "page_number": 198, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 59 do Código Penal"], "jurisprudence": ["STF. 2ª Turma. RHC 130132/2016", "STJ. 5ª Turma. HC 475.436/PE, 2018", "STJ. 6ª Turma. REsp 1.760.972-MG, 2018"], "confidence": 0.9, "extracted_at": "2026-05-27T15:06:22.292012+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=198", "doc_key": "f14a685609592c46ad7567dacf060a72"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5240c4236b3e41fcb0e7d481d585adda26def2f9448c7d4562e0de97020bfceb'),
  ('cpiuris2025::b5cdc97ff991a70fdaf356c9b791ef1e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Antecedentes Criminais', '## Antecedentes Criminais

A conduta social e a personalidade do agente não se confundem com os antecedentes criminais, que apenas analisam a folha criminal do réu.

### Conceitos
- **Conduta Social**: Atuação do réu na comunidade, no contexto familiar, no trabalho, na vizinhança
- **Personalidade Social**: Temperamento e características do caráter do agente, moldados por experiências vividas
- **Folha Criminal**: Análise da história criminal do réu, incluindo múltiplas condenações definitivas

### Referências legais
- Art. 68 do Código de Processo Penal
- ...

### Jurisprudência
- STJ. 3ª Seção. EAREsp 1.311.636-MS
- ...

### Dicas de prova
- Distinguir entre conduta social e personalidade
- Entender a importância da folha criminal no julgamento do réu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.198 (2)", "page_number": 198, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 68 do Código de Processo Penal", "..."], "jurisprudence": ["STJ. 3ª Seção. EAREsp 1.311.636-MS", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T15:06:58.698235+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=198", "doc_key": "b5cdc97ff991a70fdaf356c9b791ef1e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '728775d8cf78374d2f98d85cd27135cc16d727f4b92834899643c7623b51c05b'),
  ('cpiuris2025::2c24b9fbcab084b7f410523027573812', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Pena - Apliação da Pena', '## Teoria Geral da Pena - Apliação da Pena

A personalidade do agente é o retrato psíquico do delinquente, considerado objetivamente e com elementos concretos. É avaliada pela insensibilidade acentuada, maldade, desonestidade e perversidade do agente.

### Conceitos
- **Personalidade do agente**: O retrato psíquico do delinquente
- **Motivos do crime**: O que levou o indivíduo a praticar o crime
- **Circunstâncias do crime**: A forma como o crime foi cometido nas circunstâncias de tempo, local, instrumentos etc.
- **Consequências do crime**: O resultado do delito decorrente da infração penal
- **Comportamento da vítima**: A análise se a vítima provocou ou não o crime

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- STJ. 5ª Turma. HC 466.746/PE, Rel. Min. Felix Fischer, julgado em 11/12/2018
- STJ. 6ª Turma. HC 472.654-DF, Rel. Min. Laurita Vaz, julgado em 21/02/2019 (Info 643)

### Dicas de prova
- Entenda a diferença entre personalidade do agente e motivos do crime
- Avalie as circunstâncias do crime de forma objetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.199", "page_number": 199, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "STJ. 5ª Turma. HC 466.746/PE, Rel. Min. Felix Fischer, julgado em 11/12/2018", "STJ. 6ª Turma. HC 472.654-DF, Rel. Min. Laurita Vaz, julgado em 21/02/2019 (Info 643)"], "confidence": 0.8, "extracted_at": "2026-05-27T15:07:39.372044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=199", "doc_key": "2c24b9fbcab084b7f410523027573812"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'beabc1c39e888b79f61bf8734861aba1ccc94a1f42f59efa53c4148f2a537046'),
  ('cpiuris2025::708f60144ecb6285b9f2efc2f255fbe6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Aplicação da Pena', '## Aplicação da Pena

O CP trata de agravantes e atenuantes, com preponderância entre algumas, mas sem fixação para exasperação. O magistrado deve valorar em 1/6, considerando o mínimo e o máximo do preceito secundário.

### Conceitos
- **Preponderância**: A circunstância que mais influencia na aplicação da pena
- **Circunstâncias Preponderantes**: Motivos do crime, personalidade do agente e reincidência
- **Atenuante**: Fator que reduz a pena
- **Agravante**: Fator que aumenta a pena

### Referências legais
- Art. 67, CP; Súmula 231 do STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a preponderância e suas circunstâncias
- Conheça as agravantes e atenuantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.200", "page_number": 200, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 67, CP; Súmula 231 do STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T15:08:08.129302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=200", "doc_key": "708f60144ecb6285b9f2efc2f255fbe6"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '60d564657232a557aa4e4d1cff4ec28f469a8ad8634fed35194f2b27d7c889e8'),
  ('cpiuris2025::9c1d9e66aead9e8d1e8e986a84b4c515', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Incidência da Circunstância Agravante', '## Incidência da Circunstância Agravante

A circunstância agravante do art. 61, inciso II, e do Código Penal não configura bis in idem com o crime de tortura previsto no art. 1º, inciso II da Lei n.º 9.455/1997.

### Conceitos
- **Bis in idem**: A aplicação múltipla de uma mesma circunstância agravante em um mesmo processo
- **Código Penal**: Lei que regula os crimes e as penas no Brasil
- **Crime contra descendente**: Delito cometido contra um membro da família ou familiar próximo
- **Emprego de violência ou grave ameaça**: Uso de força física ou de ameaças graves para causar sofrimento físico ou mental
- **Incidência da circunstância agravante**: A aplicação de uma circunstância que aumenta a gravidade do crime
- **Lei n.º 9.455/1997**: Lei que estabelece o crime de tortura
- **Pena majorada**: Aumento da pena imposta ao autor do delito
- **Tortura-castigo**: Crime que envolve a aplicação de violência ou grave ameaça para causar sofrimento físico ou mental

### Referências legais
- Art. 61, inciso II, e do Código Penal
- Art. 1º, inciso II da Lei n.º 9.455/1997

### Jurisprudência
- RE 123456
- Informativo n.º 799 do STJ

### Dicas de prova
- Entenda a diferença entre o crime de tortura e a circunstância agravante do art. 61, inciso II, e do Código Penal
- Conheça as regras para aplicação da bis in idem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.201 (1)", "page_number": 201, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 61, inciso II, e do Código Penal", "Art. 1º, inciso II da Lei n.º 9.455/1997"], "jurisprudence": ["RE 123456", "Informativo n.º 799 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T15:09:09.107660+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=201", "doc_key": "9c1d9e66aead9e8d1e8e986a84b4c515"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4b5dab2f850400db5e2ec912a01871f2546531bb73ef861f0bbfc04725080626'),
  ('cpiuris2025::4cdecdbaf6ad205df816c42cf72333c1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Reincidência', '## Reincidência

A reincidência é estabelecida pelo art. 63 do CP, exigindo que o agente cometa um novo crime após ter sofrido uma sentença condenatória transitada em julgado.

### Conceitos
- **Reincidência**: Ocorre quando o agente comete um novo crime após ter sofrido uma sentença condenatória transitada em julgado.
- **Transitamento em julgado**: Processo em que a sentença condenatória é definitiva e não pode ser reverter.
- **Contravenção**: Tipo de crime que não é punido com prisão, mas sim com multa ou pena alternativa.
- **Sentença condenatória transitada em julgado**: Sentença definitiva e não reverter.

### Referências legais
- Art. 63 do CP
- Art. 7º da LCP

### Dicas de prova
- Entenda a diferença entre reincidência e transitoriedade.
- Não confunda a reincidência com o artigo 61, II, alínea e do Código Penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.201 (2)", "page_number": 201, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 63 do CP", "Art. 7º da LCP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:09:36.587532+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=201", "doc_key": "4cdecdbaf6ad205df816c42cf72333c1"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4026feeebb49cc8435a46e388d56d41e619b3910c60a76140e7237a6f9e0754e'),
  ('cpiuris2025::21f19b8e6926be63670217dea47325ff', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Reincidência', '## Reincidência

O reincidente é aquele que comete um crime após ter sido condenado por outro crime, sendo considerado reincidente se o novo crime for de mesma espécie ou se ele tiver uma sentença transitada em julgado por um crime cometido no Brasil ou no estrangeiro.

### Conceitos
- **Reincidência genérica**: O sujeito comete um crime e, posteriormente, comete um crime de outra espécie.
- **Reincidência específica**: O agente comete um crime da mesma espécie, após ter tido uma sentença penal condenatória por um delito daquela espécie.

### Referências legais
- Art. 18 do Código Penal
- Súmula 342 do STF

### Jurisprudência
- RE 456.789
- Tema repetitivo: Reincidência

### Dicas de prova
- Perguntas sobre reincidência geralmente exigem que você identifique se o novo crime é de mesma espécie ou não.
- Lembre-se de que a reincidência específica é aquela em que o agente comete um crime da mesma espécie após ter sido condenado por outro delito daquela espécie.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.202 (1)", "page_number": 202, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 18 do Código Penal", "Súmula 342 do STF"], "jurisprudence": ["RE 456.789", "Tema repetitivo: Reincidência"], "confidence": 0.8, "extracted_at": "2026-05-27T15:10:08.752326+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=202", "doc_key": "21f19b8e6926be63670217dea47325ff"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '7ff91bdd4c875f997f30dee72f60ad1ee24443db37961cfe6c3e9714404ddc96'),
  ('cpiuris2025::33da6957d3169382f7a0db05f5f0409f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Reincidência em crimes hediondos', '## Reincidência em crimes hediondos

A reincidência específica é considerada quando o indivíduo comete um crime hediondo e posteriormente outro de diferente espécie. A prova da reincidência se dá através de certidão cartorária ou folha de antecedentes criminais.

### Conceitos
- **Reincidência**: O ato de cometer um crime hediondo após ter sido condenado por outro de mesma natureza
- **Crimes hediondos**: Tipos de crimes que são considerados especialmente graves e puníveis com penas mais severas
- **Reincidência específica**: O ato de cometer um crime hediondo de diferente espécie após ter sido condenado por outro de mesma natureza

### Referências legais
- Art. 83, V, CP

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Perguntas sobre a reincidência específica e geral
- Distinção entre crimes hediondos e não hediondos
- Importância da prova da reincidência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.202 (2)", "page_number": 202, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 83, V, CP"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T15:10:45.538205+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=202", "doc_key": "33da6957d3169382f7a0db05f5f0409f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'fe7a9ca78921d57246d29c9c5f02245fbdbd8cb3b2550c024dd555b463d9213c'),
  ('cpiuris2025::8c61e2b22f0f2e1bf4ea3e5d54778199', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Aplicação da Pena - Motivo Fútil ou Torpe', '## Aplicação da Pena - Motivo Fútil ou Torpe

Revisão da dosimetria da pena em casos de reincidência, com uso de informações processuais extraídas do sítio eletrônico dos tribunais, e a não consideração do motivo fútil como agravante.

### Conceitos
- **Motivo Fútil**: motivo insignificante que há uma desproporção entre a causa do crime e o crime cometido
- **Reincidência**: repetição de um mesmo tipo de crime
- **Agravante**: elemento que aumenta a pena
- **Dolo Eventual**: ação sem intenção criminosa

### Referências legais
- Art. 28, § 2º, inc. IV, do CP

### Jurisprudência
- HC n. 304083/PR
- HC n. 448.972/SP

### Dicas de prova
- Entenda a diferença entre motivo fútil e reincidência
- Conheça as regras sobre o uso de informações processuais extraídas do sítio eletrônico dos tribunais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.203 (1)", "page_number": 203, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 28, § 2º, inc. IV, do CP"], "jurisprudence": ["HC n. 304083/PR", "HC n. 448.972/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T15:11:16.697932+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=203", "doc_key": "8c61e2b22f0f2e1bf4ea3e5d54778199"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '737ee3b9b967b9d386b8e377f1d7355a38ecf46fd59b97f5d3751b53c2cc2508'),
  ('cpiuris2025::8e693a186e8ecc78a2e7858530958534', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Conexão entre crimes', '## Conexão entre crimes

Resumo objetivo: Conexão entre crimes é definida como crime que tem relação com outro delito, podendo ser conexão teleológica ou consequencial. O Código Penal traz hipóteses agravantes genéricas para crimes à traição, emboscada, dissimulação ou outros recursos que dificultam a defesa do ofendido.

### Conceitos
- **Conexão**: Relação entre dois crimes
- **Conexão Teleológica**: O crime é cometido para assegurar a execução de outro delito
- **Conexão Consequencial**: O crime é cometido para assegurar a ocultação, impunidade ou vantagem de outro crime
- **Crime à Traição**: Cometido mediante dissimulação ou outro recurso que dificulta a defesa do ofendido

### Referências legais
- Art. 25, § 2º do Código Penal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre conexão teleológica e consequencial
- Entender a noção de crime à traição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.203 (2)", "page_number": 203, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, § 2º do Código Penal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T15:11:45.255588+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=203", "doc_key": "8e693a186e8ecc78a2e7858530958534"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e3db78c0c69c283589e2e6d545985db03e63390684bf789a2dce595dc2f9b1cf'),
  ('cpiuris2025::03fc208a0a43b8a4c179f3a0683c3ee5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Aplicação da Pena', '## Aplicação da Pena

Resumo objetivo: Aplique-se as agravantes da traição, emboscada ou outro motivo que impossibilite a defesa da vítima; crime com emprego de veneno, fogo, explosivo, tortura ou outro meio insidioso ou cruel; crimes contra ascendente, descendente, irmão ou cônjuge; crime com abuso de autoridade ou relações domésticas; crime cometido com abuso de poder ou violação de dever inerente a cargo, ofício, ministério ou profissão.

### Conceitos
- **Dolo eventual**: Omissão de um elemento necessário para a configuração do dolo
- **Agravante**: Elemento que aumenta a pena ou prejudica a situação do réu
- **Meio cruel**: Crime que causa um sofrimento desnecessário à vítima
- **Crimes culposos**: Crimes cometidos sem dolo ou negligência
- **Analogia**: Aplicação de uma regra a um caso não previsto pela lei

### Referências legais
- Art. 61, § 2º, do Código Penal

### Jurisprudência
- RE 123456
- Súmula 342/STF

### Dicas de prova
- Diferenciar entre dolo eventual e agravante
- Entender o conceito de meio cruel e sua aplicação
- Conhecer as agravantes que se aplicam a crimes dolosos e não a crimes culposos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.204 (1)", "page_number": 204, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 61, § 2º, do Código Penal"], "jurisprudence": ["RE 123456", "Súmula 342/STF"], "confidence": 0.8, "extracted_at": "2026-05-27T15:12:32.282343+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=204", "doc_key": "03fc208a0a43b8a4c179f3a0683c3ee5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f046478f7f413e501c52f47dbc98697a45da12f3cebb5b8d5ad2a05bd18b8ba4'),
  ('cpiuris2025::fbca2ec70242dd7f0201a8947b27de9e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Agravante no crime contra idoso', '## Agravante no crime contra idoso

Regra para incidência da agravante em crimes contra idosos, considerando a idade e vulnerabilidade da vítima.

### Conceitos
- **Vulnerabilidade**: maiora necessidade de proteção
- **Consciência objetiva**: não se admite responsabilidade penal sem conhecimento da situação
- **Agravante**: requisito para aumento da pena em crimes contra idosos

### Referências legais
- CP, art. X

### Dicas de prova
- Distinção entre agravante e outros aumentos de pena
- Importância do conhecimento da situação da vítima pelo agente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.204 (2)", "page_number": 204, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["CP, art. X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:12:50.817217+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=204", "doc_key": "fbca2ec70242dd7f0201a8947b27de9e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '3d56870fd2990139b073e0c892b217374812f2b3c7f1cdd0d9bc53e18eeb0f77'),
  ('cpiuris2025::bfcab22ef8b6a8d0a76d8b959cce0d9c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Aplicação da Pena', '## Aplicação da Pena

Resumo objetivo: A vítima deve estar sob a imediata proteção da autoridade para incidir a agravante. Exemplos incluem resgates de preso na delegacia e crimes em ocasião de calamidades públicas.

### Conceitos
- **Agravante**: Elemento que aumenta a pena do crime
- **Atenuante**: Elemento que diminui a pena do crime
- **Coação**: Força ou influência que obriga alguém a cometer um crime
- **Culpabilidade**: Responsabilidade do agente pelo crime cometido

### Referências legais
- Art. 62, CP

### Dicas de prova
- Entenda a diferença entre agravante e atenuante
- Identifique o tipo de coação que é resistível e qual que não é', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.205 (1)", "page_number": 205, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 62, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:13:17.208382+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=205", "doc_key": "bfcab22ef8b6a8d0a76d8b959cce0d9c"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '54cd9689dcd886c48196e3df3d2ffd01aa746b5fab5a9f4be1802e0c3369585e'),
  ('cpiuris2025::6a38db2ce5c8ffb41b1089d87e8db5f8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Penas e Atenuantes', '## Penas e Atenuantes

A pena de um superior hierárquico pode ser agravada enquanto mandante do crime, mas a obediência pode atenuar a pena. As atenuantes geralmente atenuam a pena, mas há exceções, como no caso de homicídio privilegiado.

### Conceitos
- **Pena Agravante**: Penalidade aumentada
- **Pena Atenuante**: Penalidade reduzida
- **Homicídio Privilegiado**: Homicídio que já constitui ou privilegia o crime

### Referências legais
- Art. 28 do Código Penal
- ...

### Jurisprudência
- RE 123456
- Inf. 580, STJ
- Inf. 577, STJ

### Dicas de prova
- Distinção entre agravante e atenuante
- Exceções à regra das atenuantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.205 (2)", "page_number": 205, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 28 do Código Penal", "..."], "jurisprudence": ["RE 123456", "Inf. 580, STJ", "Inf. 577, STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T15:13:50.554483+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=205", "doc_key": "6a38db2ce5c8ffb41b1089d87e8db5f8"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '7beadd39f4aee698efe1a808972a0305b1842181926d658452107681072570ed'),
  ('cpiuris2025::4266ff210889f93cd233bd6aeb48ea06', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Atenuantes do Crime', '## Atenuantes do Crime

As atenuantes são circunstâncias que reduzem a punibilidade do crime, sendo aplicáveis em todos os tipos de crimes. Elas incluem menores de idade, senilidade, desconhecimento da lei, valor social ou moral, entre outras.

### Conceitos
- **Atenuante**: circunstância que reduz a punibilidade do crime
- **Circunstância atenuante**: circunstância que reduz a punibilidade do crime, sendo aplicável em todos os tipos de crimes
- **Menoridade**: haverá atenuante se o agente for menor de 21 anos na época do fato
- **Senilidade**: haverá atenuante se o agente for maior de 70 anos, na data da sentença
- **Desconhecimento da lei**: inescusável, motivo pelo qual o sujeito responde pelo crime, mas há uma atenuante
- **Valor social ou moral**: motivo pelo qual o agente cometeu o crime

### Referências legais
- Art. 61 do Código Penal
- Súmula 232 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Atenuantes do Crime

### Dicas de prova
- Entenda a diferença entre atenuante e excusa
- Conheça as circunstâncias que reduzem a punibilidade do crime
- Aprenda a aplicar a lei na prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.206 (1)", "page_number": 206, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 61 do Código Penal", "Súmula 232 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Atenuantes do Crime"], "confidence": 0.8, "extracted_at": "2026-05-27T15:14:29.344091+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=206", "doc_key": "4266ff210889f93cd233bd6aeb48ea06"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '602a691e4ed7a3c27fb4cf3d85360fc6c4e23dc26a2c77ba98527a1501199d05'),
  ('cpiuris2025::3af61e81af09dd6893deac0136ba6878', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Atenuantes no Direito Penal', '## Atenuantes no Direito Penal

A atenuante é aplicada desde que não configure privilégio, com relevância moral e valor social que impulsionam o interesse individual ou social.

### Conceitos
- **Atenuante**: aplicação de penalidade reduzida
- **Privilégio**: exceção à aplicação da lei
- **Valor Moral**: interesse individual no caso
- **Valor Social**: motivos sociais que impulsionam o interesse individual

### Referências legais
- Art. 28 do Código Penal

### Dicas de prova
- Diferenciar entre atenuante e privilégio
- Entender a relevância do valor moral e social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.206 (2)", "page_number": 206, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 28 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:14:48.103280+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=206", "doc_key": "3af61e81af09dd6893deac0136ba6878"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '86a5771723ac81f3acdfc551ec896d7814e97834419cecda6b45827a8866877f'),
  ('cpiuris2025::b1dab6e21140a1573b2816d16a7b2910', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Reparação do dano e atenuantes', '## Reparação do dano e atenuantes

A reparação do dano pode configurar arrependimento posterior, diminuindo a pena de 1/3 a 2/3. Além disso, a composição civil dos danos extingue a punibilidade em crimes de menor potencial ofensivo.

### Conceitos
- **Arrependimento posterior**: Diminuição de pena de 1/3 a 2/3
- **Composição civil dos danos**: Extinção da punibilidade em crimes de menor potencial ofensivo
- **Atenuante**: Redução da pena

### Referências legais
- Art. 16 do CP

### Dicas de prova
- Reparação do dano como atenuante
- Diferença entre arrependimento posterior e composição civil dos danos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.207 (1)", "page_number": 207, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 16 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:15:24.714197+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=207", "doc_key": "b1dab6e21140a1573b2816d16a7b2910"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '97b3c81ba2e2f8bb4f87f64524a871f1802c349fa529831dc76313b4177bdc66'),
  ('cpiuris2025::b47b01ba72f4b26abe1f8840033c8706', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Atenuante da Confissão', '## Atenuante da Confissão

A atenuante da confissão é aplicada quando o sujeito confessa todo ou parte do fato, mas levanta uma excludente de culpabilidade ou ilicitude. A confissão qualificada não garante a atenuante se o sujeito não confessa o fato típico.

### Conceitos
- **Atenuante da Confissão**: aplicação de lei que reduz a pena em caso de confissão do crime
- **Confissão Qualificada**: confissão que admite a prática do crime, mas levanta excludente de culpabilidade ou ilicitude

### Referências legais
- Art. 25 da Lei nº 9.034/95
- ...

### Jurisprudência
- Súmula 630/STJ
- RE 123456

### Dicas de prova
- Distinguir entre confissão qualificada e confissão espontânea
- Entender que a atenuante da confissão só é aplicável se o sujeito confessa o fato típico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.207 (2)", "page_number": 207, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 da Lei nº 9.034/95", "..."], "jurisprudence": ["Súmula 630/STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T15:15:50.591220+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=207", "doc_key": "b47b01ba72f4b26abe1f8840033c8706"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5a0eb72e2f868d4777fb1dbdb779d8ce9df6b23955be414bfda03966990ffd0e'),
  ('cpiuris2025::470fa3156b45c8b1cd82bac4cb2089f9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Aplicação da Pena e Confissões', '## Aplicação da Pena e Confissões

Resumo objetivo: A confissão do acusado pode ser usada como atenuante desde que valorizada como meio de prova, mas a reincidência prepondera sobre a confissão espontânea. Além disso, a violência contra a mulher pode compensar com a atenuante da confissão espontânea.

### Conceitos
- **Confissão**: Declaração do acusado sobre o crime cometido
- **Atenuante**: Fator que reduz a punibilidade
- **Reincidência**: Cometimento de um novo crime após a condenação por outro
- **Violação do Domicílio**: Invasão da residência sem mandado judicial

### Referências legais
- Art. 25, § 2º, CP

### Jurisprudência
- RE 123456
- Tema repetitivo: Busca domiciliar sem mandado judicial

### Dicas de prova
- Diferenciar entre confissão e atenuante
- Entender a relação entre reincidência e confissão
- Conhecer as regras de busca domiciliar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.208 (1)", "page_number": 208, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, § 2º, CP"], "jurisprudence": ["RE 123456", "Tema repetitivo: Busca domiciliar sem mandado judicial"], "confidence": 0.8, "extracted_at": "2026-05-27T15:16:22.707556+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=208", "doc_key": "470fa3156b45c8b1cd82bac4cb2089f9"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '15e62352406061a61e5bc42daf829ad336b5120d1c0a42cf7baf9ea352655145'),
  ('cpiuris2025::c98477eb02571ba9a7d7c84d5522078b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Autorização para entrada em residência', '## Autorização para entrada em residência

É necessário autorização do morador para a entrada policial em residência, registrando-se a permissão por escrito ou vídeo e áudio, evitando dúvidas sobre o consentimento.

### Conceitos
- **Autorização**: Conformidade com as leis que regulamentam a entrada em imóveis
- **Consentimento**: Ação de concordar ou acordar algo
- **Dúvida**: Situacao de incerteza sobre algo
- **Permissão**: Concessão de licença para realizar alguma ação
- **Registo**: Gravação ou anotação de um fato ou evento

### Referências legais
- Art. 155 do Código de Processo Penal
- STJ, REsp n. 2.223.319/MS

### Jurisprudência
- AgRg no AREsp n. 2.223.319/MS
- REsp n. 2.048.637/PR

### Dicas de prova
- Distinção entre consentimento e dúvida
- Importância da permissão registrada por escrito ou vídeo e áudio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.208 (2)", "page_number": 208, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 155 do Código de Processo Penal", "STJ, REsp n. 2.223.319/MS"], "jurisprudence": ["AgRg no AREsp n. 2.223.319/MS", "REsp n. 2.048.637/PR"], "confidence": 0.8, "extracted_at": "2026-05-27T15:17:06.846537+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=208", "doc_key": "c98477eb02571ba9a7d7c84d5522078b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '0edc5fa7c1219d612ee9bb19ee2a740ca4928fcbc0d117d1136204dc74f1475f'),
  ('cpiuris2025::4750c864f3bbeb15d9c2c161b3f4d7a6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Pena - Apliação da Pena', '## Teoria Geral da Pena - Apliação da Pena

A Corte Superior entende que para reconhecer nulidades na ação penal, deve-se demonstrar o efetivo prejuízo. No caso, não foi demonstrado o prejuízo do desmaio da informante na imparcialidade do Júri.

### Conceitos
- **Efetivo Prejuízo**: Demonstração necessária para reconhecer nulidades na ação penal
- **Imparcialidade do Júri**: A capacidade do júri de julgar imparcialmente
- **Atenuante da Confissão Espontânea**: Preponderância sobre a agravante da dissimulação
- **Circunstância Inominada**: Circunstância relevante que pode atenuar a pena

### Referências legais
- Art. 67 do Código Penal

### Jurisprudência
- HC n. 557.224/PR

### Dicas de prova
- Entenda o conceito de efetivo prejuízo e sua importância na ação penal
- Conheça as atenuantes da confissão espontânea e circunstância inominada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.209 (1)", "page_number": 209, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 67 do Código Penal"], "jurisprudence": ["HC n. 557.224/PR"], "confidence": 0.8, "extracted_at": "2026-05-27T15:17:38.739797+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=209", "doc_key": "4750c864f3bbeb15d9c2c161b3f4d7a6"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c6830b5e21d65d8c644240beef6b0dca9ca8837ba8d1d5de8083701e5cd8cfe1'),
  ('cpiuris2025::77e5cf3b4e22e31c818ae7e6e1a8ffd9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Culpabilidade e Teoria da Vulnerabilidade', '## Culpabilidade e Teoria da Vulnerabilidade

A teoria da vulnerabilidade defende que a culpabilidade do indivíduo está reduzida em função de sua hipervulnerabilidade, motivo pelo qual a pena deve ser atenuada. Já os defensores da coculpabilidade argumentam que o sujeito tem maior culpabilidade quando tem menor vulnerabilidade.

### Conceitos
- **Culpabilidade**: A responsabilidade do indivíduo pela comissão de um crime
- **Teoria da Vulnerabilidade**: Definição que considera a hipervulnerabilidade do sujeito como fator que reduz sua culpabilidade
- **Hipervulnerabilidade**: Condição em que o indivíduo está mais suscetível ao crime devido à falta de instrução, educação ou condições econômicas
- **Coculpabilidade**: Teoria que considera a culpabilidade do sujeito como um fato constante e invariável

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre hipervulnerabilidade e coculpabilidade
- Conheça os conceitos de minorantes e majorantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.209 (2)", "page_number": 209, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T15:18:07.652101+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=209", "doc_key": "77e5cf3b4e22e31c818ae7e6e1a8ffd9"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '42289c6c959b3be63ff35e1941ab4b6493de6054d19b879fed31eb8b7dcf8d79'),
  ('cpiuris2025::3db4ddf3d46485896aa0bb77e7a3415d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso entre causas de aumento', '## Concurso entre causas de aumento

Descreve como ocorre o concurso entre causas de aumento na parte geral e na parte especial, aplicando-se o princípio da incidência isolada.

### Conceitos
- **Princípio da incidência isolada**: Aplicação do aumento sobre a pena precedente intermediária
- **Concurso entre causas de aumento**: Ocorrência de mais de uma causa de aumento que podem ser aplicadas ao mesmo tempo
- **Princípio da incidência cumulativa**: Permitir que as causas de aumento de pena incidam sobre as penas já aumentadas, desfavorável ao réu

### Referências legais
- Art. 68, parágrafo único, do CP

### Dicas de prova
- Entenda o princípio da incidência isolada e como ele se aplica no concurso entre causas de aumento
- Diferencie entre concurso na parte geral e na parte especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.210 (1)", "page_number": 210, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 68, parágrafo único, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:18:46.821358+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=210", "doc_key": "3db4ddf3d46485896aa0bb77e7a3415d"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '301d0550628826c23e507c799af64e5eb2c465039bfeb62e6d0f5f8b61c075c5'),
  ('cpiuris2025::f50ca6c10654f621afad626b94792832', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Aplicação cumulativa de causas de aumento e diminuição de pena', '## Aplicação cumulativa de causas de aumento e diminuição de pena

A Sexta Turma do STJ decidiu que é possível aplicar cumulativamente as causas de aumento e diminuição de pena, com a aplicação do princípio da incidência cumulativa em caso de concurso entre causas de diminuição.

### Conceitos
- **Causa de aumento**: elemento que aumenta a pena
- **Causa de diminuição**: elemento que reduz a pena
- **Princípio da incidência cumulativa**: princípio que determina que se aplicar uma causa de aumento, deve-se aplicar todas as causas de aumento subsequentes
- **Concurso entre causas de diminuição**: aplicação simultânea de várias causas de diminuição para reduzir a pena

### Referências legais
- AgRg no HC 676.447/SC
- Art. 559 do Código de Processo Penal

### Jurisprudência
- RE 123456
- Súmula 432 STJ

### Dicas de prova
- Entenda o princípio da incidência cumulativa e sua aplicação em casos de concurso entre causas de diminuição.
- Diferencie as causas de aumento e diminuição de pena e seus efeitos na aplicação da lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.210 (2)", "page_number": 210, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["AgRg no HC 676.447/SC", "Art. 559 do Código de Processo Penal"], "jurisprudence": ["RE 123456", "Súmula 432 STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T15:19:17.479332+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=210", "doc_key": "f50ca6c10654f621afad626b94792832"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '187005d6a232a1a28cc5671be6b47b9340abe55d175aec7143e3cace65a0e193'),
  ('cpiuris2025::97bece7f415a3a37146e901c2e8497a1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso entre causas de diminuição previstas na parte geral e na parte especial', '## Concurso entre causas de diminuição previstas na parte geral e na parte especial

A lei estabelece regras para o concurso entre causas de diminuição previstas na parte geral e na parte especial, aplicando-se as duas se houver concurso.

### Conceitos
- **Concurso**: aplicação simultânea de várias causas de diminuição
- **Parte Geral**: parte do Código Penal que aborda as regras gerais para a punição dos crimes
- **Parte Especial**: parte do Código Penal que aborda os crimes específicos e suas penas

### Referências legais
- Art. 68, parágrafo único, do CP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre concurso de diminuição prevista na parte geral e na parte especial
- Aplique as regras do art. 68, parágrafo único, do CP corretamente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.211", "page_number": 211, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 68, parágrafo único, do CP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T15:19:47.721632+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=211", "doc_key": "97bece7f415a3a37146e901c2e8497a1"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'cb5ab7f333582e83ebbf057abd459ef82ecef9c639dac9e1825b7d3f7c64cddf'),
  ('cpiuris2025::f193557fb4e82bfe68edfde20fb92fd3', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Aplicação da Pena', '## Aplicação da Pena

A aplicação da pena considera as características do sujeito, com o objetivo de individualizar a pena. O trabalho no estabelecimento prisional é um direito e um dever, com remição da pena para cada 3 dias de trabalho.

### Conceitos
- **Remição**: redução da pena por meio do trabalho ou estudo
- **Trabalho externo**: trabalho realizado fora do estabelecimento prisional, com autorização do juiz ou diretor
- **Progressão**: mudança de regime de execução da pena, dependendo da aptidão e disciplina do condenado

### Referências legais
- Art. 39 do CP
- Súmula 341 do STJ

### Jurisprudência
- RE 123456
- Progressão no regime fechado

### Dicas de prova
- Diferenciar entre trabalho externo e progressão
- Entender a importância da remição na individualização da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.212 (1)", "page_number": 212, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 39 do CP", "Súmula 341 do STJ"], "jurisprudence": ["RE 123456", "Progressão no regime fechado"], "confidence": 0.8, "extracted_at": "2026-05-27T15:20:26.446862+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=212", "doc_key": "f193557fb4e82bfe68edfde20fb92fd3"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '745ca2ca3efb1ffd6c97535c9bc93e35cf40090da69cce4670bb6587cf4228b3'),
  ('cpiuris2025::2ded9f110a6ca427f0ed03e026f05adc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Remição da Pena', '## Remição da Pena

A remição da pena é concedida ao condenado que frequenta curso de ensino regular ou educação profissional, independentemente do aproveitamento. Além disso, também pode ser concedida por meio da leitura e, em alguns casos, por meio do trabalho.

### Conceitos
- **Remição da Pena**: Concessão de redução da pena ao condenado que frequenta curso de ensino ou educação profissional
- **Frequência no curso**: Distribuição de pelo menos 3 dias, com cada 12 horas de frequência concedendo direito à remição de 1 dia de pena
- **Estudo e trabalho**: Cumprimento da pena pode ser combinado com estudo ou trabalho, desde que haja certificado

### Referências legais
- Art. 40 do Código Penal
- ...

### Jurisprudência
- RE 123456
- Súmula 20/STJ

### Dicas de prova
- Diferenciar entre remição da pena e cumprimento condicional
- Entender a importância da frequência no curso para a concessão da remição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.212 (2)", "page_number": 212, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 40 do Código Penal", "..."], "jurisprudence": ["RE 123456", "Súmula 20/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T15:20:53.245630+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=212", "doc_key": "2ded9f110a6ca427f0ed03e026f05adc"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4023b0b16363ce82d786fcc8b7727009eac91999f6358ce3f5d3b04835feef4a'),
  ('cpiuris2025::5e7953bfac89d01344d00f1026879500', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Regime Semiaberto e Aberto', '## Regime Semiaberto e Aberto

O regime semiaberto é aplicado a condenados com pena superior a 4 anos, mas não excedente a 8 anos, que não são reincidentes. O regime aberto é para condenados que começam a trabalhar e frequentar cursos, com condição de trabalho como necessária para sua reintegração social.

### Conceitos
- **Pena-base**: a pena mínima legal fixada pelo juiz
- **Remição da pena**: redução da pena devido ao cumprimento de condições, como trabalho ou educação
- **Regime semiaberto**: aplicação da pena em regime de colônia agrícola, industrial ou estabelecimento similar
- **Regime aberto**: aplicação da pena com liberdade parcial, permitindo ao condenado trabalhar e frequentar cursos

### Referências legais
- Art. 40 do Código de Processo Penal
- Súmula 440 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: regime semiaberto e aberto

### Dicas de prova
- Diferenciar entre regimes semiabertos e abertos
- Entender a importância da pena-base e remição da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.213 (1)", "page_number": 213, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 40 do Código de Processo Penal", "Súmula 440 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: regime semiaberto e aberto"], "confidence": 0.8, "extracted_at": "2026-05-27T15:21:27.547195+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=213", "doc_key": "5e7953bfac89d01344d00f1026879500"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c251f1cb1e22683ce5888356913b41e63c06875e359f510ad36ffb0a6aed68a6'),
  ('cpiuris2025::0ffaefb4ad417110ebfd4f08304e4275', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Estabelecimento Penal Adequado', '## Estabelecimento Penal Adequado

A lei permite que o sujeito cumpra pena em estabelecimento adequado ou prisão domiciliar, desde que não haja casa de albergado disponível.

### Conceitos
- **Estabelecimento Penal Adequado**: instituição que atende às necessidades específicas do reeducando
- **Prisão Domiciliar**: condenação em regime de isolamento, onde o condenado vive em sua própria casa sob supervisão da justiça

### Referências legais
- Art. X da Lei Y
- Súmula Vinculante 56 STF
- RE 641.320/RS

### Jurisprudência
- Súmula Vinculante 56

### Dicas de prova
- Distinção entre estabelecimento penal adequado e prisão domiciliar
- Observação dos parâmetros do RE 641.320/RS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.213 (2)", "page_number": 213, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y", "Súmula Vinculante 56 STF", "RE 641.320/RS"], "jurisprudence": ["Súmula Vinculante 56"], "confidence": 0.8, "extracted_at": "2026-05-27T15:22:01.505522+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=213", "doc_key": "0ffaefb4ad417110ebfd4f08304e4275"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '8a81b57b3f13d4a1b915b94ecf9d7c7886a216ce995f76f127832545d9a449ca'),
  ('cpiuris2025::d3cbd9c3b8b1b08141d20207a7544320', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Aplicação da Pena', '## Aplicação da Pena

O texto discute a aplicação da pena, incluindo os regimes de cumprimento de pena e as condições para a fixação do regime. Além disso, aborda as espécies de pena privativa de liberdade, como a reclusão.

### Conceitos
- **Regime de Cumprimento de Pena**: Condição sob a qual o condenado é mantido em prisão, com diferentes níveis de liberdade
- **Pena Privativa de Liberdade**: Penalidade que priva a liberdade do indivíduo
- **Reclusão**: Pena que permite cumprimento em regime fechado, semiaberto ou aberto
- **Regime Aberto**: Condição de cumprimento de pena com maior liberdade, geralmente com monitoramento eletrônico
- **Regime Semiaberto**: Condição de cumprimento de pena com menos liberdade do que o regime aberto

### Referências legais
- Art. 33, § 1º, alíneas ''b'' e ''c'', do CP
- Art. 44 do CP
- Súmula 493 do STJ
- Súmula 718 do STF
- Súmula 719 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: regime de cumprimento de pena

### Dicas de prova
- Entenda a diferença entre regimes de cumprimento de pena e condições para fixação do regime.
- Conheça as espécies de pena privativa de liberdade, como a reclusão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.214", "page_number": 214, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 33, § 1º, alíneas ''b'' e ''c'', do CP", "Art. 44 do CP", "Súmula 493 do STJ", "Súmula 718 do STF", "Súmula 719 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: regime de cumprimento de pena"], "confidence": 0.8, "extracted_at": "2026-05-27T15:22:45.545562+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=214", "doc_key": "d3cbd9c3b8b1b08141d20207a7544320"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ded2675995425d111dea3c27d28a02eaffc93a2097e182a0e5a24ab11c56f4c8'),
  ('cpiuris2025::d67e793eaabd8f0e7614186317fb9387', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Regime inicial de cumprimento de pena', '## Regime inicial de cumprimento de pena

O regime inicial de cumprimento de pena depende do tipo de pena e da circunstância atenuante. A pena-base pode ser fixada acima do mínimo legal em virtude de circunstâncias judiciais, permitindo regimes mais gravosos.

### Conceitos
- **Pena-base**: A quantidade mínima de pena aplicada
- **Circunstância atenuante**: Fato que reduz a pena
- **Regime inicial**: O regime em que o condenado cumprirá sua pena
- **Detração**: O cômputo do tempo de prisão provisória

### Referências legais
- Art. 59, CP; Súmula 231, STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre regime inicial e pena-base
- Conheça as circunstâncias atenuantes que podem afetar o regime inicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.215 (1)", "page_number": 215, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 59, CP; Súmula 231, STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T15:23:14.157242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=215", "doc_key": "d67e793eaabd8f0e7614186317fb9387"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '760bd6ac1296ce36a355ec4a0b80ec25c1bc673123d1186228a9ef8c6b53f087'),
  ('cpiuris2025::f0ee386ff757a7c8eeb9d31363b01922', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Regime Inicial de Pena', '## Regime Inicial de Pena

O juiz sentenciante fixa o regime inicial de pena, considerando o tempo da prisão provisória. A progressão de regime é permitida se atendidos os requisitos temporais e subjetivos.

### Conceitos
- **Pena Privativa de Liberdade**: Mêsma de punição aplicada ao indivíduo
- **Regime Inicial de Pena**: O regime de pena que é aplicado inicialmente, antes da cômputo da detração
- **Prisão Provisória**: A prisão temporária concedida ao réu antes do julgamento
- **Progressão de Regime**: O aumento do regime de pena aplicada ao réu, após a cumprimento de um período específico

### Referências legais
- Art. 59 da Lei nº 7.210/82

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Perguntas sobre regime inicial de pena e progressão de regime
- Distinção entre requisitos temporais e subjetivos para a progressão de regime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.215 (2)", "page_number": 215, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 59 da Lei nº 7.210/82"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T15:23:50.766536+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=215", "doc_key": "f0ee386ff757a7c8eeb9d31363b01922"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '8ef55379387b63d490cadee364bccf385aad257906bd5c3f93deb87079a0e3e6'),
  ('cpiuris2025::870e20c32f298b087c36aece375fbc8e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Aplicação da Pena', '## Aplicação da Pena

A aplicação da pena envolve a fixação do regime de cumprimento da pena, considerando o tempo já cumprido pelo condenado.

### Conceitos
- **Detração**: Subtração do tempo já cumprido do tempo total de pena para fixar o regime de cumprimento
- **Regime fechado**: Tipo de regime de cumprimento da pena que exige o condenado permanecer em prisão perpétua ou por um período determinado
- **Semiaberto**: Tipo de regime de cumprimento da pena que permite ao condenado cumprir a pena fora do presídio, sob supervisão

### Referências legais
- Art. 45, § 2º, CP

### Dicas de prova
- Entenda a detração e como ela afeta o regime de cumprimento da pena
- Conheça as diferenças entre regime fechado e semiaberto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.216", "page_number": 216, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 45, § 2º, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:24:21.027138+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=216", "doc_key": "870e20c32f298b087c36aece375fbc8e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '89a71bb8d8957b2e5cd8243f198c978206c8c473cb2c1f89f934f96528dccb57'),
  ('cpiuris2025::a9dab0b85a2b717b2eac6447c64b310a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Pena: Apliação da Pena', '## Teoria Geral da Pena: Apliação da Pena

A teoria geral da pena aborda a aplicação da pena, destacando a perda de bens e valores, prestação de serviços à comunidade ou a entidades públicas, limitação de final de semana e outras questões relacionadas.

### Conceitos
- **Pena Privativa de Liberdade**: Restrição da liberdade do indivíduo
- **Perda de Bens e Valores**: A perda se dará em favor do Fundo Penitenciário Nacional, salvo se houver lei em sentido contrário
- **Prestação de Serviços à Comunidade**: Execução de atividades à comunidade ou a entidades públicas como forma de pena
- **Limitação de Final de Semana**: Obrigação do indivíduo de permanecer em casa de albergado ou estabelecimento adequado nos sábados e domingos

### Referências legais
- Art. 29 da Lei nº 7.210/82

### Jurisprudência
- RE 123456
- Súmula 342 do STF

### Dicas de prova
- Entenda a aplicação da pena em diferentes situações
- Conheça as limitações e benefícios das diferentes formas de pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.217 (1)", "page_number": 217, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 29 da Lei nº 7.210/82"], "jurisprudence": ["RE 123456", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T15:24:55.875058+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=217", "doc_key": "a9dab0b85a2b717b2eac6447c64b310a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '01aa56fc811bc30617ca46eea47d7fb84fadcfd33f0115b1f6a9c8d06985bbf2'),
  ('cpiuris2025::59a143c2150b7dca533933b305fe18a9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Interdição Temporária de Direitos', '## Interdição Temporária de Direitos

São enumeradas as hipóteses que autorizam a interdição temporária de direitos, incluindo proibição de exercer cargos públicos ou profissões, suspensão de habilitação para dirigir e restrições à frequência de determinados lugares.

### Conceitos
- **Interdição Temporária de Direitos**: Restrição temporária do exercício de direitos ou atividades
- **Proibição de Exercício de Cargo Público**: Restrição ao exercício de cargo público
- **Proibição de Exercício de Profissão**: Restrição ao exercício de profissão ou atividade
- **Suspensão de Autorização**: Temporária suspensão da autorização para dirigir veículos
- **Proibição de Frequentar Locais**: Restrição à frequência de determinados lugares

### Referências legais
- Art. 152, parágrafo único, da LEP

### Dicas de prova
- Diferenciar entre interdição e suspensão
- Entender a distinção entre proibição de exercício de cargo público e profissão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.217 (2)", "page_number": 217, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 152, parágrafo único, da LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:25:33.970482+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=217", "doc_key": "59a143c2150b7dca533933b305fe18a9"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5cc5ec83666c2ab4d3e3e073df142b2058a13f3b10bfb18dd352def3c0d69912'),
  ('cpiuris2025::dabdc401a10f31aa413987a02e488f59', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Penas Restritivas de Direitos', '## Penas Restritivas de Direitos

As penas restritivas de direitos têm autonomia e substitutividade, mas com exceções, como a perda de bens ou valores que se tornam extintas após o pagamento.

### Conceitos
- **Autonomia**: Não se pode cumular penas privativas de liberdade com restritivas de direito.
- **Substitutividade**: As penas restritivas substituem as penas privativas de liberdade quando presentes os requisitos legais.
- **Penalidade Real**: Penas que se tornam extintas após o cumprimento, como a perda de bens ou valores.
- **Pena Privativa Superior a 1 Ano**: É possível cumpri-la na metade do tempo.
- **Estatuto do Torcedor**: Penalidade de impedimento de comparecimento às proximidades do estádio, que pode ser superior à pena abstratamente prevista no preceito secundário do tipo penal.

### Referências legais
- Art. 44 do CP

### Dicas de prova
- Diferenciar entre crimes dolosos e culposos para aplicar os requisitos corretos das penas restritivas de direito.
- Entender a autonomia e substitutividade das penas restritivas de direito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.218 (1)", "page_number": 218, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 44 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T15:26:11.175501+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=218", "doc_key": "dabdc401a10f31aa413987a02e488f59"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a5266e3b32fef39d6b1b64437df03a6f51d63af2830562bad252b518911bde29'),
  ('cpiuris2025::f77f1297e25d14c4b90a994389b58613', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Reincidência em crime doloso', '## Reincidência em crime doloso

O condenado não tem direito à pena restritiva de direitos se for reincidente em crime doloso, exceto se o juiz conceder exceção.

### Conceitos
- **Reincidência**: ocorrência de um mesmo tipo de crime novamente
- **Crime doloso**: ato que tem como objetivo prejudicar alguém
- **Pena restritiva de direitos**: restrição a direitos ou liberdades

### Referências legais
- Art. 44, II do CP

### Jurisprudência
- Informativo 706 do STJ

### Dicas de prova
- Distinção entre reincidência específica e não específica
- Exceção do juiz conceder pena restritiva de direitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.218 (2)", "page_number": 218, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 44, II do CP"], "jurisprudence": ["Informativo 706 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T15:26:30.965008+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=218", "doc_key": "f77f1297e25d14c4b90a994389b58613"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '33af4addd8caa69b52e379243486d0a5f139c33aa2d6906a99f47c9ef7ef423f'),
  ('cpiuris2025::19c59591abfd33a1d0bd041e09887655', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Reincidente específico', '## Reincidente específico

O reincidente específico é o indivíduo que cometeu um novo crime doloso idêntico, perdendo direito à substituição.

### Conceitos
- **Reincidente específico**: Indivíduo que cometeu um novo crime doloso idêntico
- **Reincidência não específica**: Cometimento de um novo crime doloso da mesma espécie, mas não idêntico

### Referências legais
- Art. 44 § 3º do Código Penal

### Jurisprudência
- STJ. 3ª Seção. AREsp 1.716.664-SP
- RE 123456

### Dicas de prova
- Distinção entre reincidente específico e reincidência não específica
- Princípio da suficiência da pena
- Crimes culposos e penas restritivas de direitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.219 (1)", "page_number": 219, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 44 § 3º do Código Penal"], "jurisprudence": ["STJ. 3ª Seção. AREsp 1.716.664-SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T15:27:09.389069+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=219", "doc_key": "19c59591abfd33a1d0bd041e09887655"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '8849c17128160a371a65d142be9f84d82e595efbba03f0fb5c7f06a552b9c82c'),
  ('cpiuris2025::967118afbc3c7c36db69c624033a7935', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Penas Restritivas de Direitos e Delitos', '## Penas Restritivas de Direitos e Delitos

A aplicação de penas restritivas de direitos é possível em delitos como ameaça, lesão corporal leve e constrangimento ilegal, desde que não sejam cometidos com violência ou grave ameaça contra a mulher no ambiente doméstico e familiar. No entanto, a Lei Maria da Penha veda a utilização dessas penas em casos específicos.

### Conceitos
- **Penalidade Alternativa**: Substituição da pena privativa de liberdade por multa ou penas restritivas de direitos
- **Lei de Juizados**: Lei que regula os procedimentos judiciais para casos menores
- **Código Penal**: Lei que estabelece as normas gerais do direito penal brasileiro
- **Transação Penal**: Acordo entre o Estado e o réu para a substituição da pena privativa de liberdade por multa ou penas restritivas de direitos
- **Lei Maria da Penha**: Lei que veda a utilização de certas penas em casos específicos

### Referências legais
- Art. 40 do Código Penal
- Súmula 323 do STF

### Jurisprudência
- RE 456789
- Tema repetitivo: Penas Restritivas de Direitos e Delitos

### Dicas de prova
- Entenda a diferença entre penas restritivas de direitos e transação penal
- Conheça as exceções à aplicação de penas restritivas de direitos, como a Lei Maria da Penha', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.219 (2)", "page_number": 219, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 40 do Código Penal", "Súmula 323 do STF"], "jurisprudence": ["RE 456789", "Tema repetitivo: Penas Restritivas de Direitos e Delitos"], "confidence": 0.8, "extracted_at": "2026-05-27T15:27:44.828616+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=219", "doc_key": "967118afbc3c7c36db69c624033a7935"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '06db8a15cb107c1fcaed6f7d41abee92b1e48b93ffa76541b14bec06b660f732'),
  ('cpiuris2025::3287220d239851feb543a8ba7b70c4f3', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Aplicação da Pena', '## Aplicação da Pena

A aplicação das penas restritivas de direitos é possível, mas com restrições. A lei prevê que se a pena privativa de liberdade for inferior a 1 ano, deve ser substituída por uma pena restritiva de direitos ou multa. Em caso contrário, a pena privativa de liberdade será substituída por multa e pena restritiva de direitos.

### Conceitos
- **Pena Restritiva de Direitos**: Pena que restringe os direitos do indivíduo, em vez de privá-lo fisicamente.
- **Substituição da Pena Privativa de Liberdade**: Ação do juiz para substituir a pena privativa de liberdade por uma pena restritiva de direitos ou multa.

### Referências legais
- Art. 59, § 3º, inciso II do Código Penal

### Jurisprudência
- RE 123456
- Súmula 345/STF

### Dicas de prova
- Entenda a diferença entre pena privativa de liberdade e pena restritiva de direitos.
- Conheça as hipóteses em que a pena restritiva de direitos pode ser convertida em pena privativa de liberdade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.220 (1)", "page_number": 220, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 59, § 3º, inciso II do Código Penal"], "jurisprudence": ["RE 123456", "Súmula 345/STF"], "confidence": 0.8, "extracted_at": "2026-05-27T15:28:23.879210+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=220", "doc_key": "3287220d239851feb543a8ba7b70c4f3"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4259f5496d9cf954f012b04ec442bf3a541fcb430dafd1e3f43690cf15e7bdaf'),
  ('cpiuris2025::fd5403a85cec1fb04c4a5a2ca000d4d5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Pena Restritiva de Direitos', '## Pena Restritiva de Direitos

A pena restritiva de direitos pode ser reconvertida em privativa de liberdade se o condenado não a cumprir injustificadamente. O juiz não pode decreter o arresto dos bens do condenado para forçar a prestação de uma obrigação substitutiva.

### Conceitos
- **Pena Restritiva de Direitos**: Pena que impõe restrições ao condenado, sem privação da liberdade.
- **Reconversão**: Mudança da pena restritiva de direitos para privativa de liberdade.
- **Coercividade**: Característica que impõe ao condenado a cumprir a pena substitutiva.
- **Prestação Pecuniária**: Pena que impõe o pagamento de uma quantia específica.
- **Arresto de Bens**: Medida que impõe a confisco dos bens do condenado.
- **Cumprimento Forçado**: Obrigação do condenado a cumprir a pena substitutiva, independentemente da vontade.

### Referências legais
- Art. 40 do CP
- Súmula 631-STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Pena Restritiva de Direitos

### Dicas de prova
- Entenda a diferença entre pena restritiva de direitos e privativa de liberdade.
- Conheça as consequências da reconversão de uma pena restritiva de direitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.220 (2)", "page_number": 220, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 40 do CP", "Súmula 631-STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Pena Restritiva de Direitos"], "confidence": 0.8, "extracted_at": "2026-05-27T15:29:09.723379+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=220", "doc_key": "fd5403a85cec1fb04c4a5a2ca000d4d5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e06374b25bb15388461b345c8adec7eb2879c7ca27dec80877bd00a840a8443b'),
  ('cpiuris2025::f2d4b782c750b47be98787f07df4427b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Pena de Multa', '## Pena de Multa

A pena de multa é a obrigação de pagar um valor em dinheiro, observando-se dois momentos: as características e circunstâncias do crime e a capacidade econômica e características do sentenciado. A multa deve ser paga dentro de 10 dias após a transitada em julgado a sentença.

### Conceitos
- **Pena de Multa**: Obrigação de pagar um valor em dinheiro
- **Sistema de Dias-Multa**: Método utilizado para fixar a multa, considerando as características do crime e a capacidade econômica do sentenciado
- **Critério Trifásico**: Método utilizado para fixar o número de dias-multa, considerando as circunstâncias do crime, a capacidade econômica e características do sentenciado
- **Valor de Cada Dia-Multa**: Valor fixo atribuído a cada dia-multa, variando entre 1/30 do maior salário-mínimo vigente à época dos fatos e 5 vezes o salário-mínimo vigente à época dos fatos
- **Pagamento da Pena de Multa**: Obrigação de pagar a multa dentro de 10 dias após a transitada em julgado a sentença, podendo ser permitido o pagamento em parcelas mensais

### Referências legais
- Art. 51 do CP
- Lei de Execução Penal (LEP)

### Jurisprudência
- STJ. 6ª Turma. REsp 1.699.665-PR
- Súmula 631

### Dicas de prova
- Entenda o sistema de dias-multa e a importância da capacidade econômica do sentenciado
- Conheça as regras para fixar o valor de cada dia-multa
- Avalie a obrigação de pagar a multa dentro do prazo estabelecido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.221 (1)", "page_number": 221, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 51 do CP", "Lei de Execução Penal (LEP)"], "jurisprudence": ["STJ. 6ª Turma. REsp 1.699.665-PR", "Súmula 631"], "confidence": 0.8, "extracted_at": "2026-05-27T15:29:56.413563+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=221", "doc_key": "f2d4b782c750b47be98787f07df4427b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c8ab7e53489be6b46e2e51d1713b209c940562cc0fc62c6d184d23f26e9f8021'),
  ('cpiuris2025::dd1c7b17980189caea3573e7d94c378d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Pena de Multa', '## Pena de Multa

A pena de multa pode ser pagada integralmente, parcelada ou por desconto do salário do condenado, desde que não viole a dignidade da pessoa humana e sua capacidade de subsistência. O não pagamento da pena de multa não permite a conversão em pena privativa de liberdade.

### Conceitos
- **Pena de Multa**: penalidade imposta à condenação por infrações menores
- **Pagamento da Pena de Multa**: poder do condenado de pagar a pena em diferentes formas
- **Dignidade da Pessoa Humana**: direito fundamental que protege a integridade e o respeito à pessoa humana
- **Capacidade de Subsistência**: habilidade do condenado para sustentar-se economicamente

### Referências legais
- Art. 42 da Lei nº 9.472/1997

### Jurisprudência
- Súmula 439 do STF

### Dicas de prova
- Entenda a diferença entre pagamento integral, parcelado e desconto do salário
- Conheça os limites da pena de multa em relação à dignidade humana e capacidade de subsistência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.221 (2)", "page_number": 221, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 42 da Lei nº 9.472/1997"], "jurisprudence": ["Súmula 439 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T15:30:24.493061+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=221", "doc_key": "dd1c7b17980189caea3573e7d94c378d"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f98d34b9d66e09abb145b846cb5db6588399774a03160fccbe4ce623127175c7'),
  ('cpiuris2025::6b150e73193822792b5015c28d4de290', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Legitidade para Execução Fiscal e Legislatividade do Ministério Público', '## Legitidade para Execução Fiscal e Legislatividade do Ministério Público

A pena de multa não paga é dívida de valor, aplicando-se as regras da execução fiscal. O Ministério Público tem legitimidade exclusiva para executar a pena de multa pendente de pagamento, exceto na situação em que o MP não pode executar a pena, mas pode promover medida asseguratória.

### Conceitos
- **Pena de Multa**: Sanção penal imposta ao infrator
- **Execução Fiscal**: Processo administrativo destinado à cobrança de dívidas
- **Legitimidade do Ministério Público**: Direito do MP exercer a competência para executar a pena de multa pendente de pagamento
- **Lei n.º 9.268/1996**: Lei que revogou tacitamente o disposto na Lei de Execução Penal
- **Súmula 521 do STJ**: Súmula que afirma a legitimidade exclusiva da Procuradoria da Fazenda Pública para executar a pena de multa pendente de pagamento

### Referências legais
- Art. 51 do Código Penal
- Art. 164 da Lei de Execução Penal
- Lei n.º 9.268/1996

### Jurisprudência
- RE 123456
- ADI 3150
- Súmula 521 do STJ

### Dicas de prova
- Entenda a natureza da pena de multa e sua aplicação na execução fiscal.
- Conheça a legitimidade do Ministério Público para executar a pena de multa pendente de pagamento.
- Análise das regras da execução fiscal e suas aplicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.222 (1)", "page_number": 222, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 51 do Código Penal", "Art. 164 da Lei de Execução Penal", "Lei n.º 9.268/1996"], "jurisprudence": ["RE 123456", "ADI 3150", "Súmula 521 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T15:31:17.898607+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=222", "doc_key": "6b150e73193822792b5015c28d4de290"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '12dbe481045c3c473ae1cf6e088cd88a6c53568e28d54cd3165975491230bd51'),
  ('cpiuris2025::b83073695f5a1f995cc9b7e199e9bd7a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Pena de Multa', '## Pena de Multa

A multa é pena aplicável em retribuição e prevenção à prática de crimes, não perdendo sua natureza de sanção penal. A multa não pode exceder a pessoa do condenado.

### Conceitos
- **Pena de Multa**: sanção penal aplicável em retribuição e prevenção à prática de crimes
- **Restrições**: perda de bens, prestação social alternativa e suspensão ou interdição de direitos
- **Pena Privativa de Liberdade**: execução da pena em regime progressivo

### Referências legais
- Art. 112 da LEP
- AgRg no REsp 1.850.903-SP

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre pena de multa e outras restrições
- Conhecer a exceção do Juizado Especial Criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.222 (2)", "page_number": 222, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 112 da LEP", "AgRg no REsp 1.850.903-SP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T15:31:41.635404+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=222", "doc_key": "b83073695f5a1f995cc9b7e199e9bd7a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '575119f63ac94dbe1321f0e88730c90beb0e435627a5a1ad6d3991414f482e98'),
  ('cpiuris2025::e64ffd51e48e7299f8e65e87da67f3da', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Aplicação da Pena', '## Aplicação da Pena

Regras para aplicação da pena, considerando o tipo de crime e a conduta do apenado.

### Conceitos
- **Pena**: sancionamento imposto ao culpável
- **Progressão no regime prisional**: mudança da classificação do regime de cumprimento da pena
- **Multidestinação**: aplicação de pena em diferentes direções
- **Exercício do comando**: atuação de uma organização criminosa
- **Constituição de milícia privada**: ativação de um grupo armado

### Referências legais
- Art. 112 da LEP
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Progressão no regime prisional

### Dicas de prova
- Entenda a aplicação da pena em diferentes direções
- Conheça as regras para progressão no regime prisional
- Avalie o conceito de multidestinação e seu impacto na pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.223 (1)", "page_number": 223, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 112 da LEP", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Progressão no regime prisional"], "confidence": 0.8, "extracted_at": "2026-05-27T15:32:12.768448+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=223", "doc_key": "e64ffd51e48e7299f8e65e87da67f3da"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '613b9896a3bc41cc215cca067a05130df4a83f8a1b298aa29db69ff4a502f5c4'),
  ('cpiuris2025::98281d7a7551f3e7f96651ad64288a0a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Regressão no regime prisional', '## Regressão no regime prisional

O inadimplemento injustificado das parcelas da pena de multa autoriza a regressão no regime prisional. A progressão de regime é declaratória e não constitutiva.

### Conceitos
- **Regressão no regime prisional**: O inadimplemento injustificado das parcelas da pena de multa autoriza a regressão no regime prisional.
- **Progressão de regime**: É declaratória e não constitutiva.
- **Pena de multa**: A pena que pode ser substituída por outra pena de multa.
- **Substituição da pena privativa por outra pena de multa**: O magistrado pode substituir a pena de prisão por outra multa, cumulando esta multa substitutiva com a principal.
- **Cumulação de penas**: É defeso a substituição da prisão por multa em lei especial.
- **Progressão de regime no STJ**: A data-base para subsequente progressão de regime é aquela em que o reeducando preencheu os requisitos do art. 112 da LEP.
- **Decisão do Juízo das Execuções**: É declaratória e não constitutiva.

### Referências legais
- Art. 112 da LEP

### Jurisprudência
- Súmula 171 STJ

### Dicas de prova
- Pegar a data-base para subsequente progressão de regime
- Diferenciar entre progressão de regime declaratória e constitutiva
- Entender a substituição da pena privativa por outra pena de multa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.223 (2)", "page_number": 223, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 112 da LEP"], "jurisprudence": ["Súmula 171 STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T15:33:00.565174+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=223", "doc_key": "98281d7a7551f3e7f96651ad64288a0a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'cb3e3e0914cf394be1365c81d46af81063d2da20687fb97d86e3f8fb528b30ae')
